            bytes1 char = bytes1(_unsafeReadBytesOffset(buffer, i));
            if (((SPECIAL_CHARS_LOOKUP & (1 << uint8(char))) != 0)) {
                output[outputLength++] = "\\";
                if (char == 0x08) output[outputLength++] = "b";
                else if (char == 0x09) output[outputLength++] = "t";
                else if (char == 0x0a) output[outputLength++] = "n";
                else if (char == 0x0c) output[outputLength++] = "f";
                else if (char == 0x0d) output[outputLength++] = "r";
                else if (char == 0x5c) output[outputLength++] = "\\";
                else if (char == 0x22) {
                    // solhint-disable-next-line quotes
                    output[outputLength++] = '"';
                }
            } else {
                output[outputLength++] = char;
            }
        }
        // write the actual length and deallocate unused memory
        assembly ("memory-safe") {
            mstore(output, outputLength)
            mstore(0x40, add(output, shl(5, shr(5, add(outputLength, 63)))))
        }

        return string(output);
    }

    /**
     * @dev Reads a bytes32 from a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeReadBytesOffset(bytes memory buffer, uint256 offset) private pure returns (bytes32 value) {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            value := mload(add(add(buffer, 0x20), offset))
        }
    }
}

contracts/AntiCheatingSystem.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract AntiCheatingSystem is AccessControl, Pausable {
    bytes32 public constant VALIDATOR_ROLE = keccak256("VALIDATOR_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    struct CheatingReport {
        uint256 id;
        address reporter;
        address accused;
        string cheatingType; // "plagiarism", "collusion", "fake_submission", "bot_activity"
        string evidenceHash; // IPFS hash of evidence
        string description;
        uint256 severity; // 1-5 scale
        bool isVerified;
        bool isPenalized;
        address verifiedBy;
        uint256 reportedAt;
        uint256 verifiedAt;
    }

    struct StudentRiskProfile {
        address studentAddress;
        uint256 riskScore; // 0-1000 scale
        uint256 totalReports;
        uint256 verifiedViolations;
        mapping(string => uint256) violationCounts; // cheating type => count
        uint256[] reportIds;
        bool isBlacklisted;
        uint256 lastViolationTime;
        uint256 suspensionEndTime;
    }

    struct AIDetectionResult {
        uint256 submissionId;
        address student;
        string submissionHash;
        uint256 plagiarismScore; // 0-100
        uint256 aiGeneratedScore; // 0-100
        uint256 similarityScore; // 0-100
        string[] similarSubmissions;
        bool requiresHumanReview;
        bool isApproved;
        uint256 analyzedAt;
    }

    struct BehaviorPattern {
        address student;
        uint256 submissionFrequency; // submissions per day
        uint256 averageCompletionTime; // in minutes
        uint256 consistencyScore; // How consistent is their work quality
        uint256 timePattern; // What times do they usually work
        uint256[] recentSubmissionTimes;
        bool isPotentialBot;
        uint256 lastAnalyzed;
    }

    mapping(uint256 => CheatingReport) public cheatingReports;
    mapping(address => StudentRiskProfile) private studentRiskProfiles;
    mapping(uint256 => AIDetectionResult) public aiDetectionResults;
    mapping(address => BehaviorPattern) private behaviorPatterns;
    mapping(string => uint256[]) public submissionHashes; // hash => submission IDs

    uint256 private _reportIds;
    uint256 private _detectionIds;

    // Thresholds
    uint256 public constant HIGH_RISK_THRESHOLD = 700;
    uint256 public constant BLACKLIST_THRESHOLD = 900;
    uint256 public constant SUSPENSION_DURATION = 30 days;
    uint256 public constant BOT_DETECTION_THRESHOLD = 80;

    event CheatingReported(uint256 indexed reportId, address indexed accused, string cheatingType);
    event ViolationVerified(uint256 indexed reportId, address indexed accused, uint256 penalty);
    event StudentSuspended(address indexed student, uint256 duration);
    event BotActivityDetected(address indexed student, uint256 confidence);
    event RiskScoreUpdated(address indexed student, uint256 oldScore, uint256 newScore);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(VALIDATOR_ROLE, msg.sender);
    }

    function reportCheating(
        address accused,
        string memory cheatingType,
        string memory evidenceHash,
        string memory description,
        uint256 severity
    ) external whenNotPaused returns (uint256) {
        require(accused != msg.sender, "Cannot report yourself");
        require(severity >= 1 && severity <= 5, "Invalid severity level");
        require(bytes(evidenceHash).length > 0, "Evidence required");

        _reportIds++;
        uint256 reportId = _reportIds;

        cheatingReports[reportId] = CheatingReport({
            id: reportId,
            reporter: msg.sender,
            accused: accused,
            cheatingType: cheatingType,
            evidenceHash: evidenceHash,
            description: description,
            severity: severity,
            isVerified: false,
            isPenalized: false,
            verifiedBy: address(0),
            reportedAt: block.timestamp,
            verifiedAt: 0
        });

        // Update risk profile
        StudentRiskProfile storage profile = studentRiskProfiles[accused];
        profile.totalReports++;
        profile.reportIds.push(reportId);

        // Increase risk score based on severity
        uint256 riskIncrease = severity * 50; // 50-250 points per report
        _updateRiskScore(accused, riskIncrease, true);

        emit CheatingReported(reportId, accused, cheatingType);
        return reportId;
    }

    function verifyReport(uint256 reportId, bool isValid) 
        external onlyRole(VALIDATOR_ROLE) whenNotPaused {
        CheatingReport storage report = cheatingReports[reportId];
        require(!report.isVerified, "Report already verified");
        require(report.id != 0, "Report does not exist");

        report.isVerified = true;
        report.verifiedBy = msg.sender;
        report.verifiedAt = block.timestamp;

        if (isValid) {
            // Apply penalties
            _applyPenalty(report.accused, report.cheatingType, report.severity);
            report.isPenalized = true;

            emit ViolationVerified(reportId, report.accused, report.severity);
        } else {
            // Remove risk score increase from false report
            uint256 riskDecrease = report.severity * 50;
            _updateRiskScore(report.accused, riskDecrease, false);
        }
    }

    function _applyPenalty(address student, string memory cheatingType, uint256 severity) private {
        StudentRiskProfile storage profile = studentRiskProfiles[student];
        profile.verifiedViolations++;
        profile.violationCounts[cheatingType]++;
        profile.lastViolationTime = block.timestamp;

        // Increase risk score significantly for verified violations
        uint256 penaltyScore = severity * 100; // 100-500 points
        _updateRiskScore(student, penaltyScore, true);

        // Apply additional penalties based on severity and type
        if (severity >= 4) {
            // Suspend for high severity violations
            profile.suspensionEndTime = block.timestamp + SUSPENSION_DURATION;
            emit StudentSuspended(student, SUSPENSION_DURATION);
        }

        // Blacklist for repeated violations
        if (profile.verifiedViolations >= 3 || profile.riskScore >= BLACKLIST_THRESHOLD) {
            profile.isBlacklisted = true;
        }
    }

    function _updateRiskScore(address student, uint256 scoreChange, bool increase) private {
        StudentRiskProfile storage profile = studentRiskProfiles[student];
        uint256 oldScore = profile.riskScore;

        if (increase) {
            profile.riskScore += scoreChange;
            if (profile.riskScore > 1000) profile.riskScore = 1000;
        } else {
            if (profile.riskScore > scoreChange) {
                profile.riskScore -= scoreChange;
            } else {
                profile.riskScore = 0;
            }
        }

        emit RiskScoreUpdated(student, oldScore, profile.riskScore);
    }

    function analyzeSubmission(
        uint256 submissionId,
        address student,
        string memory submissionHash,
        string memory submissionContent
    ) external onlyRole(VALIDATOR_ROLE) whenNotPaused returns (uint256) {
        _detectionIds++;
        uint256 detectionId = _detectionIds;

        // Perform AI-based analysis (simplified implementation)
        (uint256 plagiarismScore, uint256 aiScore, uint256 similarityScore, bool requiresReview) = 
            _performAIAnalysis(submissionHash, submissionContent);

        aiDetectionResults[detectionId] = AIDetectionResult({
            submissionId: submissionId,
            student: student,
            submissionHash: submissionHash,
            plagiarismScore: plagiarismScore,
            aiGeneratedScore: aiScore,
            similarityScore: similarityScore,
            similarSubmissions: new string[](0),
            requiresHumanReview: requiresReview,
            isApproved: !requiresReview && plagiarismScore < 50,
            analyzedAt: block.timestamp
        });

        // Update behavior tracking
        _updateBehaviorPattern(student);

        // Store submission hash for similarity checking
        submissionHashes[submissionHash].push(detectionId);

        // Flag potential cheating if scores are high
        if (plagiarismScore > 80 || aiScore > 80) {
            _flagAutomaticViolation(student, plagiarismScore > aiScore ? "plagiarism" : "ai_generation");
        }

        return detectionId;
    }

    function _performAIAnalysis(string memory submissionHash, string memory content) 
        private view returns (uint256 plagiarismScore, uint256 aiScore, uint256 similarityScore, bool requiresReview) {
        // Simplified AI analysis simulation
        // In production, this would integrate with AI services like GPTZero, Copyleaks, etc.

        // Mock plagiarism detection based on hash similarity
        uint256[] memory similarHashes = submissionHashes[submissionHash];
        if (similarHashes.length > 0) {
            plagiarismScore = 95; // High plagiarism if exact hash match
        } else {
            plagiarismScore = uint256(keccak256(abi.encodePacked(content, block.timestamp))) % 40; // 0-39 random
        }

        // Mock AI generation detection
        aiScore = uint256(keccak256(abi.encodePacked(content, "AI_CHECK"))) % 60; // 0-59 random

        // Mock similarity scoring
        similarityScore = (plagiarismScore + aiScore) / 2;

        // Requires human review if any score is concerning
        requiresReview = plagiarismScore > 50 || aiScore > 60 || similarityScore > 55;
    }

    function _updateBehaviorPattern(address student) private {
        BehaviorPattern storage pattern = behaviorPatterns[student];

        // Track submission timing
        pattern.recentSubmissionTimes.push(block.timestamp);

        // Keep only last 10 submissions
        if (pattern.recentSubmissionTimes.length > 10) {
            for (uint256 i = 0; i < 9; i++) {
                pattern.recentSubmissionTimes[i] = pattern.recentSubmissionTimes[i + 1];
            }
            pattern.recentSubmissionTimes.pop();
        }

        // Analyze for bot behavior
        if (pattern.recentSubmissionTimes.length >= 5) {
            uint256 botScore = _calculateBotLikelihood(student);
            if (botScore > BOT_DETECTION_THRESHOLD) {
                pattern.isPotentialBot = true;
                emit BotActivityDetected(student, botScore);

                // Increase risk score for bot activity
                _updateRiskScore(student, 300, true);
            }
        }

        pattern.lastAnalyzed = block.timestamp;
    }

    function _calculateBotLikelihood(address student) private view returns (uint256) {
        BehaviorPattern storage pattern = behaviorPatterns[student];
        uint256 botScore = 0;

        // Check submission timing patterns
        if (pattern.recentSubmissionTimes.length >= 3) {
            uint256[] memory intervals = new uint256[](pattern.recentSubmissionTimes.length - 1);

            for (uint256 i = 1; i < pattern.recentSubmissionTimes.length; i++) {
                intervals[i - 1] = pattern.recentSubmissionTimes[i] - pattern.recentSubmissionTimes[i - 1];
            }

            // Check for extremely regular intervals (bot-like)
            bool tooRegular = true;
            uint256 avgInterval = intervals[0];

            for (uint256 i = 1; i < intervals.length; i++) {
                if (intervals[i] > avgInterval * 12 / 10 || intervals[i] < avgInterval * 8 / 10) {
                    tooRegular = false;
                    break;
                }
            }

            if (tooRegular) {
                botScore += 50;
            }

            // Check for unrealistic completion times (too fast)
            if (avgInterval < 5 minutes) {
                botScore += 40;
            }
        }

        return botScore;
    }

    function _flagAutomaticViolation(address student, string memory violationType) private {
        // Create automatic report for high-confidence violations
        _reportIds++;
        uint256 reportId = _reportIds;

        cheatingReports[reportId] = CheatingReport({
            id: reportId,
            reporter: address(this), // System-generated report
            accused: student,
            cheatingType: violationType,
            evidenceHash: "AUTO_DETECTED",
            description: "Automatically detected by AI system",
            severity: 3,
            isVerified: true,
            isPenalized: false,
            verifiedBy: address(this),
            reportedAt: block.timestamp,
            verifiedAt: block.timestamp
        });

        _applyPenalty(student, violationType, 3);
    }

    // View functions
    function getStudentRiskProfile(address student) external view returns (
        uint256 riskScore,
        uint256 totalReports,
        uint256 verifiedViolations,
        bool isBlacklisted,
        bool isSuspended
    ) {
        StudentRiskProfile storage profile = studentRiskProfiles[student];
        bool suspended = block.timestamp < profile.suspensionEndTime;

        return (
            profile.riskScore,
            profile.totalReports,
            profile.verifiedViolations,
            profile.isBlacklisted,
            suspended
        );
    }

    function getCheatingReport(uint256 reportId) external view returns (CheatingReport memory) {
        return cheatingReports[reportId];
    }

    function getAIDetectionResult(uint256 detectionId) external view returns (AIDetectionResult memory) {
        return aiDetectionResults[detectionId];
    }

    function getBehaviorPattern(address student) external view returns (
        uint256 submissionFrequency,
        uint256 averageCompletionTime,
        bool isPotentialBot,
        uint256 lastAnalyzed
    ) {
        BehaviorPattern storage pattern = behaviorPatterns[student];
        return (
            pattern.submissionFrequency,
            pattern.averageCompletionTime,
            pattern.isPotentialBot,
            pattern.lastAnalyzed
        );
    }

    function canParticipate(address student) external view returns (bool, string memory reason) {
        StudentRiskProfile storage profile = studentRiskProfiles[student];

        if (profile.isBlacklisted) {
            return (false, "Student is blacklisted");
        }

        if (block.timestamp < profile.suspensionEndTime) {
            return (false, "Student is suspended");
        }

        if (profile.riskScore >= HIGH_RISK_THRESHOLD) {
            return (false, "High risk score - requires review");
        }

        return (true, "");
    }

    function getViolationCount(address student, string memory cheatingType) 
        external view returns (uint256) {
        return studentRiskProfiles[student].violationCounts[cheatingType];
    }

    function getStudentReports(address student) external view returns (uint256[] memory) {
        return studentRiskProfiles[student].reportIds;
    }

    // Admin functions
    function setRiskScore(address student, uint256 newScore) external onlyRole(ADMIN_ROLE) {
        require(newScore <= 1000, "Risk score too high");
        uint256 oldScore = studentRiskProfiles[student].riskScore;
        studentRiskProfiles[student].riskScore = newScore;

        emit RiskScoreUpdated(student, oldScore, newScore);
    }

    function removeFromBlacklist(address student) external onlyRole(ADMIN_ROLE) {
        studentRiskProfiles[student].isBlacklisted = false;
        studentRiskProfiles[student].riskScore = HIGH_RISK_THRESHOLD - 1;
    }

    function endSuspension(address student) external onlyRole(ADMIN_ROLE) {
        studentRiskProfiles[student].suspensionEndTime = 0;
    }

    function updateDetectionThresholds(
        uint256 _highRiskThreshold,
        uint256 _blacklistThreshold,
        uint256 _botThreshold
    ) external onlyRole(ADMIN_ROLE) {
        // These would be implemented as state variables that can be modified
        // Simplified for this implementation
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

contracts/CrossBootcampRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract CrossBootcampRegistry is AccessControl, Pausable {
    bytes32 public constant REGISTRY_ADMIN_ROLE = keccak256("REGISTRY_ADMIN_ROLE");
    bytes32 public constant BOOTCAMP_ADMIN_ROLE = keccak256("BOOTCAMP_ADMIN_ROLE");

    struct BootcampRegistry {
        uint256 id;
        address contractAddress;
        string name;
        string description;
        address admin;
        string[] supportedSkills;
        mapping(string => uint256) skillWeights; // skill => importance weight
        bool isActive;
        bool isVerified;
        uint256 registeredAt;
        uint256 totalGraduates;
        uint256 averageRating;
    }

    struct BadgeRecognition {
        uint256 sourceBootcampId;
        uint256 targetBootcampId;
        uint256 sourceBadgeId;
        string recognizedSkill;
        uint256 equivalentLevel; // 0-4
        uint256 creditValue; // How much credit this gives in target bootcamp
        bool isActive;
        address verifiedBy;
        uint256 createdAt;
    }

    struct StudentProfile {
        address studentAddress;
        mapping(uint256 => uint256[]) bootcampBadges; // bootcampId => badge IDs
        mapping(string => uint256) aggregatedSkills; // skill => total level across all bootcamps
        mapping(uint256 => bool) completedBootcamps;
        uint256[] participatedBootcamps;
        uint256 totalCrossCredits;
        bool isPortable;
    }

    struct SkillStandard {
        string skillName;
        string category;
        string description;
        mapping(uint256 => string) levelDescriptions; // level => description
        uint256 totalBootcampsUsing;
        bool isStandardized;
        address standardizedBy;
        uint256 createdAt;
    }

    struct TransferRequest {
        uint256 id;
        address student;
        uint256 sourceBootcampId;
        uint256 targetBootcampId;
        uint256[] sourceBadgeIds;
        uint256 requestedCredits;
        string justification;
        bool isApproved;
        bool isProcessed;
        address approvedBy;
        uint256 createdAt;
        uint256 processedAt;
    }

    mapping(uint256 => BootcampRegistry) private bootcampRegistries;
    mapping(address => uint256) public contractToBootcampId;
    mapping(uint256 => mapping(uint256 => BadgeRecognition)) public badgeRecognitions;
    mapping(address => StudentProfile) private studentProfiles;
    mapping(string => SkillStandard) private skillStandards;
    mapping(uint256 => TransferRequest) public transferRequests;
    mapping(string => uint256[]) public skillBootcamps; // skill => bootcamp IDs that teach it

    uint256 private _bootcampIds;
    uint256 private _transferRequestIds;

    string[] public standardizedSkills;
    uint256[] public registeredBootcamps;

    event BootcampRegistered(uint256 indexed bootcampId, address contractAddress, string name);
    event BadgeRecognitionCreated(uint256 indexed sourceBootcamp, uint256 indexed targetBootcamp, string skill);
    event SkillStandardized(string skillName, address standardizedBy);
    event TransferRequested(uint256 indexed requestId, address student, uint256 sourceBootcamp, uint256 targetBootcamp);
    event TransferApproved(uint256 indexed requestId, uint256 creditsGranted);
    event CrossCreditsAwarded(address indexed student, uint256 bootcampId, uint256 credits);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(REGISTRY_ADMIN_ROLE, msg.sender);

        // Initialize common skill standards
        _initializeSkillStandards();
    }

    function _initializeSkillStandards() private {
        _createSkillStandard("Solidity Development", "Blockchain", "Smart contract development with Solidity");
        _createSkillStandard("Web3 Frontend", "Frontend", "Building decentralized application interfaces");
        _createSkillStandard("DeFi Protocols", "Finance", "Decentralized finance mechanisms and protocols");
        _createSkillStandard("JavaScript", "Programming", "JavaScript programming language");
        _createSkillStandard("React Development", "Frontend", "React.js application development");
        _createSkillStandard("Python Programming", "Programming", "Python programming language");
        _createSkillStandard("Database Design", "Backend", "Database architecture and management");
        _createSkillStandard("API Development", "Backend", "RESTful API design and implementation");
    }

    function _createSkillStandard(string memory skillName, string memory category, string memory description) private {
        SkillStandard storage standard = skillStandards[skillName];
        standard.skillName = skillName;
        standard.category = category;
        standard.description = description;
        standard.totalBootcampsUsing = 0;
        standard.isStandardized = true;
        standard.standardizedBy = msg.sender;
        standard.createdAt = block.timestamp;

        // Set level descriptions
        standard.levelDescriptions[0] = "No knowledge";
        standard.levelDescriptions[1] = "Basic understanding";
        standard.levelDescriptions[2] = "Intermediate proficiency";
        standard.levelDescriptions[3] = "Advanced skills";
        standard.levelDescriptions[4] = "Expert level";

        standardizedSkills.push(skillName);

        emit SkillStandardized(skillName, msg.sender);
    }

    function registerBootcamp(
        address contractAddress,
        string memory name,
        string memory description,
        string[] memory supportedSkills,
        uint256[] memory skillWeights
    ) external onlyRole(REGISTRY_ADMIN_ROLE) whenNotPaused returns (uint256) {
        require(contractAddress != address(0), "Invalid contract address");
        require(bytes(name).length > 0, "Name cannot be empty");
        require(contractToBootcampId[contractAddress] == 0, "Contract already registered");
        require(supportedSkills.length == skillWeights.length, "Skills and weights length mismatch");

        _bootcampIds++;
        uint256 bootcampId = _bootcampIds;

        BootcampRegistry storage registry = bootcampRegistries[bootcampId];
        registry.id = bootcampId;
        registry.contractAddress = contractAddress;
        registry.name = name;
        registry.description = description;
        registry.admin = msg.sender;
        registry.supportedSkills = supportedSkills;
        registry.isActive = true;
        registry.isVerified = false; // Requires separate verification
        registry.registeredAt = block.timestamp;
        registry.totalGraduates = 0;
        registry.averageRating = 0;

        // Set skill weights
        for (uint256 i = 0; i < supportedSkills.length; i++) {
            registry.skillWeights[supportedSkills[i]] = skillWeights[i];
            skillBootcamps[supportedSkills[i]].push(bootcampId);
        }

        contractToBootcampId[contractAddress] = bootcampId;
        registeredBootcamps.push(bootcampId);

        _grantRole(BOOTCAMP_ADMIN_ROLE, msg.sender);

        emit BootcampRegistered(bootcampId, contractAddress, name);
        return bootcampId;
    }

    function createBadgeRecognition(
        uint256 sourceBootcampId,
        uint256 targetBootcampId,
        uint256 sourceBadgeId,
        string memory recognizedSkill,
        uint256 equivalentLevel,
        uint256 creditValue
    ) external onlyRole(BOOTCAMP_ADMIN_ROLE) whenNotPaused {
        require(bootcampRegistries[sourceBootcampId].isActive, "Source bootcamp not active");
        require(bootcampRegistries[targetBootcampId].isActive, "Target bootcamp not active");
        require(equivalentLevel <= 4, "Invalid equivalent level");
        require(_isBootcampAdmin(msg.sender, targetBootcampId), "Not target bootcamp admin");

        badgeRecognitions[sourceBootcampId][targetBootcampId] = BadgeRecognition({
            sourceBootcampId: sourceBootcampId,
            targetBootcampId: targetBootcampId,
            sourceBadgeId: sourceBadgeId,
            recognizedSkill: recognizedSkill,
            equivalentLevel: equivalentLevel,
            creditValue: creditValue,
            isActive: true,
            verifiedBy: msg.sender,
            createdAt: block.timestamp
        });

        emit BadgeRecognitionCreated(sourceBootcampId, targetBootcampId, recognizedSkill);
    }

    function requestCrossBootcampTransfer(
        uint256 sourceBootcampId,
        uint256 targetBootcampId,
        uint256[] memory sourceBadgeIds,
        string memory justification
    ) external whenNotPaused returns (uint256) {
        require(bootcampRegistries[sourceBootcampId].isActive, "Source bootcamp not active");
        require(bootcampRegistries[targetBootcampId].isActive, "Target bootcamp not active");
        require(sourceBadgeIds.length > 0, "Must provide source badges");

        // Verify student owns these badges (simplified - would check with badge contract)
        // require(_verifyBadgeOwnership(msg.sender, sourceBootcampId, sourceBadgeIds), "Badge ownership verification failed");

        _transferRequestIds++;
        uint256 requestId = _transferRequestIds;

        // Calculate requested credits based on badge recognition
        uint256 requestedCredits = _calculateTransferCredits(sourceBootcampId, targetBootcampId, sourceBadgeIds);

        transferRequests[requestId] = TransferRequest({
            id: requestId,
            student: msg.sender,
            sourceBootcampId: sourceBootcampId,
            targetBootcampId: targetBootcampId,
            sourceBadgeIds: sourceBadgeIds,
            requestedCredits: requestedCredits,
            justification: justification,
            isApproved: false,
            isProcessed: false,
            approvedBy: address(0),
            createdAt: block.timestamp,
            processedAt: 0
        });

        emit TransferRequested(requestId, msg.sender, sourceBootcampId, targetBootcampId);
        return requestId;
    }

    function approveTransferRequest(uint256 requestId, uint256 creditsGranted) 
        external onlyRole(BOOTCAMP_ADMIN_ROLE) whenNotPaused {
        TransferRequest storage request = transferRequests[requestId];
        require(!request.isProcessed, "Request already processed");
        require(_isBootcampAdmin(msg.sender, request.targetBootcampId), "Not target bootcamp admin");
        require(creditsGranted <= request.requestedCredits, "Credits exceed requested amount");

        request.isApproved = true;
        request.isProcessed = true;
        request.approvedBy = msg.sender;
        request.processedAt = block.timestamp;

        // Award cross-credits to student
        StudentProfile storage profile = studentProfiles[request.student];
        profile.totalCrossCredits += creditsGranted;

        // Update aggregated skills based on transferred badges
        _updateAggregatedSkills(request.student, request.sourceBootcampId, request.sourceBadgeIds);

        emit TransferApproved(requestId, creditsGranted);
        emit CrossCreditsAwarded(request.student, request.targetBootcampId, creditsGranted);
    }

    function _calculateTransferCredits(
        uint256 sourceBootcampId,
        uint256 targetBootcampId,
        uint256[] memory sourceBadgeIds
    ) private view returns (uint256) {
        uint256 totalCredits = 0;

        for (uint256 i = 0; i < sourceBadgeIds.length; i++) {
            BadgeRecognition memory recognition = badgeRecognitions[sourceBootcampId][targetBootcampId];
            if (recognition.isActive && recognition.sourceBadgeId == sourceBadgeIds[i]) {
                totalCredits += recognition.creditValue;
            }
        }

        // If no specific recognitions, calculate based on skill overlap
        if (totalCredits == 0) {
            totalCredits = _calculateSkillOverlapCredits(sourceBootcampId, targetBootcampId, sourceBadgeIds);
        }

        return totalCredits;
    }

    function _calculateSkillOverlapCredits(
        uint256 sourceBootcampId,
        uint256 targetBootcampId,
        uint256[] memory sourceBadgeIds
    ) private view returns (uint256) {
        // This would analyze skill overlap between bootcamps
        // Simplified implementation
        BootcampRegistry storage sourceBootcamp = bootcampRegistries[sourceBootcampId];
        BootcampRegistry storage targetBootcamp = bootcampRegistries[targetBootcampId];

        uint256 overlapScore = 0;
        uint256 commonSkills = 0;

        for (uint256 i = 0; i < sourceBootcamp.supportedSkills.length; i++) {
            string memory sourceSkill = sourceBootcamp.supportedSkills[i];

            for (uint256 j = 0; j < targetBootcamp.supportedSkills.length; j++) {
                if (keccak256(bytes(sourceSkill)) == keccak256(bytes(targetBootcamp.supportedSkills[j]))) {
                    commonSkills++;
                    overlapScore += sourceBootcamp.skillWeights[sourceSkill];
                    break;
                }
            }
        }

        // Calculate credits based on overlap (max 50% of badge count)
        uint256 maxCredits = sourceBadgeIds.length * 50 / 100;
        uint256 calculatedCredits = (overlapScore * sourceBadgeIds.length) / 1000;

        return calculatedCredits > maxCredits ? maxCredits : calculatedCredits;
    }

    function _updateAggregatedSkills(
        address student,
        uint256 sourceBootcampId,
        uint256[] memory sourceBadgeIds
    ) private {
        StudentProfile storage profile = studentProfiles[student];
        BootcampRegistry storage bootcamp = bootcampRegistries[sourceBootcampId];

        // For each skill supported by the source bootcamp, increase aggregated level
        for (uint256 i = 0; i < bootcamp.supportedSkills.length; i++) {
            string memory skill = bootcamp.supportedSkills[i];
            uint256 currentLevel = profile.aggregatedSkills[skill];

            // Increase skill level based on number of relevant badges (simplified)
            uint256 skillIncrease = sourceBadgeIds.length / 2; // 2 badges = 1 skill level
            if (skillIncrease == 0) skillIncrease = 1;

            uint256 newLevel = currentLevel + skillIncrease;
            if (newLevel > 4) newLevel = 4; // Cap at expert level

            profile.aggregatedSkills[skill] = newLevel;
        }

        // Mark participation in source bootcamp
        if (!profile.completedBootcamps[sourceBootcampId]) {
            profile.participatedBootcamps.push(sourceBootcampId);
        }
    }

    function _isBootcampAdmin(address admin, uint256 bootcampId) private view returns (bool) {
        return bootcampRegistries[bootcampId].admin == admin || hasRole(REGISTRY_ADMIN_ROLE, admin);
    }

    function enablePortability(bool isPortable) external {
        studentProfiles[msg.sender].isPortable = isPortable;
    }

    // View functions
    function getBootcampRegistry(uint256 bootcampId) external view returns (
        uint256 id,
        address contractAddress,
        string memory name,
        string memory description,
        address admin,
        string[] memory supportedSkills,
        bool isActive,
        bool isVerified,
        uint256 registeredAt,
        uint256 totalGraduates,
        uint256 averageRating
    ) {
        BootcampRegistry storage registry = bootcampRegistries[bootcampId];
        return (
            registry.id,
            registry.contractAddress,
            registry.name,
            registry.description,
            registry.admin,
            registry.supportedSkills,
            registry.isActive,
            registry.isVerified,
            registry.registeredAt,
            registry.totalGraduates,
            registry.averageRating
        );
    }

    function getBadgeRecognition(uint256 sourceBootcampId, uint256 targetBootcampId) 
        external view returns (BadgeRecognition memory) {
        return badgeRecognitions[sourceBootcampId][targetBootcampId];
    }

    function getStudentProfile(address student) external view returns (
        uint256[] memory participatedBootcamps,
        uint256 totalCrossCredits,
        bool isPortable
    ) {
        StudentProfile storage profile = studentProfiles[student];
        return (
            profile.participatedBootcamps,
            profile.totalCrossCredits,
            profile.isPortable
        );
    }

    function getStudentAggregatedSkills(address student) external view returns (
        string[] memory skills,
        uint256[] memory levels
    ) {
        skills = standardizedSkills;
        levels = new uint256[](skills.length);

        for (uint256 i = 0; i < skills.length; i++) {
            levels[i] = studentProfiles[student].aggregatedSkills[skills[i]];
        }
    }

    function getSkillStandard(string memory skillName) external view returns (
        string memory category,
        string memory description,
        uint256 totalBootcampsUsing,
        bool isStandardized,
        address standardizedBy,
        uint256 createdAt
    ) {
        SkillStandard storage standard = skillStandards[skillName];
        return (
            standard.category,
            standard.description,
            standard.totalBootcampsUsing,
            standard.isStandardized,
            standard.standardizedBy,
            standard.createdAt
        );
    }

    function getBootcampsForSkill(string memory skill) external view returns (uint256[] memory) {
        return skillBootcamps[skill];
    }

    function getTransferRequest(uint256 requestId) external view returns (TransferRequest memory) {
        return transferRequests[requestId];
    }

    function getRegisteredBootcamps() external view returns (uint256[] memory) {
        return registeredBootcamps;
    }

    function getStandardizedSkills() external view returns (string[] memory) {
        return standardizedSkills;
    }

    function canTransferBadges(
        address student,
        uint256 sourceBootcampId,
        uint256 targetBootcampId,
        uint256[] memory sourceBadgeIds
    ) external view returns (bool canTransfer, uint256 estimatedCredits, string memory reason) {
        if (!studentProfiles[student].isPortable) {
            return (false, 0, "Student has not enabled portability");
        }

        if (!bootcampRegistries[sourceBootcampId].isActive) {
            return (false, 0, "Source bootcamp not active");
        }

        if (!bootcampRegistries[targetBootcampId].isActive) {
            return (false, 0, "Target bootcamp not active");
        }

        uint256 credits = _calculateTransferCredits(sourceBootcampId, targetBootcampId, sourceBadgeIds);

        if (credits == 0) {
            return (false, 0, "No transferable credits found");
        }

        return (true, credits, "Transfer possible");
    }

    // Admin functions
    function verifyBootcamp(uint256 bootcampId, bool isVerified) 
        external onlyRole(REGISTRY_ADMIN_ROLE) {
        require(bootcampRegistries[bootcampId].id != 0, "Bootcamp not registered");
        bootcampRegistries[bootcampId].isVerified = isVerified;
    }

    function createSkillStandard(
        string memory skillName,
        string memory category,
        string memory description
    ) external onlyRole(REGISTRY_ADMIN_ROLE) {
        require(!skillStandards[skillName].isStandardized, "Skill already standardized");
        _createSkillStandard(skillName, category, description);
    }

    function updateBootcampRating(uint256 bootcampId, uint256 newRating) 
        external onlyRole(REGISTRY_ADMIN_ROLE) {
        require(bootcampRegistries[bootcampId].id != 0, "Bootcamp not registered");
        require(newRating <= 500, "Rating too high"); // Max 5.00 * 100
        bootcampRegistries[bootcampId].averageRating = newRating;
    }

    function pause() external onlyRole(REGISTRY_ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(REGISTRY_ADMIN_ROLE) {
        _unpause();
    }
}

contracts/DecentralizedVerification.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract DecentralizedVerification is AccessControl, ReentrancyGuard, Pausable {
    bytes32 public constant VALIDATOR_ROLE = keccak256("VALIDATOR_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    struct VerificationRequest {
        uint256 id;
        address student;
        string submissionType; // "assignment", "project", "milestone"
        string submissionHash; // IPFS hash
        uint256 requiredValidators;
        uint256 currentValidators;
        mapping(address => bool) hasValidated;
        mapping(address => VerificationVote) votes;
        address[] validatorList;
        bool isCompleted;
        bool isPassed;
        uint256 createdAt;
        uint256 completedAt;
    }

    struct VerificationVote {
        address validator;
        bool isApproved;
        uint256 confidence; // 0-100
        string feedback;
        string evidenceHash;
        uint256 votedAt;
    }

    struct ValidatorProfile {
        address validatorAddress;
        uint256 totalVerifications;
        uint256 correctVerifications;
        uint256 accuracyRate; // 0-1000 (0-100%)
        uint256 stakingAmount;
        bool isActive;
        uint256 joinedAt;
        string[] specializations;
    }

    struct ValidationReward {
        address validator;
        uint256 amount;
        uint256 requestId;
        bool isClaimed;
        uint256 earnedAt;
    }

    mapping(uint256 => VerificationRequest) private verificationRequests;
    mapping(address => ValidatorProfile) public validatorProfiles;
    mapping(uint256 => mapping(address => VerificationVote)) public votes;
    mapping(address => uint256[]) public validatorRequests;
    mapping(uint256 => ValidationReward[]) public requestRewards;

    uint256 private _requestIds;
    uint256 public validatorStakeAmount = 0.1 ether;
    uint256 public verificationReward = 0.01 ether;
    uint256 public totalRewardPool;
    uint256 public constant MIN_VALIDATORS = 3;
    uint256 public constant MAX_VALIDATORS = 7;

    event ValidatorRegistered(address indexed validator, uint256 stakeAmount);
    event VerificationRequested(uint256 indexed requestId, address indexed student);
    event VerificationVoteSubmitted(uint256 indexed requestId, address indexed validator, bool approved);
    event VerificationCompleted(uint256 indexed requestId, bool passed, uint256 validatorCount);
    event ValidatorRewarded(address indexed validator, uint256 amount, uint256 requestId);
    event ValidatorSlashed(address indexed validator, uint256 amount, string reason);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function registerValidator(string[] memory specializations) 
        external payable whenNotPaused {
        require(msg.value >= validatorStakeAmount, "Insufficient stake amount");
        require(!validatorProfiles[msg.sender].isActive, "Already registered");
        require(specializations.length > 0, "Must specify specializations");

        validatorProfiles[msg.sender] = ValidatorProfile({
            validatorAddress: msg.sender,
            totalVerifications: 0,
            correctVerifications: 0,
            accuracyRate: 1000, // Start with 100% accuracy
            stakingAmount: msg.value,
            isActive: true,
            joinedAt: block.timestamp,
            specializations: specializations
        });

        _grantRole(VALIDATOR_ROLE, msg.sender);

        emit ValidatorRegistered(msg.sender, msg.value);
    }

    function requestVerification(
        string memory submissionType,
        string memory submissionHash,
        uint256 requiredValidators
    ) external whenNotPaused returns (uint256) {
        require(requiredValidators >= MIN_VALIDATORS, "Not enough validators required");
        require(requiredValidators <= MAX_VALIDATORS, "Too many validators required");
        require(bytes(submissionHash).length > 0, "Submission hash required");

        _requestIds++;
        uint256 requestId = _requestIds;

        VerificationRequest storage request = verificationRequests[requestId];
        request.id = requestId;
        request.student = msg.sender;
        request.submissionType = submissionType;
        request.submissionHash = submissionHash;
        request.requiredValidators = requiredValidators;
        request.currentValidators = 0;
        request.isCompleted = false;
        request.isPassed = false;
        request.createdAt = block.timestamp;
        request.completedAt = 0;

        emit VerificationRequested(requestId, msg.sender);
        return requestId;
    }

    function submitVerification(
        uint256 requestId,
        bool isApproved,
        uint256 confidence,
        string memory feedback,
        string memory evidenceHash
    ) external onlyRole(VALIDATOR_ROLE) whenNotPaused {
        VerificationRequest storage request = verificationRequests[requestId];
        require(request.id != 0, "Request does not exist");
        require(!request.isCompleted, "Verification already completed");
        require(!request.hasValidated[msg.sender], "Already validated this request");
        require(confidence <= 100, "Confidence must be <= 100");
        require(validatorProfiles[msg.sender].isActive, "Validator not active");

        // Record the vote
        request.votes[msg.sender] = VerificationVote({
            validator: msg.sender,
            isApproved: isApproved,
            confidence: confidence,
            feedback: feedback,
            evidenceHash: evidenceHash,
            votedAt: block.timestamp
        });

        request.hasValidated[msg.sender] = true;
        request.validatorList.push(msg.sender);
        request.currentValidators++;

        validatorRequests[msg.sender].push(requestId);
        validatorProfiles[msg.sender].totalVerifications++;

        emit VerificationVoteSubmitted(requestId, msg.sender, isApproved);

        // Check if we have enough validators
        if (request.currentValidators >= request.requiredValidators) {
            _completeVerification(requestId);
        }
    }

    function _completeVerification(uint256 requestId) private {
        VerificationRequest storage request = verificationRequests[requestId];

        uint256 approvalCount = 0;
        uint256 totalConfidence = 0;

        // Count approvals and calculate average confidence
        for (uint256 i = 0; i < request.validatorList.length; i++) {
            address validator = request.validatorList[i];
            VerificationVote memory vote = request.votes[validator];

            if (vote.isApproved) {
                approvalCount++;
            }
            totalConfidence += vote.confidence;
        }

        uint256 averageConfidence = totalConfidence / request.currentValidators;

        // Determine if verification passes (majority approval + high confidence)
        bool passes = (approvalCount * 2 > request.currentValidators) && (averageConfidence >= 70);

        request.isCompleted = true;
        request.isPassed = passes;
        request.completedAt = block.timestamp;

        // Distribute rewards to validators
        _distributeRewards(requestId, passes);

        emit VerificationCompleted(requestId, passes, request.currentValidators);
    }

    function _distributeRewards(uint256 requestId, bool verificationPassed) private {
        VerificationRequest storage request = verificationRequests[requestId];
        uint256 rewardPerValidator = verificationReward;

        require(totalRewardPool >= rewardPerValidator * request.currentValidators, "Insufficient reward pool");

        for (uint256 i = 0; i < request.validatorList.length; i++) {
            address validator = request.validatorList[i];
            VerificationVote memory vote = request.votes[validator];

            // Calculate reward based on vote quality and confidence
            uint256 baseReward = rewardPerValidator;
            uint256 confidenceBonus = (vote.confidence * baseReward) / 1000; // Up to 10% bonus
            uint256 totalReward = baseReward + confidenceBonus;

            // Create reward entry
            requestRewards[requestId].push(ValidationReward({
                validator: validator,
                amount: totalReward,
                requestId: requestId,
                isClaimed: false,
                earnedAt: block.timestamp
            }));

            totalRewardPool -= totalReward;

            emit ValidatorRewarded(validator, totalReward, requestId);
        }
    }

    function claimValidationRewards(uint256[] memory requestIds) 
        external onlyRole(VALIDATOR_ROLE) whenNotPaused nonReentrant {
        uint256 totalAmount = 0;

        for (uint256 i = 0; i < requestIds.length; i++) {
            uint256 requestId = requestIds[i];
            ValidationReward[] storage rewards = requestRewards[requestId];

            for (uint256 j = 0; j < rewards.length; j++) {
                if (rewards[j].validator == msg.sender && !rewards[j].isClaimed) {
                    rewards[j].isClaimed = true;
                    totalAmount += rewards[j].amount;
                }
            }
        }

        require(totalAmount > 0, "No rewards to claim");
        payable(msg.sender).transfer(totalAmount);
    }

    function challengeVerification(uint256 requestId, string memory reason) 
        external whenNotPaused {
        VerificationRequest storage request = verificationRequests[requestId];
        require(request.isCompleted, "Verification not completed");
        require(msg.sender == request.student, "Only student can challenge");

        // This would start a dispute resolution process
        // Simplified implementation - in production, this would involve additional validators

        // For now, just flag for admin review
        emit VerificationCompleted(requestId, false, 0); // Re-emit with challenge flag
    }

    function updateValidatorAccuracy(address validator, bool wasCorrect) 
        external onlyRole(ADMIN_ROLE) {
        ValidatorProfile storage profile = validatorProfiles[validator];
        require(profile.isActive, "Validator not active");

        if (wasCorrect) {
            profile.correctVerifications++;
        }

        // Recalculate accuracy rate
        if (profile.totalVerifications > 0) {
            profile.accuracyRate = (profile.correctVerifications * 1000) / profile.totalVerifications;
        }

        // Slash stake for poor performance
        if (profile.accuracyRate < 600 && profile.totalVerifications >= 10) { // Less than 60% accuracy
            uint256 slashAmount = profile.stakingAmount / 10; // 10% slash
            profile.stakingAmount -= slashAmount;
            totalRewardPool += slashAmount; // Add to reward pool

            emit ValidatorSlashed(validator, slashAmount, "Low accuracy rate");

            // Deactivate if stake too low
            if (profile.stakingAmount < validatorStakeAmount / 2) {
                profile.isActive = false;
                _revokeRole(VALIDATOR_ROLE, validator);
            }
        }
    }

    // View functions
    function getVerificationRequest(uint256 requestId) external view returns (
        address student,
        string memory submissionType,
        string memory submissionHash,
        uint256 requiredValidators,
        uint256 currentValidators,
        bool isCompleted,
        bool isPassed,
        uint256 createdAt,
        uint256 completedAt
    ) {
        VerificationRequest storage request = verificationRequests[requestId];
        return (
            request.student,
            request.submissionType,
            request.submissionHash,
            request.requiredValidators,
            request.currentValidators,
            request.isCompleted,
            request.isPassed,
            request.createdAt,
            request.completedAt
        );
    }

    function getVerificationVote(uint256 requestId, address validator) 
        external view returns (VerificationVote memory) {
        return verificationRequests[requestId].votes[validator];
    }

    function getValidatorRequests(address validator) external view returns (uint256[] memory) {
        return validatorRequests[validator];
    }

    function getRequestValidators(uint256 requestId) external view returns (address[] memory) {
        return verificationRequests[requestId].validatorList;
    }

    function getValidatorProfile(address validator) external view returns (ValidatorProfile memory) {
        return validatorProfiles[validator];
    }

    function getPendingRewards(address validator) external view returns (uint256) {
        uint256 totalPending = 0;
        uint256[] memory requests = validatorRequests[validator];

        for (uint256 i = 0; i < requests.length; i++) {
            uint256 requestId = requests[i];
            ValidationReward[] memory rewards = requestRewards[requestId];

            for (uint256 j = 0; j < rewards.length; j++) {
                if (rewards[j].validator == validator && !rewards[j].isClaimed) {
                    totalPending += rewards[j].amount;
                }
            }
        }

        return totalPending;
    }

    // Admin functions
    function addToRewardPool() external payable onlyRole(ADMIN_ROLE) {
        totalRewardPool += msg.value;
    }

    function updateStakeAmount(uint256 newAmount) external onlyRole(ADMIN_ROLE) {
        validatorStakeAmount = newAmount;
    }

    function updateRewardAmount(uint256 newAmount) external onlyRole(ADMIN_ROLE) {
        verificationReward = newAmount;
    }

    function forceCompleteVerification(uint256 requestId, bool isPassed) 
        external onlyRole(ADMIN_ROLE) {
        VerificationRequest storage request = verificationRequests[requestId];
        require(!request.isCompleted, "Already completed");

        request.isCompleted = true;
        request.isPassed = isPassed;
        request.completedAt = block.timestamp;

        emit VerificationCompleted(requestId, isPassed, request.currentValidators);
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    receive() external payable {
        totalRewardPool += msg.value;
    }
}

contracts/GraduateDAO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract GraduateDAO is AccessControl, ReentrancyGuard, Pausable {
    bytes32 public constant GRADUATE_ROLE = keccak256("GRADUATE_ROLE");
    bytes32 public constant PROPOSAL_CREATOR_ROLE = keccak256("PROPOSAL_CREATOR_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    enum ProposalType { PROGRAM_IMPROVEMENT, FEATURE_REQUEST, TREASURY_ALLOCATION, GOVERNANCE_CHANGE, PARTNERSHIP }
    enum ProposalStatus { PENDING, ACTIVE, EXECUTED, REJECTED, EXPIRED }
    enum VoteType { AGAINST, FOR, ABSTAIN }

    struct Proposal {
        uint256 id;
        address proposer;
        ProposalType proposalType;
        string title;
        string description;
        string proposalHash; // IPFS hash with detailed proposal
        uint256 votingStartTime;
        uint256 votingEndTime;
        uint256 executionDelay;
        uint256 forVotes;
        uint256 againstVotes;
        uint256 abstainVotes;
        uint256 totalVotes;
        ProposalStatus status;
        bool executed;
        uint256 requiredQuorum;
        uint256 createdAt;
    }

    struct Vote {
        address voter;
        uint256 proposalId;
        VoteType voteType;
        uint256 votingPower;
        string reason;
        uint256 timestamp;
    }

    struct GraduateMember {
        address memberAddress;
        string name;
        uint256 votingPower;
        uint256 totalBadges;
        uint256 reputationScore;
        uint256[] completedBootcamps;
        uint256 joinedDAOAt;
        bool isActive;
        uint256 proposalsCreated;
        uint256 votesParticipated;
    }

    struct TreasuryAllocation {
        uint256 proposalId;
        address recipient;
        uint256 amount;
        string purpose;
        bool isExecuted;
        uint256 executedAt;
    }

    struct GovernanceParameters {
        uint256 minVotingPeriod;     // Minimum voting duration
        uint256 maxVotingPeriod;     // Maximum voting duration
        uint256 executionDelay;      // Time delay before execution
        uint256 proposalThreshold;   // Min tokens to create proposal
        uint256 quorumThreshold;     // Min votes needed for quorum
        uint256 majorityThreshold;   // % needed to pass (in basis points)
        uint256 minBadgesForMembership; // Min badges required to join
    }

    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => Vote)) public votes;
    mapping(uint256 => mapping(address => bool)) public hasVoted;
    mapping(address => GraduateMember) public members;
    mapping(uint256 => TreasuryAllocation) public treasuryAllocations;
    mapping(address => uint256[]) public memberProposals;
    mapping(address => uint256[]) public memberVotes;

    uint256 private _proposalIds;
    uint256 private _treasuryAllocationIds;
    uint256 public totalMembers;
    uint256 public treasuryBalance;

    GovernanceParameters public governance;

    address public skillPaysCore;
    address public badgeContract;

    event ProposalCreated(uint256 indexed proposalId, address indexed proposer, ProposalType proposalType, string title);
    event VoteCast(uint256 indexed proposalId, address indexed voter, VoteType voteType, uint256 votingPower);
    event ProposalExecuted(uint256 indexed proposalId, ProposalStatus status);
    event MemberJoined(address indexed member, uint256 votingPower);
    event TreasuryAllocationExecuted(uint256 indexed allocationId, address recipient, uint256 amount);
    event GovernanceParametersUpdated();
    event MemberVotingPowerUpdated(address indexed member, uint256 oldPower, uint256 newPower);

    modifier onlyGraduate() {
        require(hasRole(GRADUATE_ROLE, msg.sender), "Only graduates can call this function");
        require(members[msg.sender].isActive, "Member not active");
        _;
    }

    modifier onlyActiveMember() {
        require(members[msg.sender].isActive, "Member not active");
        _;
    }

    constructor(address _skillPaysCore, address _badgeContract) {
        require(_skillPaysCore != address(0), "Invalid SkillPays core address");
        require(_badgeContract != address(0), "Invalid badge contract address");

        skillPaysCore = _skillPaysCore;
        badgeContract = _badgeContract;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);

        // Initialize governance parameters
        governance = GovernanceParameters({
            minVotingPeriod: 3 days,
            maxVotingPeriod: 7 days,
            executionDelay: 1 days,
            proposalThreshold: 100, // Need 100 voting power to create proposal
            quorumThreshold: 1000,  // Need 1000 total votes for quorum
            majorityThreshold: 5000, // Need 50% majority (in basis points)
            minBadgesForMembership: 10 // Need 10 badges to join
        });
    }

    function joinDAO(string memory name) external whenNotPaused {
        require(!members[msg.sender].isActive, "Already a DAO member");

        // Get member data from SkillPays contracts
        (uint256 totalBadges, uint256 reputationScore, uint256[] memory bootcamps) = 
            _getMemberDataFromContracts(msg.sender);

        require(totalBadges >= governance.minBadgesForMembership, "Not enough badges to join");

        // Calculate voting power based on badges and reputation
        uint256 votingPower = _calculateVotingPower(totalBadges, reputationScore);

        members[msg.sender] = GraduateMember({
            memberAddress: msg.sender,
            name: name,
            votingPower: votingPower,
            totalBadges: totalBadges,
            reputationScore: reputationScore,
            completedBootcamps: bootcamps,
            joinedDAOAt: block.timestamp,
            isActive: true,
            proposalsCreated: 0,
            votesParticipated: 0
        });

        _grantRole(GRADUATE_ROLE, msg.sender);

        // Grant proposal creator role if they have enough voting power
        if (votingPower >= governance.proposalThreshold) {
            _grantRole(PROPOSAL_CREATOR_ROLE, msg.sender);
        }

        totalMembers++;

        emit MemberJoined(msg.sender, votingPower);
    }

    function createProposal(
        ProposalType proposalType,
        string memory title,
        string memory description,
        string memory proposalHash,
        uint256 votingDuration,
        uint256 executionDelay
    ) external onlyRole(PROPOSAL_CREATOR_ROLE) onlyActiveMember whenNotPaused returns (uint256) {
        require(bytes(title).length > 0, "Title cannot be empty");
        require(votingDuration >= governance.minVotingPeriod, "Voting period too short");
        require(votingDuration <= governance.maxVotingPeriod, "Voting period too long");
        require(executionDelay >= governance.executionDelay, "Execution delay too short");

        _proposalIds++;
        uint256 proposalId = _proposalIds;

        // Calculate required quorum based on proposal type
        uint256 requiredQuorum = _calculateRequiredQuorum(proposalType);

        proposals[proposalId] = Proposal({
            id: proposalId,
            proposer: msg.sender,
            proposalType: proposalType,
            title: title,
            description: description,
            proposalHash: proposalHash,
            votingStartTime: block.timestamp,
            votingEndTime: block.timestamp + votingDuration,
            executionDelay: executionDelay,
            forVotes: 0,
            againstVotes: 0,
            abstainVotes: 0,
            totalVotes: 0,
            status: ProposalStatus.ACTIVE,
            executed: false,
            requiredQuorum: requiredQuorum,
            createdAt: block.timestamp
        });

        members[msg.sender].proposalsCreated++;
        memberProposals[msg.sender].push(proposalId);

        emit ProposalCreated(proposalId, msg.sender, proposalType, title);
        return proposalId;
    }

    function vote(uint256 proposalId, VoteType voteType, string memory reason) 
        external onlyGraduate whenNotPaused {
        Proposal storage proposal = proposals[proposalId];
        require(proposal.id != 0, "Proposal does not exist");
        require(proposal.status == ProposalStatus.ACTIVE, "Proposal not active");
        require(block.timestamp <= proposal.votingEndTime, "Voting period ended");
        require(!hasVoted[proposalId][msg.sender], "Already voted on this proposal");

        uint256 votingPower = members[msg.sender].votingPower;
        require(votingPower > 0, "No voting power");

        // Record vote
        votes[proposalId][msg.sender] = Vote({
            voter: msg.sender,
            proposalId: proposalId,
            voteType: voteType,
            votingPower: votingPower,
            reason: reason,
            timestamp: block.timestamp
        });

        hasVoted[proposalId][msg.sender] = true;

        // Update proposal vote counts
        if (voteType == VoteType.FOR) {
            proposal.forVotes += votingPower;
        } else if (voteType == VoteType.AGAINST) {
            proposal.againstVotes += votingPower;
        } else {
            proposal.abstainVotes += votingPower;
        }

        proposal.totalVotes += votingPower;

        // Update member stats
        members[msg.sender].votesParticipated++;
        memberVotes[msg.sender].push(proposalId);

        emit VoteCast(proposalId, msg.sender, voteType, votingPower);

        // Check if proposal can be executed early (if overwhelming support)
        _checkEarlyExecution(proposalId);
    }

    function executeProposal(uint256 proposalId) external whenNotPaused nonReentrant {
        Proposal storage proposal = proposals[proposalId];
        require(proposal.id != 0, "Proposal does not exist");
        require(proposal.status == ProposalStatus.ACTIVE, "Proposal not active");
        require(block.timestamp > proposal.votingEndTime, "Voting still active");
        require(!proposal.executed, "Already executed");

        // Check if proposal passed
        bool passed = _hasProposalPassed(proposalId);

        if (passed) {
            proposal.status = ProposalStatus.EXECUTED;
            proposal.executed = true;

            // Execute proposal based on type
            _executeProposalAction(proposalId);
        } else {
            proposal.status = ProposalStatus.REJECTED;
        }

        emit ProposalExecuted(proposalId, proposal.status);
    }

    function _executeProposalAction(uint256 proposalId) private {
        Proposal memory proposal = proposals[proposalId];

        if (proposal.proposalType == ProposalType.TREASURY_ALLOCATION) {
            // Handle treasury allocation
            _executeTreasuryAllocation(proposalId);
        } else if (proposal.proposalType == ProposalType.GOVERNANCE_CHANGE) {
            // Handle governance parameter changes
            _executeGovernanceChange(proposalId);
        } else if (proposal.proposalType == ProposalType.PROGRAM_IMPROVEMENT) {
            // These would be handled off-chain or through integration
            // Mark as executed for tracking purposes
        }
        // Other proposal types would be implemented similarly
    }

    function _executeTreasuryAllocation(uint256 proposalId) private {
        // This would parse the proposal details to extract allocation info
        // Simplified implementation
        _treasuryAllocationIds++;
        uint256 allocationId = _treasuryAllocationIds;

        // In a real implementation, you'd parse the proposal data to get these values
        address recipient = proposals[proposalId].proposer; // Simplified
        uint256 amount = 0.1 ether; // This would come from proposal data

        require(treasuryBalance >= amount, "Insufficient treasury balance");

        treasuryAllocations[allocationId] = TreasuryAllocation({
            proposalId: proposalId,
            recipient: recipient,
            amount: amount,
            purpose: proposals[proposalId].description,
            isExecuted: true,
            executedAt: block.timestamp
        });

        treasuryBalance -= amount;
        payable(recipient).transfer(amount);

        emit TreasuryAllocationExecuted(allocationId, recipient, amount);
    }

    function _executeGovernanceChange(uint256 proposalId) private {
        // This would parse proposal data to update governance parameters
        // Simplified implementation - in reality, you'd have structured proposal data

        emit GovernanceParametersUpdated();
    }

    function _hasProposalPassed(uint256 proposalId) private view returns (bool) {
        Proposal memory proposal = proposals[proposalId];

        // Check quorum
        if (proposal.totalVotes < proposal.requiredQuorum) {
            return false;
        }

        // Check majority
        uint256 totalDecisionVotes = proposal.forVotes + proposal.againstVotes;
        if (totalDecisionVotes == 0) {
            return false;
        }

        uint256 majorityRequired = (totalDecisionVotes * governance.majorityThreshold) / 10000;
        return proposal.forVotes > majorityRequired;
    }

    function _checkEarlyExecution(uint256 proposalId) private {
        Proposal storage proposal = proposals[proposalId];

        // Check if we have overwhelming support (75%+ of total possible votes)
        uint256 totalPossibleVotes = _getTotalVotingPower();
        uint256 overwhelmingSupport = (totalPossibleVotes * 7500) / 10000; // 75%

        if (proposal.forVotes >= overwhelmingSupport) {
            proposal.votingEndTime = block.timestamp; // End voting immediately
        }
    }

    function _calculateVotingPower(uint256 totalBadges, uint256 reputationScore) 
        private pure returns (uint256) {
        // Base power from badges
        uint256 badgePower = totalBadges * 10;

        // Reputation multiplier (1.0x to 2.0x)
        uint256 reputationMultiplier = 100 + (reputationScore / 10); // Max 200% if reputation is 1000
        if (reputationMultiplier > 200) reputationMultiplier = 200;

        uint256 votingPower = (badgePower * reputationMultiplier) / 100;

        // Cap voting power to prevent excessive concentration
        if (votingPower > 1000) votingPower = 1000;

        return votingPower;
    }

    function _calculateRequiredQuorum(ProposalType proposalType) private view returns (uint256) {
        uint256 baseQuorum = governance.quorumThreshold;

        // Higher quorum for critical changes
        if (proposalType == ProposalType.GOVERNANCE_CHANGE) {
            return (baseQuorum * 150) / 100; // 50% higher quorum
        } else if (proposalType == ProposalType.TREASURY_ALLOCATION) {
            return (baseQuorum * 125) / 100; // 25% higher quorum
        }

        return baseQuorum;
    }

    function _getMemberDataFromContracts(address member) 
        private view returns (uint256 totalBadges, uint256 reputationScore, uint256[] memory bootcamps) {
        // In a real implementation, this would call the SkillPays and Badge contracts
        // Simplified implementation
        totalBadges = 15; // Mock data
        reputationScore = 500; // Mock data
        bootcamps = new uint256[](2);
        bootcamps[0] = 1;
        bootcamps[1] = 2;
    }

    function _getTotalVotingPower() private view returns (uint256) {
        // In a real implementation, you'd maintain this as a state variable
        // This is simplified for demonstration
        return totalMembers * 500; // Average voting power estimate
    }

    function updateMemberVotingPower(address member) external onlyRole(ADMIN_ROLE) {
        require(members[member].isActive, "Member not active");

        (uint256 totalBadges, uint256 reputationScore,) = _getMemberDataFromContracts(member);
        uint256 oldPower = members[member].votingPower;
        uint256 newPower = _calculateVotingPower(totalBadges, reputationScore);

        members[member].votingPower = newPower;
        members[member].totalBadges = totalBadges;
        members[member].reputationScore = reputationScore;

        // Update roles based on new voting power
        if (newPower >= governance.proposalThreshold) {
            _grantRole(PROPOSAL_CREATOR_ROLE, member);
        } else {
            _revokeRole(PROPOSAL_CREATOR_ROLE, member);
        }

        emit MemberVotingPowerUpdated(member, oldPower, newPower);
    }

    // View functions
    function getProposal(uint256 proposalId) external view returns (Proposal memory) {
        return proposals[proposalId];
    }

    function getVote(uint256 proposalId, address voter) external view returns (Vote memory) {
        return votes[proposalId][voter];
    }

    function getMember(address member) external view returns (GraduateMember memory) {
        return members[member];
    }

    function getMemberProposals(address member) external view returns (uint256[] memory) {
        return memberProposals[member];
    }

    function getMemberVotes(address member) external view returns (uint256[] memory) {
        return memberVotes[member];
    }

    function getGovernanceParameters() external view returns (GovernanceParameters memory) {
        return governance;
    }

    function canCreateProposal(address member) external view returns (bool) {
        return members[member].isActive && 
               hasRole(PROPOSAL_CREATOR_ROLE, member) && 
               members[member].votingPower >= governance.proposalThreshold;
    }

    function getProposalStatus(uint256 proposalId) external view returns (
        ProposalStatus status,
        uint256 forVotes,
        uint256 againstVotes,
        uint256 abstainVotes,
        uint256 totalVotes,
        bool hasQuorum,
        bool hasMajority
    ) {
        Proposal memory proposal = proposals[proposalId];

        bool quorum = proposal.totalVotes >= proposal.requiredQuorum;
        bool majority = _hasProposalPassed(proposalId);

        return (
            proposal.status,
            proposal.forVotes,
            proposal.againstVotes,
            proposal.abstainVotes,
            proposal.totalVotes,
            quorum,
            majority
        );
    }

    // Admin functions
    function updateGovernanceParameters(
        uint256 minVotingPeriod,
        uint256 maxVotingPeriod,
        uint256 executionDelay,
        uint256 proposalThreshold,
        uint256 quorumThreshold,
        uint256 majorityThreshold,
        uint256 minBadgesForMembership
    ) external onlyRole(ADMIN_ROLE) {
        governance.minVotingPeriod = minVotingPeriod;
        governance.maxVotingPeriod = maxVotingPeriod;
        governance.executionDelay = executionDelay;
        governance.proposalThreshold = proposalThreshold;
        governance.quorumThreshold = quorumThreshold;
        governance.majorityThreshold = majorityThreshold;
        governance.minBadgesForMembership = minBadgesForMembership;

        emit GovernanceParametersUpdated();
    }

    function addToTreasury() external payable onlyRole(ADMIN_ROLE) {
        treasuryBalance += msg.value;
    }

    function emergencyPause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function emergencyUnpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    receive() external payable {
        treasuryBalance += msg.value;
    }
}

contracts/interfaces/ISkillPaysCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface ISkillPaysCore {
    struct Student {
        string name;
        uint256 totalBadges;
        uint256 reputationScore;
        bool isActive;
        uint256 joinedAt;
    }

    struct Bootcamp {
        uint256 id;
        string name;
        string description;
        address creator;
        uint256 duration;
        uint256 fee;
        bool isActive;
        uint256 createdAt;
        uint256 totalEnrollments;
        uint256 totalCompletions;
    }

    struct Milestone {
        uint256 id;
        uint256 bootcampId;
        string name;
        string description;
        uint256 requiredScore;
        bool requiresPeerReview;
    }

    event StudentRegistered(address indexed student, string name);
    event BootcampCreated(uint256 indexed bootcampId, string name, address creator);
    event MilestoneCompleted(address indexed student, uint256 indexed bootcampId, uint256 milestoneId);
    event BadgeMinted(address indexed student, uint256 indexed tokenId, uint256 level);

    function registerStudent(string memory name) external;
    function createBootcamp(string memory name, string memory description, uint256 duration, uint256 fee) external returns (uint256);
    function enrollInBootcamp(uint256 bootcampId) external payable;
    function completeMilestone(uint256 bootcampId, uint256 milestoneId, bytes memory proof) external;
    function getStudent(address studentAddress) external view returns (Student memory);
    function getBootcamp(uint256 bootcampId) external view returns (Bootcamp memory);
    function getBootcampMilestones(uint256 bootcampId) external view returns (Milestone[] memory);
    function getStudentBootcamps(address student) external view returns (uint256[] memory);
}

contracts/JobBoardIntegration.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract JobBoardIntegration is AccessControl, Pausable {
    bytes32 public constant EMPLOYER_ROLE = keccak256("EMPLOYER_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    struct JobListing {
        uint256 id;
        address employer;
        string title;
        string description;
        string[] requiredSkills;
        mapping(string => uint256) skillLevels; // skill => minimum level required
        uint256 salaryRange; // in wei for simplicity
        bool isActive;
        uint256 postedAt;
        uint256 applicationsCount;
    }

    struct JobApplication {
        uint256 id;
        uint256 jobId;
        address applicant;
        string coverLetter;
        bool isVerified; // Whether skills are verified onchain
        uint256 matchScore; // 0-100 based on skill matching
        uint256 appliedAt;
        bool isReviewed;
        address reviewedBy;
    }

    struct EmployerProfile {
        address employerAddress;
        string companyName;
        string description;
        bool isVerified;
        uint256 jobsPosted;
        uint256 hires;
        uint256 joinedAt;
    }

    mapping(uint256 => JobListing) private jobListings;
    mapping(uint256 => JobApplication) public jobApplications;
    mapping(address => EmployerProfile) public employers;
    mapping(address => uint256[]) public applicantApplications;
    mapping(uint256 => uint256[]) public jobApplicationsList;

    uint256 private _jobIds;
    uint256 private _applicationIds;
    uint256[] public activeJobs;

    address public skillGraphContract;
    address public badgeContract;

    event EmployerRegistered(address indexed employer, string companyName);
    event JobPosted(uint256 indexed jobId, address indexed employer, string title);
    event JobApplicationSubmitted(uint256 indexed applicationId, uint256 indexed jobId, address applicant);
    event SkillsVerified(address indexed applicant, uint256 matchScore);

    constructor(address _skillGraphContract, address _badgeContract) {
        require(_skillGraphContract != address(0), "Invalid skill graph address");
        require(_badgeContract != address(0), "Invalid badge contract address");

        skillGraphContract = _skillGraphContract;
        badgeContract = _badgeContract;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function registerEmployer(string memory companyName, string memory description) 
        external whenNotPaused {
        require(bytes(companyName).length > 0, "Company name required");
        require(employers[msg.sender].employerAddress == address(0), "Already registered");

        employers[msg.sender] = EmployerProfile({
            employerAddress: msg.sender,
            companyName: companyName,
            description: description,
            isVerified: false,
            jobsPosted: 0,
            hires: 0,
            joinedAt: block.timestamp
        });

        _grantRole(EMPLOYER_ROLE, msg.sender);

        emit EmployerRegistered(msg.sender, companyName);
    }

    function postJob(
        string memory title,
        string memory description,
        string[] memory requiredSkills,
        uint256[] memory skillLevels,
        uint256 salaryRange
    ) external onlyRole(EMPLOYER_ROLE) whenNotPaused returns (uint256) {
        require(bytes(title).length > 0, "Title required");
        require(requiredSkills.length == skillLevels.length, "Skills and levels length mismatch");

        _jobIds++;
        uint256 jobId = _jobIds;

        JobListing storage job = jobListings[jobId];
        job.id = jobId;
        job.employer = msg.sender;
        job.title = title;
        job.description = description;
        job.requiredSkills = requiredSkills;
        job.salaryRange = salaryRange;
        job.isActive = true;
        job.postedAt = block.timestamp;
        job.applicationsCount = 0;

        for (uint256 i = 0; i < requiredSkills.length; i++) {
            job.skillLevels[requiredSkills[i]] = skillLevels[i];
        }

        activeJobs.push(jobId);
        employers[msg.sender].jobsPosted++;

        emit JobPosted(jobId, msg.sender, title);
        return jobId;
    }

    function applyForJob(uint256 jobId, string memory coverLetter) 
        external whenNotPaused returns (uint256) {
        require(jobListings[jobId].isActive, "Job not active");
        require(jobListings[jobId].employer != msg.sender, "Cannot apply to own job");

        _applicationIds++;
        uint256 applicationId = _applicationIds;

        // Verify skills and calculate match score
        uint256 matchScore = _calculateMatchScore(msg.sender, jobId);

        jobApplications[applicationId] = JobApplication({
            id: applicationId,
            jobId: jobId,
            applicant: msg.sender,
            coverLetter: coverLetter,
            isVerified: true, // Always verified since we're checking onchain
            matchScore: matchScore,
            appliedAt: block.timestamp,
            isReviewed: false,
            reviewedBy: address(0)
        });

        applicantApplications[msg.sender].push(applicationId);
        jobApplicationsList[jobId].push(applicationId);
        jobListings[jobId].applicationsCount++;

        emit JobApplicationSubmitted(applicationId, jobId, msg.sender);
        emit SkillsVerified(msg.sender, matchScore);

        return applicationId;
    }

    function _calculateMatchScore(address applicant, uint256 jobId) private view returns (uint256) {
        JobListing storage job = jobListings[jobId];
        uint256 totalSkills = job.requiredSkills.length;
        uint256 matchedSkills = 0;
        uint256 totalScore = 0;

        // This would integrate with SkillGraph contract to get actual skill levels
        for (uint256 i = 0; i < totalSkills; i++) {
            string memory skill = job.requiredSkills[i];
            uint256 requiredLevel = job.skillLevels[skill];

            // Mock skill level - in real implementation, call SkillGraph contract
            uint256 applicantLevel = _getApplicantSkillLevel(applicant, skill);

            if (applicantLevel >= requiredLevel) {
                matchedSkills++;
                // Award full points for meeting requirement, bonus for exceeding
                uint256 skillScore = 100;
                if (applicantLevel > requiredLevel) {
                    skillScore += (applicantLevel - requiredLevel) * 25;
                }
                totalScore += skillScore;
            } else {
                // Partial credit for having some skill level
                totalScore += (applicantLevel * 50) / requiredLevel;
            }
        }

        // Calculate final score
        uint256 averageScore = totalSkills > 0 ? totalScore / totalSkills : 0;

        // Bonus for having all required skills
        if (matchedSkills == totalSkills) {
            averageScore = (averageScore * 110) / 100; // 10% bonus
        }

        return averageScore > 100 ? 100 : averageScore;
    }

    function _getApplicantSkillLevel(address applicant, string memory skill) 
        private pure returns (uint256) {
        // Mock implementation - in real scenario, would call SkillGraph contract
        // This is simplified for demonstration
        if (keccak256(bytes(skill)) == keccak256(bytes("Solidity Development"))) {
            return 3; // Advanced level
        } else if (keccak256(bytes(skill)) == keccak256(bytes("JavaScript"))) {
            return 2; // Intermediate level
        }
        return 1; // Basic level for other skills
    }

    function reviewApplication(uint256 applicationId, bool isAccepted) 
        external onlyRole(EMPLOYER_ROLE) whenNotPaused {
        JobApplication storage application = jobApplications[applicationId];
        require(!application.isReviewed, "Already reviewed");

        uint256 jobId = application.jobId;
        require(jobListings[jobId].employer == msg.sender, "Not job owner");

        application.isReviewed = true;
        application.reviewedBy = msg.sender;

        if (isAccepted) {
            employers[msg.sender].hires++;
        }
    }

    function getJobDetails(uint256 jobId) external view returns (
        address employer,
        string memory title,
        string memory description,
        string[] memory requiredSkills,
        uint256 salaryRange,
        bool isActive,
        uint256 postedAt,
        uint256 applicationsCount
    ) {
        JobListing storage job = jobListings[jobId];
        return (
            job.employer,
            job.title,
            job.description,
            job.requiredSkills,
            job.salaryRange,
            job.isActive,
            job.postedAt,
            job.applicationsCount
        );
    }

    function getJobRequiredSkillLevel(uint256 jobId, string memory skill) 
        external view returns (uint256) {
        return jobListings[jobId].skillLevels[skill];
    }

    function getJobApplications(uint256 jobId) external view returns (uint256[] memory) {
        return jobApplicationsList[jobId];
    }

    function getApplicantApplications(address applicant) external view returns (uint256[] memory) {
        return applicantApplications[applicant];
    }

    function getActiveJobs() external view returns (uint256[] memory) {
        return activeJobs;
    }

    function getMatchedJobs(address applicant, uint256 minMatchScore) 
        external view returns (uint256[] memory matchedJobs, uint256[] memory matchScores) {
        uint256 count = 0;
        uint256[] memory tempJobs = new uint256[](activeJobs.length);
        uint256[] memory tempScores = new uint256[](activeJobs.length);

        for (uint256 i = 0; i < activeJobs.length; i++) {
            uint256 jobId = activeJobs[i];
            if (jobListings[jobId].isActive) {
                uint256 matchScore = _calculateMatchScore(applicant, jobId);
                if (matchScore >= minMatchScore) {
                    tempJobs[count] = jobId;
                    tempScores[count] = matchScore;
                    count++;
                }
            }
        }

        matchedJobs = new uint256[](count);
        matchScores = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            matchedJobs[i] = tempJobs[i];
            matchScores[i] = tempScores[i];
        }
    }

    // Admin functions
    function verifyEmployer(address employer, bool isVerified) 
        external onlyRole(ADMIN_ROLE) {
        require(employers[employer].employerAddress != address(0), "Employer not registered");
        employers[employer].isVerified = isVerified;
    }

    function deactivateJob(uint256 jobId) external {
        require(
            jobListings[jobId].employer == msg.sender || hasRole(ADMIN_ROLE, msg.sender),
            "Not authorized"
        );
        jobListings[jobId].isActive = false;
    }

    function updateSkillGraphContract(address _skillGraphContract) 
        external onlyRole(ADMIN_ROLE) {
        require(_skillGraphContract != address(0), "Invalid address");
        skillGraphContract = _skillGraphContract;
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

contracts/LeaderboardSocial.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title LeaderboardSocial
 * @author SkillPays Team
 * @notice A comprehensive leaderboard and social interaction system for students
 * @dev Manages student profiles, connections, achievements, and competitive rankings
 */
contract LeaderboardSocial is AccessControl, Pausable, ReentrancyGuard {
    /// @notice Role for entities that can update student scores
    bytes32 public constant SCORE_UPDATER_ROLE =
        keccak256("SCORE_UPDATER_ROLE");

    /// @notice Role for administrators who can manage the system
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    /// @notice Maximum number of entries per leaderboard
    uint256 public constant MAX_LEADERBOARD_SIZE = 100;

    /// @notice Grace period for maintaining streak (in seconds)
    uint256 public constant STREAK_GRACE_PERIOD = 2 days;

    /// @dev Custom errors for gas optimization
    error LeaderboardSocial__ProfileAlreadyExists();
    error LeaderboardSocial__ProfileNotFound();
    error LeaderboardSocial__InvalidConnectionType();
    error LeaderboardSocial__ConnectionAlreadyExists();
    error LeaderboardSocial__CannotConnectToSelf();
    error LeaderboardSocial__ConnectionNotFound();
    error LeaderboardSocial__LeaderboardNotFound();
    error LeaderboardSocial__AchievementNotFound();
    error LeaderboardSocial__InvalidScore();

    /**
     * @notice Represents an entry in a leaderboard
     * @param student The address of the student
     * @param score The student's score in this category
     * @param rank The student's current rank
     * @param badgeCount Number of badges earned by the student
     * @param streakDays Current streak in days
     * @param lastActiveDate When the student was last active
     * @param displayName The student's display name
     */
    struct LeaderboardEntry {
        address student;
        uint256 score;
        uint256 rank;
        uint256 badgeCount;
        uint256 streakDays;
        uint256 lastActiveDate;
        string displayName;
    }

    /**
     * @notice Student's social profile information
     * @param studentAddress The student's wallet address
     * @param displayName Public display name
     * @param bio Student's biography/description
     * @param profileImageHash IPFS hash of profile image
     * @param totalScore Total accumulated score
     * @param currentStreak Current daily activity streak
     * @param longestStreak Longest streak achieved
     * @param lastActiveDate Last time student was active
     * @param totalBadges Number of badges earned
     * @param totalConnections Number of social connections
     * @param isPublic Whether profile is publicly visible
     * @param joinedAt When the student joined
     */
    struct StudentSocialProfile {
        address studentAddress;
        string displayName;
        string bio;
        string profileImageHash;
        uint256 totalScore;
        uint256 currentStreak;
        uint256 longestStreak;
        uint256 lastActiveDate;
        uint256 totalBadges;
        uint256 totalConnections;
        bool isPublic;
        uint256 joinedAt;
    }

    /**
     * @notice Represents a social connection between students
     * @param requester The student who initiated the connection
     * @param target The student who received the request
     * @param isAccepted Whether the connection has been accepted
     * @param connectionType Type of connection (0=friend, 1=mentor, 2=collaborator)
     * @param createdAt When the connection was created
     * @param connectionNote Optional note about the connection
     */
    struct SocialConnection {
        address requester;
        address target;
        bool isAccepted;
        uint256 connectionType;
        uint256 createdAt;
        string connectionNote;
    }

    /**
     * @notice Represents an achievement that students can earn
     * @param id Unique identifier for this achievement
     * @param name Display name of the achievement
     * @param description Detailed description
     * @param iconHash IPFS hash of the achievement icon
     * @param requiredScore Minimum score required
     * @param requiredBadges Minimum badges required
     * @param requiredStreak Minimum streak required
     * @param isActive Whether this achievement can still be earned
     * @param totalEarned How many students have earned this
     */
    struct Achievement {
        uint256 id;
        string name;
        string description;
        string iconHash;
        uint256 requiredScore;
        uint256 requiredBadges;
        uint256 requiredStreak;
        bool isActive;
        uint256 totalEarned;
    }

    /**
     * @notice Represents a leaderboard category
     * @param name Name of the leaderboard category
     * @param scores Mapping from student address to their score
     * @param participants Array of participating students
     * @param lastUpdated When this leaderboard was last updated
     * @param isActive Whether this leaderboard is currently active
     */
    struct LeaderboardCategory {
        string name;
        mapping(address => uint256) scores;
        address[] participants;
        uint256 lastUpdated;
        bool isActive;
    }

    /// @notice Mapping from student address to their social profile
    mapping(address => StudentSocialProfile) public profiles;

    /// @notice Mapping to check if two students are connected
    mapping(address => mapping(address => bool)) public connections;

    /// @notice Mapping from connection hash to connection details
    mapping(bytes32 => SocialConnection) public connectionRequests;

    /// @notice Mapping from user to their connection request hashes
    mapping(address => bytes32[]) public userConnections;

    /// @notice Mapping to track which achievements each user has earned
    mapping(address => mapping(uint256 => bool)) public userAchievements;

    /// @notice Mapping from achievement ID to achievement details
    mapping(uint256 => Achievement) public achievements;

    /// @notice Mapping from category name to leaderboard data
    mapping(string => LeaderboardCategory) private leaderboards;

    /// @notice Mapping from category to array of leaderboard entries
    mapping(string => LeaderboardEntry[]) public leaderboardEntries;

    /// @notice Mapping from category and student to their position
    mapping(string => mapping(address => uint256)) public leaderboardPositions;

    /// @notice Array of active leaderboard names
    string[] public activeLeaderboards;

    /// @dev Counter for generating unique achievement IDs
    uint256 private _achievementIds;

    /// @notice Emitted when a new student profile is created
    event ProfileCreated(address indexed student, string displayName);

    /// @notice Emitted when a student profile is updated
    event ProfileUpdated(address indexed student);

    /// @notice Emitted when a connection request is made
    event ConnectionRequested(
        address indexed requester,
        address indexed target
    );

    /// @notice Emitted when a connection is accepted
    event ConnectionAccepted(address indexed requester, address indexed target);

    /// @notice Emitted when a student's score is updated
    event ScoreUpdated(
        address indexed student,
        string category,
        uint256 newScore,
        uint256 oldScore
    );

    /// @notice Emitted when a student's rank changes
    event RankChanged(
        address indexed student,
        string category,
        uint256 newRank,
        uint256 oldRank
    );

    /// @notice Emitted when a student's streak is updated
    event StreakUpdated(address indexed student, uint256 newStreak);

    /// @notice Emitted when a student earns an achievement
    event AchievementEarned(address indexed student, uint256 achievementId);

    /// @notice Emitted when a new leaderboard is created
    event LeaderboardCreated(string category);

    /**
     * @notice Initializes the LeaderboardSocial contract
     * @dev Sets up roles and creates default leaderboards
     */
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(SCORE_UPDATER_ROLE, msg.sender);

        // Initialize default leaderboards
        _createLeaderboard("overall");
        _createLeaderboard("monthly");
        _createLeaderboard("badges");
        _createLeaderboard("streak");

        // Initialize default achievements
        _createDefaultAchievements();
    }

    /**
     * @notice Creates a new student social profile
     * @param displayName Public display name for the student
     * @param bio Biography or description
     * @param profileImageHash IPFS hash of profile image
     * @param isPublic Whether the profile should be publicly visible
     * @dev Profile can only be created once per address
     */
    function createProfile(
        string memory displayName,
        string memory bio,
        string memory profileImageHash,
        bool isPublic
    ) external whenNotPaused {
        if (bytes(displayName).length == 0)
            revert LeaderboardSocial__InvalidScore();
        if (_profileExists(msg.sender))
            revert LeaderboardSocial__ProfileAlreadyExists();

        profiles[msg.sender] = StudentSocialProfile({
            studentAddress: msg.sender,
            displayName: displayName,
            bio: bio,
            profileImageHash: profileImageHash,
            totalScore: 0,
            currentStreak: 0,
            longestStreak: 0,
            lastActiveDate: block.timestamp,
            totalBadges: 0,
            totalConnections: 0,
            isPublic: isPublic,
            joinedAt: block.timestamp
        });

        emit ProfileCreated(msg.sender, displayName);
    }

    /**
     * @notice Updates an existing student social profile
     * @param displayName New display name
     * @param bio New biography
     * @param profileImageHash New profile image hash
     * @param isPublic New privacy setting
     * @dev Profile must exist to be updated
     */
    function updateProfile(
        string memory displayName,
        string memory bio,
        string memory profileImageHash,
        bool isPublic
    ) external whenNotPaused {
        if (!_profileExists(msg.sender))
            revert LeaderboardSocial__ProfileNotFound();

        StudentSocialProfile storage profile = profiles[msg.sender];
        profile.displayName = displayName;
        profile.bio = bio;
        profile.profileImageHash = profileImageHash;
        profile.isPublic = isPublic;

        emit ProfileUpdated(msg.sender);
    }

    function updateScore(
        address student,
        string memory category,
        uint256 newScore,
        uint256 badgeCount
    ) external onlyRole(SCORE_UPDATER_ROLE) whenNotPaused {
        require(_profileExists(student), "Profile does not exist");

        uint256 oldScore = leaderboards[category].scores[student];
        leaderboards[category].scores[student] = newScore;

        // Update profile
        StudentSocialProfile storage profile = profiles[student];
        profile.totalScore = newScore;
        profile.totalBadges = badgeCount;

        // Update streak
        _updateStreak(student);

        // Update leaderboard position
        _updateLeaderboardPosition(student, category);

        // Check for new achievements
        _checkAchievements(student);

        emit ScoreUpdated(student, category, newScore, oldScore);
    }

    function _updateStreak(address student) private {
        StudentSocialProfile storage profile = profiles[student];
        uint256 daysSinceLastActive = (block.timestamp -
            profile.lastActiveDate) / 1 days;

        if (daysSinceLastActive <= 1) {
            // Continue or start streak
            if (daysSinceLastActive == 1) {
                profile.currentStreak++;
                if (profile.currentStreak > profile.longestStreak) {
                    profile.longestStreak = profile.currentStreak;
                }
                emit StreakUpdated(student, profile.currentStreak);
            }
        } else if (daysSinceLastActive > STREAK_GRACE_PERIOD / 1 days) {
            // Break streak if too many days inactive
            if (profile.currentStreak > 0) {
                profile.currentStreak = 0;
                emit StreakUpdated(student, 0);
            }
        }

        profile.lastActiveDate = block.timestamp;
    }

    function _updateLeaderboardPosition(
        address student,
        string memory category
    ) private {
        LeaderboardEntry[] storage entries = leaderboardEntries[category];
        uint256 studentScore = leaderboards[category].scores[student];

        // Find current position
        uint256 currentPosition = leaderboardPositions[category][student];
        bool isNewEntry = currentPosition == 0;

        if (isNewEntry) {
            // Add new entry
            entries.push(
                LeaderboardEntry({
                    student: student,
                    score: studentScore,
                    rank: entries.length,
                    badgeCount: profiles[student].totalBadges,
                    streakDays: profiles[student].currentStreak,
                    lastActiveDate: profiles[student].lastActiveDate,
                    displayName: profiles[student].displayName
                })
            );
            leaderboardPositions[category][student] = entries.length;
        } else {
            // Update existing entry
            entries[currentPosition - 1].score = studentScore;
            entries[currentPosition - 1].badgeCount = profiles[student]
                .totalBadges;
            entries[currentPosition - 1].streakDays = profiles[student]
                .currentStreak;
            entries[currentPosition - 1].lastActiveDate = block.timestamp;
        }

        // Resort leaderboard (bubble sort for simplicity)
        _sortLeaderboard(category);

        // Trim to max size
        if (entries.length > MAX_LEADERBOARD_SIZE) {
            entries.pop();
        }

        leaderboards[category].lastUpdated = block.timestamp;
    }

    function _sortLeaderboard(string memory category) private {
        LeaderboardEntry[] storage entries = leaderboardEntries[category];

        for (uint256 i = 0; i < entries.length; i++) {
            for (uint256 j = 0; j < entries.length - 1 - i; j++) {
                if (entries[j].score < entries[j + 1].score) {
                    // Swap entries
                    LeaderboardEntry memory temp = entries[j];
                    entries[j] = entries[j + 1];
                    entries[j + 1] = temp;
                }
            }
        }

        // Update ranks and positions
        for (uint256 i = 0; i < entries.length; i++) {
            entries[i].rank = i + 1;
            leaderboardPositions[category][entries[i].student] = i + 1;
        }
    }

    function sendConnectionRequest(
        address target,
        uint256 connectionType,
        string memory note
    ) external whenNotPaused {
        require(_profileExists(msg.sender), "Sender profile does not exist");
        require(_profileExists(target), "Target profile does not exist");
        require(msg.sender != target, "Cannot connect to yourself");
        require(!connections[msg.sender][target], "Already connected");

        bytes32 requestId = keccak256(
            abi.encodePacked(msg.sender, target, block.timestamp)
        );

        connectionRequests[requestId] = SocialConnection({
            requester: msg.sender,
            target: target,
            isAccepted: false,
            connectionType: connectionType,
            createdAt: block.timestamp,
            connectionNote: note
        });

        emit ConnectionRequested(msg.sender, target);
    }

    function acceptConnection(bytes32 requestId) external whenNotPaused {
        SocialConnection storage request = connectionRequests[requestId];
        require(request.target == msg.sender, "Not the target of this request");
        require(!request.isAccepted, "Already accepted");

        request.isAccepted = true;

        // Create bidirectional connection
        connections[request.requester][request.target] = true;
        connections[request.target][request.requester] = true;

        // Update connection counts
        profiles[request.requester].totalConnections++;
        profiles[request.target].totalConnections++;

        // Store connection reference
        userConnections[request.requester].push(requestId);
        userConnections[request.target].push(requestId);

        emit ConnectionAccepted(request.requester, request.target);
    }

    function _checkAchievements(address student) private {
        StudentSocialProfile memory profile = profiles[student];

        for (uint256 i = 1; i <= _achievementIds; i++) {
            if (!userAchievements[student][i] && achievements[i].isActive) {
                Achievement memory achievement = achievements[i];

                bool earned = true;
                if (
                    achievement.requiredScore > 0 &&
                    profile.totalScore < achievement.requiredScore
                ) {
                    earned = false;
                }
                if (
                    achievement.requiredBadges > 0 &&
                    profile.totalBadges < achievement.requiredBadges
                ) {
                    earned = false;
                }
                if (
                    achievement.requiredStreak > 0 &&
                    profile.longestStreak < achievement.requiredStreak
                ) {
                    earned = false;
                }

                if (earned) {
                    userAchievements[student][i] = true;
                    achievements[i].totalEarned++;
                    emit AchievementEarned(student, i);
                }
            }
        }
    }

    function _createDefaultAchievements() private {
        _createAchievement(
            "First Steps",
            "Complete your first milestone",
            "",
            10,
            1,
            0
        );
        _createAchievement("Badge Collector", "Earn 10 badges", "", 0, 10, 0);
        _createAchievement(
            "Dedicated Learner",
            "Maintain a 7-day streak",
            "",
            0,
            0,
            7
        );
        _createAchievement(
            "Rising Star",
            "Reach 500 skill points",
            "",
            500,
            0,
            0
        );
        _createAchievement("Master Student", "Earn 50 badges", "", 0, 50, 0);
        _createAchievement(
            "Streak Master",
            "Maintain a 30-day streak",
            "",
            0,
            0,
            30
        );
        _createAchievement(
            "Elite Learner",
            "Reach 2000 skill points",
            "",
            2000,
            0,
            0
        );
        _createAchievement("Badge Legend", "Earn 100 badges", "", 0, 100, 0);
    }

    function _createAchievement(
        string memory name,
        string memory description,
        string memory iconHash,
        uint256 requiredScore,
        uint256 requiredBadges,
        uint256 requiredStreak
    ) private {
        _achievementIds++;
        achievements[_achievementIds] = Achievement({
            id: _achievementIds,
            name: name,
            description: description,
            iconHash: iconHash,
            requiredScore: requiredScore,
            requiredBadges: requiredBadges,
            requiredStreak: requiredStreak,
            isActive: true,
            totalEarned: 0
        });
    }

    function _createLeaderboard(string memory category) private {
        leaderboards[category].name = category;
        leaderboards[category].isActive = true;
        leaderboards[category].lastUpdated = block.timestamp;
        activeLeaderboards.push(category);

        emit LeaderboardCreated(category);
    }

    function _profileExists(address student) private view returns (bool) {
        return profiles[student].studentAddress != address(0);
    }

    // View functions
    function getProfile(
        address student
    ) external view returns (StudentSocialProfile memory) {
        return profiles[student];
    }

    function getLeaderboard(
        string memory category
    ) external view returns (LeaderboardEntry[] memory) {
        return leaderboardEntries[category];
    }

    function getLeaderboardPosition(
        address student,
        string memory category
    ) external view returns (uint256) {
        return leaderboardPositions[category][student];
    }

    function getUserConnections(
        address user
    ) external view returns (bytes32[] memory) {
        return userConnections[user];
    }

    function getConnectionRequest(
        bytes32 requestId
    ) external view returns (SocialConnection memory) {
        return connectionRequests[requestId];
    }

    function getAchievement(
        uint256 achievementId
    ) external view returns (Achievement memory) {
        return achievements[achievementId];
    }

    function getUserAchievements(
        address user
    ) external view returns (uint256[] memory) {
        uint256[] memory earnedAchievements = new uint256[](_achievementIds);
        uint256 count = 0;

        for (uint256 i = 1; i <= _achievementIds; i++) {
            if (userAchievements[user][i]) {
                earnedAchievements[count] = i;
                count++;
            }
        }

        // Trim array to actual size
        uint256[] memory result = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            result[i] = earnedAchievements[i];
        }

        return result;
    }

    function getActiveLeaderboards() external view returns (string[] memory) {
        return activeLeaderboards;
    }

    function isConnected(
        address user1,
        address user2
    ) external view returns (bool) {
        return connections[user1][user2];
    }

    // Admin functions
    function createLeaderboard(
        string memory category
    ) external onlyRole(ADMIN_ROLE) {
        require(!leaderboards[category].isActive, "Leaderboard already exists");
        _createLeaderboard(category);
    }

    function createAchievement(
        string memory name,
        string memory description,
        string memory iconHash,
        uint256 requiredScore,
        uint256 requiredBadges,
        uint256 requiredStreak
    ) external onlyRole(ADMIN_ROLE) {
        _createAchievement(
            name,
            description,
            iconHash,
            requiredScore,
            requiredBadges,
            requiredStreak
        );
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

contracts/MentorBoostSystem.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title MentorBoostSystem
 * @author SkillPays Team
 * @notice A comprehensive mentorship and micro-rewards system for student guidance
 * @dev Manages mentor registration, boost requests, micro-rewards, and mentorship sessions
 */
contract MentorBoostSystem is AccessControl, ReentrancyGuard, Pausable {
    /// @notice Role for registered mentors who can provide boosts
    bytes32 public constant MENTOR_ROLE = keccak256("MENTOR_ROLE");

    /// @notice Role for administrators who can manage the system
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    /// @notice Minimum stake required to become a mentor
    uint256 public constant MIN_MENTOR_STAKE = 0.5 ether;

    /// @notice Maximum amount for micro-rewards
    uint256 public constant MAX_MICRO_REWARD = 0.01 ether;

    /// @notice Minimum reputation score for certain mentor privileges
    uint256 public constant REPUTATION_THRESHOLD = 80;

    /// @dev Custom errors for gas optimization
    error MentorBoost__InsufficientStake();
    error MentorBoost__AlreadyMentor();
    error MentorBoost__NotMentor();
    error MentorBoost__InvalidRequest();
    error MentorBoost__RequestNotApproved();
    error MentorBoost__RequestAlreadyProcessed();
    error MentorBoost__ExcessiveMicroReward();
    error MentorBoost__MentorshipNotActive();
    error MentorBoost__SessionNotFound();
    error MentorBoost__InvalidRating();

    /**
     * @notice Profile information for registered mentors
     * @param mentorAddress The mentor's wallet address
     * @param name Display name of the mentor
     * @param bio Biography or description
     * @param expertise Comma-separated areas of expertise
     * @param totalBoosts Total number of boosts provided
     * @param successfulMentorships Number of successful mentorship relationships
     * @param averageRating Average rating from students (0-100)
     * @param reputationScore Reputation score based on performance
     * @param stakingAmount Amount of ETH staked by the mentor
     * @param isActive Whether the mentor is currently active
     * @param joinedAt Timestamp when mentor registered
     */
    struct MentorProfile {
        address mentorAddress;
        string name;
        string bio;
        string expertise;
        uint256 totalBoosts;
        uint256 successfulMentorships;
        uint256 averageRating;
        uint256 reputationScore;
        uint256 stakingAmount;
        bool isActive;
        uint256 joinedAt;
    }

    /**
     * @notice Request for a mentor boost from a student
     * @param id Unique identifier for this request
     * @param student The student requesting the boost
     * @param mentor The mentor who will provide the boost
     * @param bootcampId ID of the bootcamp context
     * @param milestoneId ID of the milestone context
     * @param submissionHash IPFS hash of student's submission
     * @param boostType Type of boost (recognition, micro_reward, skill_validation)
     * @param requestedAmount Amount requested for micro-reward boosts
     * @param justification Student's justification for the boost
     * @param isApproved Whether the mentor has approved this request
     * @param isCompleted Whether the boost has been processed
     * @param createdAt When the request was created
     * @param processedAt When the request was processed
     */
    struct BoostRequest {
        uint256 id;
        address student;
        address mentor;
        uint256 bootcampId;
        uint256 milestoneId;
        string submissionHash;
        string boostType;
        uint256 requestedAmount;
        string justification;
        bool isApproved;
        bool isCompleted;
        uint256 createdAt;
        uint256 processedAt;
    }

    /**
     * @notice A micro-reward issued by a mentor to a student
     * @param id Unique identifier for this reward
     * @param student The student receiving the reward
     * @param mentor The mentor issuing the reward
     * @param amount Amount of the reward in Wei
     * @param reason Reason for issuing the reward
     * @param evidenceHash IPFS hash of supporting evidence
     * @param timestamp When the reward was issued
     * @param isClaimed Whether the reward has been claimed
     */
    struct MicroReward {
        uint256 id;
        address student;
        address mentor;
        uint256 amount;
        string reason;
        string evidenceHash;
        uint256 timestamp;
        bool isClaimed;
    }

    /**
     * @notice A mentorship session between mentor and student
     * @param id Unique identifier for this session
     * @param mentor The mentor conducting the session
     * @param student The student participating
     * @param sessionType Type of session (1on1, group, review)
     * @param duration Duration of the session in minutes
     * @param contentHash IPFS hash of session notes/content
     * @param studentRating Rating given by student (0-100)
     * @param feedback Student's feedback about the session
     * @param scheduledAt When the session was scheduled
     * @param completedAt When the session was completed
     * @param isCompleted Whether the session has been completed
     */
    struct MentorshipSession {
        uint256 id;
        address mentor;
        address student;
        string sessionType;
        uint256 duration;
        string contentHash;
        uint256 studentRating;
        string feedback;
        uint256 scheduledAt;
        uint256 completedAt;
        bool isCompleted;
    }

    /**
     * @notice Reward tracking for mentors
     * @param totalEarned Total rewards earned by the mentor
     * @param totalDistributed Total rewards distributed by the mentor
     * @param pendingRewards Rewards awaiting distribution
     * @param reputationBonus Bonus based on reputation score
     * @param lastRewardTime When rewards were last calculated
     */
    struct MentorRewards {
        uint256 totalEarned;
        uint256 totalDistributed;
        uint256 pendingRewards;
        uint256 reputationBonus;
        uint256 lastRewardTime;
    }

    /// @notice Mapping from mentor address to their profile
    mapping(address => MentorProfile) public mentors;

    /// @notice Mapping from request ID to boost request details
    mapping(uint256 => BoostRequest) public boostRequests;

    /// @notice Mapping from reward ID to micro-reward details
    mapping(uint256 => MicroReward) public microRewards;

    /// @notice Mapping from session ID to mentorship session details
    mapping(uint256 => MentorshipSession) public mentorshipSessions;

    /// @notice Mapping from mentor address to their reward information
    mapping(address => MentorRewards) public mentorRewards;

    /// @notice Mapping from mentor to their students
    mapping(address => address[]) public mentorStudents;

    /// @notice Mapping from student to their mentors
    mapping(address => address[]) public studentMentors;

    /// @notice Mapping to track active mentorship relationships
    mapping(address => mapping(address => bool)) public activeMentorships;

    /// @dev Counter for generating unique boost request IDs
    uint256 private _boostRequestIds;

    /// @dev Counter for generating unique micro-reward IDs
    uint256 private _microRewardIds;

    /// @dev Counter for generating unique session IDs
    uint256 private _sessionIds;

    /// @notice Address of the reward pool contract
    address public rewardPool;

    /// @notice Total amount in the reward pool
    uint256 public totalRewardPool;

    /// @notice Emitted when a new mentor registers
    event MentorRegistered(address indexed mentor, string name);

    /// @notice Emitted when a student requests a boost
    event BoostRequested(uint256 indexed requestId, address indexed student, address indexed mentor);

    /// @notice Emitted when a mentor approves a boost request
    event BoostApproved(uint256 indexed requestId, uint256 amount);

    /// @notice Emitted when a micro-reward is issued
    event MicroRewardIssued(uint256 indexed rewardId, address indexed student, address indexed mentor, uint256 amount);

    /// @notice Emitted when a new mentorship relationship starts
    event MentorshipStarted(address indexed mentor, address indexed student);

    /// @notice Emitted when a mentorship session is scheduled
    event SessionScheduled(uint256 indexed sessionId, address indexed mentor, address indexed student);

    /// @notice Emitted when a mentorship session is completed
    event SessionCompleted(uint256 indexed sessionId, uint256 rating);

    /// @notice Emitted when a mentor receives rewards
    event MentorRewarded(address indexed mentor, uint256 amount);

    /**
     * @notice Initializes the MentorBoostSystem contract
     * @param _rewardPool Address of the reward pool contract
     * @dev Sets up roles and reward pool configuration
     */
    constructor(address _rewardPool) {
        if (_rewardPool == address(0)) revert MentorBoost__InvalidRequest();
        rewardPool = _rewardPool;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    /**
     * @notice Registers a new mentor with staking requirement
     * @param name Display name of the mentor
     * @param bio Biography or description
     * @param expertise Areas of expertise (comma-separated)
     * @dev Requires minimum stake and mentor must not be already registered
     */
    function registerAsMentor(
        string memory name,
        string memory bio,
        string memory expertise
    ) external payable whenNotPaused {
        if (msg.value < MIN_MENTOR_STAKE) revert MentorBoost__InsufficientStake();
        require(!mentors[msg.sender].isActive, "Already registered as mentor");
        require(bytes(name).length > 0, "Name cannot be empty");

        mentors[msg.sender] = MentorProfile({
            mentorAddress: msg.sender,
            name: name,
            bio: bio,
            expertise: expertise,
            totalBoosts: 0,
            successfulMentorships: 0,
            averageRating: 0,
            reputationScore: 100, // Start with good reputation
            stakingAmount: msg.value,
            isActive: true,
            joinedAt: block.timestamp
        });

        _grantRole(MENTOR_ROLE, msg.sender);

        emit MentorRegistered(msg.sender, name);
    }

    function requestBoost(
        address mentor,
        uint256 bootcampId,
        uint256 milestoneId,
        string memory submissionHash,
        string memory boostType,
        uint256 requestedAmount,
        string memory justification
    ) external whenNotPaused returns (uint256) {
        require(mentors[mentor].isActive, "Mentor not active");
        require(requestedAmount <= MAX_MICRO_REWARD, "Requested amount too high");
        require(bytes(justification).length > 0, "Justification required");

        _boostRequestIds++;
        uint256 requestId = _boostRequestIds;

        boostRequests[requestId] = BoostRequest({
            id: requestId,
            student: msg.sender,
            mentor: mentor,
            bootcampId: bootcampId,
            milestoneId: milestoneId,
            submissionHash: submissionHash,
            boostType: boostType,
            requestedAmount: requestedAmount,
            justification: justification,
            isApproved: false,
            isCompleted: false,
            createdAt: block.timestamp,
            processedAt: 0
        });

        emit BoostRequested(requestId, msg.sender, mentor);
        return requestId;
    }

    function approveBoost(uint256 requestId) external onlyRole(MENTOR_ROLE) whenNotPaused nonReentrant {
        BoostRequest storage request = boostRequests[requestId];
        require(request.mentor == msg.sender, "Not the assigned mentor");
        require(!request.isApproved, "Already approved");
        require(mentors[msg.sender].reputationScore >= REPUTATION_THRESHOLD, "Insufficient reputation");

        request.isApproved = true;
        request.processedAt = block.timestamp;

        // Issue micro reward if requested
        if (request.requestedAmount > 0) {
            _issueMicroReward(request.student, msg.sender, request.requestedAmount, request.justification);
        }

        // Update mentor stats
        mentors[msg.sender].totalBoosts++;

        // Start mentorship if not already active
        if (!activeMentorships[msg.sender][request.student]) {
            _startMentorship(msg.sender, request.student);
        }

        emit BoostApproved(requestId, request.requestedAmount);
    }

    function _issueMicroReward(
        address student,
        address mentor,
        uint256 amount,
        string memory reason
    ) private {
        require(totalRewardPool >= amount, "Insufficient reward pool");

        _microRewardIds++;
        uint256 rewardId = _microRewardIds;

        microRewards[rewardId] = MicroReward({
            id: rewardId,
            student: student,
            mentor: mentor,
            amount: amount,
            reason: reason,
            evidenceHash: "",
            timestamp: block.timestamp,
            isClaimed: false
        });

        // Update reward tracking
        mentorRewards[mentor].totalDistributed += amount;
        totalRewardPool -= amount;

        // Transfer reward to student
        payable(student).transfer(amount);

        emit MicroRewardIssued(rewardId, student, mentor, amount);
    }

    function _startMentorship(address mentor, address student) private {
        activeMentorships[mentor][student] = true;
        mentorStudents[mentor].push(student);
        studentMentors[student].push(mentor);

        emit MentorshipStarted(mentor, student);
    }

    function scheduleSession(
        address student,
        string memory sessionType,
        uint256 duration,
        uint256 scheduledTime
    ) external onlyRole(MENTOR_ROLE) whenNotPaused {
        require(activeMentorships[msg.sender][student], "Not an active mentorship");
        require(scheduledTime > block.timestamp, "Cannot schedule in the past");

        _sessionIds++;
        uint256 sessionId = _sessionIds;

        mentorshipSessions[sessionId] = MentorshipSession({
            id: sessionId,
            mentor: msg.sender,
            student: student,
            sessionType: sessionType,
            duration: duration,
            contentHash: "",
            studentRating: 0,
            feedback: "",
            scheduledAt: scheduledTime,
            completedAt: 0,
            isCompleted: false
        });

        emit SessionScheduled(sessionId, msg.sender, student);
    }

    function completeSession(
        uint256 sessionId,
        string memory contentHash
    ) external onlyRole(MENTOR_ROLE) whenNotPaused {
        MentorshipSession storage session = mentorshipSessions[sessionId];
        require(session.mentor == msg.sender, "Not the session mentor");
        require(!session.isCompleted, "Session already completed");
        require(block.timestamp >= session.scheduledAt, "Session not started yet");

        session.contentHash = contentHash;
        session.completedAt = block.timestamp;
        session.isCompleted = true;

        // Update mentor session count
        mentors[msg.sender].successfulMentorships++;

        // Reward mentor based on session completion
        _rewardMentor(msg.sender, session.duration);
    }

    function rateSession(uint256 sessionId, uint256 rating, string memory feedback) external whenNotPaused {
        MentorshipSession storage session = mentorshipSessions[sessionId];
        require(session.student == msg.sender, "Not the session student");
        require(session.isCompleted, "Session not completed");
        require(rating >= 1 && rating <= 5, "Rating must be 1-5");
        require(session.studentRating == 0, "Already rated");

        session.studentRating = rating;
        session.feedback = feedback;

        // Update mentor average rating
        _updateMentorRating(session.mentor, rating);

        emit SessionCompleted(sessionId, rating);
    }

    function _updateMentorRating(address mentor, uint256 newRating) private {
        MentorProfile storage profile = mentors[mentor];

        if (profile.averageRating == 0) {
            profile.averageRating = newRating * 20; // Scale to 0-100
        } else {
            // Weighted average with more weight on recent ratings
            profile.averageRating = (profile.averageRating * 70 + newRating * 20 * 30) / 100;
        }

        // Update reputation based on rating
        if (newRating >= 4) {
            if (profile.reputationScore < 1000) {
                profile.reputationScore += 2;
            }
        } else if (newRating <= 2) {
            if (profile.reputationScore > 10) {
                profile.reputationScore -= 5;
            }
        }
    }

    function _rewardMentor(address mentor, uint256 sessionDuration) private {
        // Calculate reward based on session duration and mentor reputation
        uint256 baseReward = (sessionDuration * 0.001 ether) / 60; // Base rate per minute
        uint256 reputationMultiplier = mentors[mentor].reputationScore;
        uint256 totalReward = (baseReward * reputationMultiplier) / 100;

        if (totalReward > totalRewardPool) {
            totalReward = totalRewardPool;
        }

        if (totalReward > 0) {
            MentorRewards storage rewards = mentorRewards[mentor];
            rewards.totalEarned += totalReward;
            rewards.pendingRewards += totalReward;
            rewards.lastRewardTime = block.timestamp;

            totalRewardPool -= totalReward;

            emit MentorRewarded(mentor, totalReward);
        }
    }

    function claimRewards() external onlyRole(MENTOR_ROLE) whenNotPaused nonReentrant {
        MentorRewards storage rewards = mentorRewards[msg.sender];
        require(rewards.pendingRewards > 0, "No pending rewards");

        uint256 amount = rewards.pendingRewards;
        rewards.pendingRewards = 0;

        payable(msg.sender).transfer(amount);
    }

    function addExpertise(string memory newExpertise) external onlyRole(MENTOR_ROLE) {
        MentorProfile storage profile = mentors[msg.sender];
        require(profile.isActive, "Mentor not active");

        if (bytes(profile.expertise).length == 0) {
            profile.expertise = newExpertise;
        } else {
            profile.expertise = string(abi.encodePacked(profile.expertise, ",", newExpertise));
        }
    }

    // View functions
    function getMentorProfile(address mentor) external view returns (MentorProfile memory) {
        return mentors[mentor];
    }

    function getBoostRequest(uint256 requestId) external view returns (BoostRequest memory) {
        return boostRequests[requestId];
    }

    function getMentorshipSession(uint256 sessionId) external view returns (MentorshipSession memory) {
        return mentorshipSessions[sessionId];
    }

    function getMentorStudents(address mentor) external view returns (address[] memory) {
        return mentorStudents[mentor];
    }

    function getStudentMentors(address student) external view returns (address[] memory) {
        return studentMentors[student];
    }

    function getMentorRewards(address mentor) external view returns (MentorRewards memory) {
        return mentorRewards[mentor];
    }

    function isActiveMentorship(address mentor, address student) external view returns (bool) {
        return activeMentorships[mentor][student];
    }

    // Admin functions
    function addToRewardPool() external payable onlyRole(ADMIN_ROLE) {
        totalRewardPool += msg.value;
    }

    function emergencyWithdrawRewards(uint256 amount) external onlyRole(ADMIN_ROLE) {
        require(amount <= totalRewardPool, "Insufficient pool balance");
        totalRewardPool -= amount;
        payable(msg.sender).transfer(amount);
    }

    function penalizeMentor(address mentor, uint256 penaltyAmount, string memory reason) 
        external onlyRole(ADMIN_ROLE) {
        require(mentors[mentor].isActive, "Mentor not active");
        require(penaltyAmount <= mentors[mentor].stakingAmount, "Penalty exceeds stake");

        mentors[mentor].stakingAmount -= penaltyAmount;
        mentors[mentor].reputationScore = mentors[mentor].reputationScore > 20 ? 
            mentors[mentor].reputationScore - 20 : 0;

        // Send penalty to reward pool
        totalRewardPool += penaltyAmount;

        if (mentors[mentor].stakingAmount < MIN_MENTOR_STAKE) {
            mentors[mentor].isActive = false;
            _revokeRole(MENTOR_ROLE, mentor);
        }
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    receive() external payable {
        totalRewardPool += msg.value;
    }
}

contracts/MicroRewardsSystem.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title MicroRewardsSystem
 * @author SkillPays Team
 * @notice A comprehensive micro-rewards system for incentivizing student engagement
 * @dev Manages automated reward distribution based on activity checkpoints and streaks
 */
contract MicroRewardsSystem is AccessControl, ReentrancyGuard, Pausable {
    /// @notice Role for entities that can distribute rewards
    bytes32 public constant REWARDS_DISTRIBUTOR_ROLE = keccak256("REWARDS_DISTRIBUTOR_ROLE");

    /// @notice Role for administrators who can manage the system
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    /// @notice Maximum daily rewards a student can earn
    uint256 public constant MAX_DAILY_REWARDS = 0.01 ether;

    /// @notice Maximum weekly rewards a student can earn
    uint256 public constant MAX_WEEKLY_REWARDS = 0.05 ether;

    /// @notice Threshold for detecting suspicious activity
    uint256 public constant SUSPICIOUS_ACTIVITY_THRESHOLD = 100;

    /// @dev Custom errors for gas optimization
    error MicroRewards__InvalidCheckpointType();
    error MicroRewards__DailyLimitExceeded();
    error MicroRewards__WeeklyLimitExceeded();
    error MicroRewards__TooSoonForCheckpoint();
    error MicroRewards__CheckpointNotFound();
    error MicroRewards__AlreadyClaimed();
    error MicroRewards__SuspiciousActivity();
    error MicroRewards__InsufficientRewardPool();
    error MicroRewards__NoRewardsToClaim();

    /**
     * @notice Represents a reward checkpoint earned by a student
     * @param id Unique identifier for this checkpoint
     * @param student The student who earned this checkpoint
     * @param checkpointType Type of checkpoint (daily_login, weekly_consistency, etc.)
     * @param rewardAmount Amount of reward for this checkpoint
     * @param streakMultiplier Multiplier applied based on streak
     * @param evidenceHash IPFS hash of evidence supporting this checkpoint
     * @param timestamp When this checkpoint was earned
     * @param isClaimed Whether the reward has been claimed
     * @param claimedAt When the reward was claimed
     */
    struct RewardCheckpoint {
        uint256 id;
        address student;
        string checkpointType;
        uint256 rewardAmount;
        uint256 streakMultiplier;
        string evidenceHash;
        uint256 timestamp;
        bool isClaimed;
        uint256 claimedAt;
    }

    /**
     * @notice Student's reward profile tracking earnings and activity
     * @param studentAddress The student's wallet address
     * @param totalEarned Total rewards earned (claimed + pending)
     * @param totalClaimed Total rewards claimed so far
     * @param pendingRewards Rewards awaiting claim
     * @param currentStreak Current consecutive activity streak
     * @param longestStreak Longest streak achieved by the student
     * @param lastActivityDate Last time student had activity
     * @param dailyCheckpoints Number of checkpoints earned today
     * @param weeklyCheckpoints Number of checkpoints earned this week
     * @param checkpointCounts Count of each checkpoint type earned
     * @param claimedCheckpoints Mapping of claimed checkpoint IDs
     */
    struct StudentRewardProfile {
        address studentAddress;
        uint256 totalEarned;
        uint256 totalClaimed;
        uint256 pendingRewards;
        uint256 currentStreak;
        uint256 longestStreak;
        uint256 lastActivityDate;
        uint256 dailyCheckpoints;
        uint256 weeklyCheckpoints;
        mapping(string => uint256) checkpointCounts;
        mapping(uint256 => bool) claimedCheckpoints;
    }

    /**
     * @notice Rules for distributing rewards for different checkpoint types
     * @param checkpointType The type of checkpoint this rule applies to
     * @param baseReward Base reward amount before multipliers
     * @param maxStreakMultiplier Maximum multiplier from streaks (in basis points)
     * @param dailyLimit Maximum checkpoints of this type per day
     * @param weeklyLimit Maximum checkpoints of this type per week
     * @param isActive Whether this rule is currently active
     * @param gamingPrevention Minimum time between same type rewards
     */
    struct RewardDistributionRule {
        string checkpointType;
        uint256 baseReward;
        uint256 maxStreakMultiplier;
        uint256 dailyLimit;
        uint256 weeklyLimit;
        bool isActive;
        uint256 gamingPrevention;
    }

    /**
     * @notice System for validating activity and preventing gaming
     * @param lastDailyLogin Last login timestamp for each student
     * @param weeklyActivities Weekly activity counts by week number
     * @param lastCheckpointTime Last checkpoint time by type for each student
     * @param suspiciousActivityScore Score tracking suspicious behavior
     */
    struct ActivityValidator {
        mapping(address => uint256) lastDailyLogin;
        mapping(address => mapping(uint256 => uint256)) weeklyActivities;
        mapping(address => mapping(string => uint256)) lastCheckpointTime;
        mapping(address => uint256) suspiciousActivityScore;
    }

    /// @notice Mapping from checkpoint ID to reward checkpoint data
    mapping(uint256 => RewardCheckpoint) public rewardCheckpoints;

    /// @notice Mapping from student address to their reward profile
    mapping(address => StudentRewardProfile) private studentProfiles;

    /// @notice Mapping from checkpoint type to distribution rules
    mapping(string => RewardDistributionRule) public distributionRules;

    /// @dev Activity validation system for preventing gaming
    ActivityValidator private validator;

    /// @dev Counter for generating unique checkpoint IDs
    uint256 private _checkpointIds;

    /// @notice Total amount available in the reward pool
    uint256 public totalRewardPool;

    /// @notice Total amount of rewards distributed
    uint256 public distributedRewards;

    /// @notice Array of active checkpoint types
    string[] public activeCheckpointTypes;

    /// @notice Emitted when a student earns a checkpoint
    event CheckpointEarned(uint256 indexed checkpointId, address indexed student, string checkpointType, uint256 amount);

    /// @notice Emitted when a student claims their rewards
    event RewardClaimed(address indexed student, uint256 amount, uint256 checkpointsCount);

    /// @notice Emitted when a student's streak is updated
    event StreakUpdated(address indexed student, uint256 newStreak, string checkpointType);

    /// @notice Emitted when suspicious activity is detected
    event SuspiciousActivityDetected(address indexed student, string reason, uint256 score);

    /// @notice Emitted when reward rules are updated
    event RewardRuleUpdated(string checkpointType, uint256 baseReward, uint256 maxMultiplier);

    /// @notice Emitted when the reward pool is updated
    event RewardPoolUpdated(uint256 oldPool, uint256 newPool);

    /**
     * @notice Initializes the MicroRewardsSystem contract
     * @dev Sets up roles and initializes default reward rules
     */
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(REWARDS_DISTRIBUTOR_ROLE, msg.sender);

        // Initialize default reward rules
        _initializeDefaultRewardRules();
    }

    function _initializeDefaultRewardRules() private {
        // Daily login rewards
        distributionRules["daily_login"] = RewardDistributionRule({
            checkpointType: "daily_login",
            baseReward: 0.001 ether,
            maxStreakMultiplier: 300, // 3x max
            dailyLimit: 1,
            weeklyLimit: 7,
            isActive: true,
            gamingPrevention: 20 hours // Must wait 20 hours between logins
        });

        // Weekly consistency rewards
        distributionRules["weekly_consistency"] = RewardDistributionRule({
            checkpointType: "weekly_consistency",
            baseReward: 0.005 ether,
            maxStreakMultiplier: 200, // 2x max
            dailyLimit: 0,
            weeklyLimit: 1,
            isActive: true,
            gamingPrevention: 6 days
        });

        // Milestone progress rewards
        distributionRules["milestone_progress"] = RewardDistributionRule({
            checkpointType: "milestone_progress",
            baseReward: 0.002 ether,
            maxStreakMultiplier: 150,
            dailyLimit: 3,
            weeklyLimit: 15,
            isActive: true,
            gamingPrevention: 2 hours
        });

        // Peer help rewards
        distributionRules["peer_help"] = RewardDistributionRule({
            checkpointType: "peer_help",
            baseReward: 0.0015 ether,
            maxStreakMultiplier: 200,
            dailyLimit: 5,
            weeklyLimit: 20,
            isActive: true,
            gamingPrevention: 1 hours
        });

        activeCheckpointTypes = ["daily_login", "weekly_consistency", "milestone_progress", "peer_help"];
    }

    function earnCheckpoint(
        address student,
        string memory checkpointType,
        string memory evidenceHash
    ) external onlyRole(REWARDS_DISTRIBUTOR_ROLE) whenNotPaused nonReentrant returns (uint256) {
        require(distributionRules[checkpointType].isActive, "Checkpoint type not active");
        require(_isValidStudent(student), "Invalid student");

        // Anti-gaming checks
        require(_passesGamingPrevention(student, checkpointType), "Gaming prevention triggered");
        require(!_isSuspiciousActivity(student), "Suspicious activity detected");

        // Check daily and weekly limits
        require(_checkDailyLimit(student, checkpointType), "Daily limit exceeded");
        require(_checkWeeklyLimit(student, checkpointType), "Weekly limit exceeded");

        // Calculate reward amount with streak multiplier
        uint256 rewardAmount = _calculateRewardAmount(student, checkpointType);
        require(totalRewardPool >= rewardAmount, "Insufficient reward pool");

        // Create checkpoint
        _checkpointIds++;
        uint256 checkpointId = _checkpointIds;

        StudentRewardProfile storage profile = studentProfiles[student];
        uint256 streakMultiplier = _updateStreak(student, checkpointType);

        rewardCheckpoints[checkpointId] = RewardCheckpoint({
            id: checkpointId,
            student: student,
            checkpointType: checkpointType,
            rewardAmount: rewardAmount,
            streakMultiplier: streakMultiplier,
            evidenceHash: evidenceHash,
            timestamp: block.timestamp,
            isClaimed: false,
            claimedAt: 0
        });

        // Update student profile
        profile.totalEarned += rewardAmount;
        profile.pendingRewards += rewardAmount;
        profile.checkpointCounts[checkpointType]++;
        profile.lastActivityDate = block.timestamp;

        // Update activity tracking
        _updateActivityTracking(student, checkpointType);

        totalRewardPool -= rewardAmount;
        distributedRewards += rewardAmount;

        emit CheckpointEarned(checkpointId, student, checkpointType, rewardAmount);
        return checkpointId;
    }

    function _calculateRewardAmount(address student, string memory checkpointType) 
        private view returns (uint256) {
        RewardDistributionRule memory rule = distributionRules[checkpointType];
        StudentRewardProfile storage profile = studentProfiles[student];

        uint256 baseReward = rule.baseReward;

        // Apply streak multiplier
        uint256 streakBonus = 0;
        if (profile.currentStreak > 1) {
            uint256 multiplier = profile.currentStreak * 100 / 10; // 10% per streak day
            if (multiplier > rule.maxStreakMultiplier) {
                multiplier = rule.maxStreakMultiplier;
            }
            streakBonus = (baseReward * multiplier) / 100;
        }

        return baseReward + streakBonus;
    }

    function _updateStreak(address student, string memory checkpointType) 
        private returns (uint256) {
        StudentRewardProfile storage profile = studentProfiles[student];

        // Check if this continues a streak
        uint256 daysSinceLastActivity = (block.timestamp - profile.lastActivityDate) / 1 days;

        if (daysSinceLastActivity <= 1) {
            profile.currentStreak++;
            if (profile.currentStreak > profile.longestStreak) {
                profile.longestStreak = profile.currentStreak;
            }
        } else if (daysSinceLastActivity > 1) {
            // Streak broken
            profile.currentStreak = 1;
        }

        emit StreakUpdated(student, profile.currentStreak, checkpointType);
        return profile.currentStreak;
    }

    function _passesGamingPrevention(address student, string memory checkpointType) 
        private view returns (bool) {
        RewardDistributionRule memory rule = distributionRules[checkpointType];
        uint256 lastTime = validator.lastCheckpointTime[student][checkpointType];

        if (lastTime == 0) return true;

        return (block.timestamp - lastTime) >= rule.gamingPrevention;
    }

    function _isSuspiciousActivity(address student) private view returns (bool) {
        return validator.suspiciousActivityScore[student] >= SUSPICIOUS_ACTIVITY_THRESHOLD;
    }

    function _checkDailyLimit(address student, string memory checkpointType) 
        private view returns (bool) {
        RewardDistributionRule memory rule = distributionRules[checkpointType];
        if (rule.dailyLimit == 0) return true;

        // Count checkpoints earned today
        uint256 today = block.timestamp / 1 days;
        uint256 todayCount = 0;

        // This is simplified - in production, you'd want a more efficient way to track daily counts
        // Consider using a mapping of day => checkpoint count

        return todayCount < rule.dailyLimit;
    }

    function _checkWeeklyLimit(address student, string memory checkpointType) 
        private view returns (bool) {
        RewardDistributionRule memory rule = distributionRules[checkpointType];
        if (rule.weeklyLimit == 0) return true;

        uint256 currentWeek = block.timestamp / (7 days);
        uint256 weeklyCount = validator.weeklyActivities[student][currentWeek];

        return weeklyCount < rule.weeklyLimit;
    }

    function _updateActivityTracking(address student, string memory checkpointType) private {
        // Update last checkpoint time
        validator.lastCheckpointTime[student][checkpointType] = block.timestamp;

        // Update weekly activity count
        uint256 currentWeek = block.timestamp / (7 days);
        validator.weeklyActivities[student][currentWeek]++;

        // Update daily login if applicable
        if (keccak256(bytes(checkpointType)) == keccak256(bytes("daily_login"))) {
            validator.lastDailyLogin[student] = block.timestamp;
        }

        // Check for suspicious patterns and update score
        _updateSuspiciousActivityScore(student, checkpointType);
    }

    function _updateSuspiciousActivityScore(address student, string memory checkpointType) private {
        uint256 currentScore = validator.suspiciousActivityScore[student];

        // Check for rapid-fire claiming (multiple checkpoints in short time)
        uint256 recentActivity = 0;
        uint256 oneHourAgo = block.timestamp - 1 hours;

        // Count recent checkpoints (simplified implementation)
        // In production, use more sophisticated tracking

        if (recentActivity > 10) {
            validator.suspiciousActivityScore[student] += 25;
            emit SuspiciousActivityDetected(student, "Rapid claiming pattern", currentScore + 25);
        } else if (currentScore > 0) {
            // Gradually reduce score for normal behavior
            validator.suspiciousActivityScore[student] = currentScore > 5 ? currentScore - 5 : 0;
        }
    }

    function _isValidStudent(address student) private view returns (bool) {
        // This would check with the main SkillPays contract
        // Simplified for this implementation
        return student != address(0);
    }

    function claimRewards() external whenNotPaused nonReentrant {
        StudentRewardProfile storage profile = studentProfiles[msg.sender];
        require(profile.pendingRewards > 0, "No pending rewards");
        require(!_isSuspiciousActivity(msg.sender), "Account flagged for suspicious activity");

        uint256 amount = profile.pendingRewards;
        profile.pendingRewards = 0;
        profile.totalClaimed += amount;

        // Count claimed checkpoints for this claim
        uint256 claimedCount = 0;
        for (uint256 i = 1; i <= _checkpointIds; i++) {
            if (rewardCheckpoints[i].student == msg.sender && !rewardCheckpoints[i].isClaimed) {
                rewardCheckpoints[i].isClaimed = true;
                rewardCheckpoints[i].claimedAt = block.timestamp;
                profile.claimedCheckpoints[i] = true;
                claimedCount++;
            }
        }

        payable(msg.sender).transfer(amount);

        emit RewardClaimed(msg.sender, amount, claimedCount);
    }

    function claimSpecificCheckpoints(uint256[] memory checkpointIds) 
        external whenNotPaused nonReentrant {
        require(!_isSuspiciousActivity(msg.sender), "Account flagged for suspicious activity");

        StudentRewardProfile storage profile = studentProfiles[msg.sender];
        uint256 totalAmount = 0;

        for (uint256 i = 0; i < checkpointIds.length; i++) {
            uint256 checkpointId = checkpointIds[i];
            RewardCheckpoint storage checkpoint = rewardCheckpoints[checkpointId];

            require(checkpoint.student == msg.sender, "Not your checkpoint");
            require(!checkpoint.isClaimed, "Already claimed");

            checkpoint.isClaimed = true;
            checkpoint.claimedAt = block.timestamp;
            profile.claimedCheckpoints[checkpointId] = true;

            totalAmount += checkpoint.rewardAmount;
        }

        require(totalAmount > 0, "No rewards to claim");
        require(profile.pendingRewards >= totalAmount, "Insufficient pending rewards");

        profile.pendingRewards -= totalAmount;
        profile.totalClaimed += totalAmount;

        payable(msg.sender).transfer(totalAmount);

        emit RewardClaimed(msg.sender, totalAmount, checkpointIds.length);
    }

    // View functions
    function getStudentProfile(address student) external view returns (
        uint256 totalEarned,
        uint256 totalClaimed,
        uint256 pendingRewards,
        uint256 currentStreak,
        uint256 longestStreak,
        uint256 lastActivityDate
    ) {
        StudentRewardProfile storage profile = studentProfiles[student];
        return (
            profile.totalEarned,
            profile.totalClaimed,
            profile.pendingRewards,
            profile.currentStreak,
            profile.longestStreak,
            profile.lastActivityDate
        );
    }

    function getCheckpointDetails(uint256 checkpointId) external view returns (RewardCheckpoint memory) {
        return rewardCheckpoints[checkpointId];
    }

    function getRewardRule(string memory checkpointType) external view returns (RewardDistributionRule memory) {
        return distributionRules[checkpointType];
    }

    function getActiveCheckpointTypes() external view returns (string[] memory) {
        return activeCheckpointTypes;
    }

    function canEarnCheckpoint(address student, string memory checkpointType) external view returns (
        bool canEarn,
        string memory reason
    ) {
        if (!distributionRules[checkpointType].isActive) {
            return (false, "Checkpoint type not active");
        }

        if (_isSuspiciousActivity(student)) {
            return (false, "Suspicious activity detected");
        }

        if (!_passesGamingPrevention(student, checkpointType)) {
            return (false, "Gaming prevention cooldown");
        }

        if (!_checkDailyLimit(student, checkpointType)) {
            return (false, "Daily limit exceeded");
        }

        if (!_checkWeeklyLimit(student, checkpointType)) {
            return (false, "Weekly limit exceeded");
        }

        return (true, "");
    }

    function getStudentCheckpointCount(address student, string memory checkpointType) 
        external view returns (uint256) {
        return studentProfiles[student].checkpointCounts[checkpointType];
    }

    function getSuspiciousActivityScore(address student) external view returns (uint256) {
        return validator.suspiciousActivityScore[student];
    }

    // Admin functions
    function addToRewardPool() external payable onlyRole(ADMIN_ROLE) {
        uint256 oldPool = totalRewardPool;
        totalRewardPool += msg.value;
        emit RewardPoolUpdated(oldPool, totalRewardPool);
    }

    function updateRewardRule(
        string memory checkpointType,
        uint256 baseReward,
        uint256 maxStreakMultiplier,
        uint256 dailyLimit,
        uint256 weeklyLimit,
        uint256 gamingPrevention
    ) external onlyRole(ADMIN_ROLE) {
        distributionRules[checkpointType].baseReward = baseReward;
        distributionRules[checkpointType].maxStreakMultiplier = maxStreakMultiplier;
        distributionRules[checkpointType].dailyLimit = dailyLimit;
        distributionRules[checkpointType].weeklyLimit = weeklyLimit;
        distributionRules[checkpointType].gamingPrevention = gamingPrevention;

        emit RewardRuleUpdated(checkpointType, baseReward, maxStreakMultiplier);
    }

    function flagSuspiciousActivity(address student, uint256 scoreIncrease, string memory reason) 
        external onlyRole(ADMIN_ROLE) {
        validator.suspiciousActivityScore[student] += scoreIncrease;
        emit SuspiciousActivityDetected(student, reason, validator.suspiciousActivityScore[student]);
    }

    function clearSuspiciousActivity(address student) external onlyRole(ADMIN_ROLE) {
        validator.suspiciousActivityScore[student] = 0;
    }

    function emergencyWithdraw(uint256 amount) external onlyRole(ADMIN_ROLE) {
        require(amount <= totalRewardPool, "Insufficient pool balance");
        totalRewardPool -= amount;
        payable(msg.sender).transfer(amount);
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    receive() external payable {
        totalRewardPool += msg.value;
        emit RewardPoolUpdated(totalRewardPool - msg.value, totalRewardPool);
    }
}

contracts/PeerReviewSystem.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title PeerReviewSystem
 * @author SkillPays Team
 * @notice A comprehensive peer review system with anti-collusion mechanisms
 * @dev This contract manages peer reviews for student submissions with reputation staking
 */
contract PeerReviewSystem is AccessControl, ReentrancyGuard, Pausable {
    /// @notice Role for registered reviewers who can submit reviews
    bytes32 public constant REVIEWER_ROLE = keccak256("REVIEWER_ROLE");

    /// @notice Role for administrators who can manage the system
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    /// @notice Minimum number of reviews required per request
    uint256 public constant MIN_REVIEWS_REQUIRED = 3;

    /// @notice Maximum number of reviews allowed per request
    uint256 public constant MAX_REVIEWS_PER_REQUEST = 7;

    /// @notice Minimum stake required to become a reviewer
    uint256 public constant MIN_REVIEWER_STAKE = 0.1 ether;

    /// @notice Deadline for completing reviews (in hours)
    uint256 public constant REVIEW_DEADLINE_HOURS = 72;

    /// @notice Maximum reviews per reviewer per day (anti-spam)
    uint256 public constant MAX_REVIEWS_PER_REVIEWER_PER_DAY = 10;

    /// @notice Minimum time between reviews of the same student
    uint256 public constant MIN_TIME_BETWEEN_REVIEWS_SAME_STUDENT = 24 hours;

    /// @dev Custom errors for gas optimization
    error PeerReview__InsufficientStake();
    error PeerReview__AlreadyRegistered();
    error PeerReview__NotEnoughRequiredReviews();
    error PeerReview__TooManyRequiredReviews();
    error PeerReview__ReviewCompleted();
    error PeerReview__DeadlinePassed();
    error PeerReview__AlreadyReviewed();
    error PeerReview__InvalidScore();
    error PeerReview__CannotSelfReview();
    error PeerReview__AntiCollusionFailed();
    error PeerReview__ReviewNotCompleted();
    error PeerReview__InvalidReviewIndex();
    error PeerReview__ReviewerNotActive();

    /**
     * @notice Represents a review request for student submissions
     * @param id Unique identifier for this request
     * @param student The student who submitted work for review
     * @param bootcampId The ID of the bootcamp this submission belongs to
     * @param milestoneId The ID of the milestone being reviewed
     * @param submissionHash IPFS hash of the submission
     * @param createdAt Timestamp when the request was created
     * @param deadline Deadline for completing all reviews
     * @param isCompleted Whether all required reviews have been submitted
     * @param requiredReviews Number of reviews needed
     * @param completedReviews Number of reviews submitted so far
     */
    struct ReviewRequest {
        uint256 id;
        address student;
        uint256 bootcampId;
        uint256 milestoneId;
        string submissionHash;
        uint256 createdAt;
        uint256 deadline;
        bool isCompleted;
        uint256 requiredReviews;
        uint256 completedReviews;
    }

    /**
     * @notice Represents a single review from a peer reviewer
     * @param requestId The ID of the review request this belongs to
     * @param reviewer The address of the reviewer
     * @param score Numerical score from 0-100
     * @param feedback Textual feedback for the student
     * @param evidenceHash IPFS hash of review evidence/justification
     * @param submittedAt Timestamp when review was submitted
     * @param isVerified Whether this review has been verified
     * @param helpfulnessScore Peer rating of review quality (0-100)
     */
    struct Review {
        uint256 requestId;
        address reviewer;
        uint256 score;
        string feedback;
        string evidenceHash;
        uint256 submittedAt;
        bool isVerified;
        uint256 helpfulnessScore;
    }

    /**
     * @notice Profile information for registered peer reviewers
     * @param reviewerAddress The reviewer's address
     * @param totalReviews Total number of reviews completed
     * @param averageScore Average score given across all reviews
     * @param reputationScore Reputation score (0-1000)
     * @param specializations Bitmap representing areas of expertise
     * @param isActive Whether the reviewer is currently active
     * @param stakingAmount Amount of ETH staked by the reviewer
     * @param joinedAt Timestamp when reviewer registered
     */
    struct ReviewerProfile {
        address reviewerAddress;
        uint256 totalReviews;
        uint256 averageScore;
        uint256 reputationScore;
        uint256 specializations;
        bool isActive;
        uint256 stakingAmount;
        uint256 joinedAt;
    }

    /**
     * @notice Anti-collusion tracking metrics
     * @param reviewHistory Tracks review count between reviewer-student pairs
     * @param recentReviews Tracks recent review timestamps for each reviewer
     * @param requestReviewers Maps request IDs to their reviewers
     * @param reviewerReputationStake Tracks reputation stakes for slashing
     */
    struct AntiCollusionMetrics {
        mapping(address => mapping(address => uint256)) reviewHistory;
        mapping(address => uint256[]) recentReviews;
        mapping(uint256 => address[]) requestReviewers;
        mapping(address => uint256) reviewerReputationStake;
    }

    /// @notice Mapping from request ID to review request data
    mapping(uint256 => ReviewRequest) public reviewRequests;

    /// @notice Mapping from request ID to array of reviews
    mapping(uint256 => Review[]) public requestReviews;

    /// @notice Mapping from reviewer address to their profile
    mapping(address => ReviewerProfile) public reviewerProfiles;

    /// @notice Tracks whether a reviewer has reviewed a specific request
    mapping(uint256 => mapping(address => bool)) public hasReviewed;

    /// @dev Anti-collusion metrics for detecting suspicious behavior
    AntiCollusionMetrics private antiCollusion;

    /// @dev Counter for generating unique request IDs
    uint256 private _requestIds;

    /// @notice Emitted when a new review request is created
    event ReviewRequestCreated(uint256 indexed requestId, address indexed student, uint256 bootcampId);

    /// @notice Emitted when a reviewer submits a review
    event ReviewSubmitted(uint256 indexed requestId, address indexed reviewer, uint256 score);

    /// @notice Emitted when a new reviewer registers
    event ReviewerRegistered(address indexed reviewer, uint256 stakingAmount);

    /// @notice Emitted when all required reviews are completed
    event ReviewCompleted(uint256 indexed requestId, uint256 averageScore);

    /// @notice Emitted when potential collusion is detected
    event CollusionDetected(address indexed reviewer, address indexed student, string reason);

    /// @notice Emitted when a reviewer is penalized
    event ReviewerPenalized(address indexed reviewer, uint256 penaltyAmount, string reason);

    /**
     * @notice Initializes the PeerReviewSystem contract
     * @dev Sets up admin roles for contract management
     */
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    /**
     * @notice Registers a new peer reviewer with staking requirement
     * @param specializations Bitmap representing reviewer's areas of expertise
     * @dev Requires minimum stake and reviewer must not be already registered
     */
    function registerAsReviewer(uint256 specializations) external payable whenNotPaused {
        if (msg.value < MIN_REVIEWER_STAKE) revert PeerReview__InsufficientStake();
        if (reviewerProfiles[msg.sender].isActive) revert PeerReview__AlreadyRegistered();

        reviewerProfiles[msg.sender] = ReviewerProfile({
            reviewerAddress: msg.sender,
            totalReviews: 0,
            averageScore: 0,
            reputationScore: 100, // Start with 100 reputation
            specializations: specializations,
            isActive: true,
            stakingAmount: msg.value,
            joinedAt: block.timestamp
        });

        antiCollusion.reviewerReputationStake[msg.sender] = msg.value;

        _grantRole(REVIEWER_ROLE, msg.sender);

        emit ReviewerRegistered(msg.sender, msg.value);
    }

    /**
     * @notice Creates a new review request for a student submission
     * @param student The address of the student whose work needs review
     * @param bootcampId The ID of the bootcamp this submission belongs to
     * @param milestoneId The ID of the milestone being reviewed
     * @param submissionHash IPFS hash of the student's submission
     * @param requiredReviews Number of reviews required for completion
     * @return requestId The ID of the newly created review request
     * @dev Only admins can create review requests
     */
    function createReviewRequest(
        address student,
        uint256 bootcampId,
        uint256 milestoneId,
        string memory submissionHash,
        uint256 requiredReviews
    ) external onlyRole(ADMIN_ROLE) whenNotPaused returns (uint256) {
        if (requiredReviews < MIN_REVIEWS_REQUIRED) revert PeerReview__NotEnoughRequiredReviews();
        if (requiredReviews > MAX_REVIEWS_PER_REQUEST) revert PeerReview__TooManyRequiredReviews();

        _requestIds++;
        uint256 requestId = _requestIds;

        reviewRequests[requestId] = ReviewRequest({
            id: requestId,
            student: student,
            bootcampId: bootcampId,
            milestoneId: milestoneId,
            submissionHash: submissionHash,
            createdAt: block.timestamp,
            deadline: block.timestamp + (REVIEW_DEADLINE_HOURS * 1 hours),
            isCompleted: false,
            requiredReviews: requiredReviews,
            completedReviews: 0
        });

        emit ReviewRequestCreated(requestId, student, bootcampId);
        return requestId;
    }

    /**
     * @notice Submits a peer review for a student submission
     * @param requestId The ID of the review request
     * @param score Numerical score from 0-100
     * @param feedback Textual feedback for the student
     * @param evidenceHash IPFS hash of review evidence/justification
     * @dev Only registered reviewers can submit reviews, includes anti-collusion checks
     */
    function submitReview(
        uint256 requestId,
        uint256 score,
        string memory feedback,
        string memory evidenceHash
    ) external onlyRole(REVIEWER_ROLE) whenNotPaused nonReentrant {
        if (reviewRequests[requestId].isCompleted) revert PeerReview__ReviewCompleted();
        if (block.timestamp > reviewRequests[requestId].deadline) revert PeerReview__DeadlinePassed();
        if (hasReviewed[requestId][msg.sender]) revert PeerReview__AlreadyReviewed();
        if (score > 100) revert PeerReview__InvalidScore();

        ReviewRequest storage request = reviewRequests[requestId];
        if (request.student == msg.sender) revert PeerReview__CannotSelfReview();

        // Anti-collusion checks
        if (!_passesAntiCollusionChecks(msg.sender, request.student)) revert PeerReview__AntiCollusionFailed();

        Review memory review = Review({
            requestId: requestId,
            reviewer: msg.sender,
            score: score,
            feedback: feedback,
            evidenceHash: evidenceHash,
            submittedAt: block.timestamp,
            isVerified: false,
            helpfulnessScore: 0
        });

        requestReviews[requestId].push(review);
        hasReviewed[requestId][msg.sender] = true;
        request.completedReviews++;

        // Update anti-collusion metrics
        _updateAntiCollusionMetrics(msg.sender, request.student, requestId);

        // Update reviewer profile
        _updateReviewerProfile(msg.sender, score);

        emit ReviewSubmitted(requestId, msg.sender, score);

        // Check if review is complete
        if (request.completedReviews >= request.requiredReviews) {
            _completeReview(requestId);
        }
    }

    function _passesAntiCollusionChecks(address reviewer, address student) private view returns (bool) {
        // Check 1: Not too many reviews of same student
        if (antiCollusion.reviewHistory[reviewer][student] >= 5) {
            return false;
        }

        // Check 2: Minimum time between reviews of same student
        uint256[] memory recentReviews = antiCollusion.recentReviews[reviewer];
        if (recentReviews.length > 0) {
            uint256 lastReviewTime = recentReviews[recentReviews.length - 1];
            if (block.timestamp - lastReviewTime < MIN_TIME_BETWEEN_REVIEWS_SAME_STUDENT) {
                return false;
            }
        }

        // Check 3: Daily review limit
        uint256 reviewsToday = 0;
        uint256 oneDayAgo = block.timestamp - 1 days;
        for (uint256 i = 0; i < recentReviews.length; i++) {
            if (recentReviews[i] >= oneDayAgo) {
                reviewsToday++;
            }
        }
        if (reviewsToday >= MAX_REVIEWS_PER_REVIEWER_PER_DAY) {
            return false;
        }

        // Check 4: Reviewer has sufficient reputation
        if (reviewerProfiles[reviewer].reputationScore < 50) {
            return false;
        }

        return true;
    }

    function _updateAntiCollusionMetrics(address reviewer, address student, uint256 requestId) private {
        // Update review history
        antiCollusion.reviewHistory[reviewer][student]++;

        // Update recent reviews
        antiCollusion.recentReviews[reviewer].push(block.timestamp);

        // Keep only last 50 recent reviews to manage gas costs
        if (antiCollusion.recentReviews[reviewer].length > 50) {
            for (uint256 i = 0; i < 49; i++) {
                antiCollusion.recentReviews[reviewer][i] = antiCollusion.recentReviews[reviewer][i + 1];
            }
            antiCollusion.recentReviews[reviewer].pop();
        }

        // Add to request reviewers
        antiCollusion.requestReviewers[requestId].push(reviewer);
    }

    function _updateReviewerProfile(address reviewer, uint256 score) private {
        ReviewerProfile storage profile = reviewerProfiles[reviewer];

        // Update average score
        uint256 totalScore = (profile.averageScore * profile.totalReviews) + score;
        profile.totalReviews++;
        profile.averageScore = totalScore / profile.totalReviews;

        // Update reputation based on consistency and quality
        if (score >= 70 && score <= 90) {
            // Reasonable scores increase reputation slightly
            profile.reputationScore = profile.reputationScore + 1;
            if (profile.reputationScore > 1000) profile.reputationScore = 1000;
        } else if (score < 30 || score > 95) {
            // Extreme scores decrease reputation
            if (profile.reputationScore > 2) {
                profile.reputationScore = profile.reputationScore - 2;
            }
        }
    }

    function _completeReview(uint256 requestId) private {
        ReviewRequest storage request = reviewRequests[requestId];
        request.isCompleted = true;

        // Calculate average score
        Review[] memory reviews = requestReviews[requestId];
        uint256 totalScore = 0;
        for (uint256 i = 0; i < reviews.length; i++) {
            totalScore += reviews[i].score;
        }
        uint256 averageScore = totalScore / reviews.length;

        // Detect potential collusion based on score clustering
        _detectScoreCollusion(requestId, averageScore);

        emit ReviewCompleted(requestId, averageScore);
    }

    function _detectScoreCollusion(uint256 requestId, uint256 averageScore) private {
        Review[] memory reviews = requestReviews[requestId];

        // Check for suspicious score patterns
        uint256 identicalScores = 0;
        uint256 veryCloseScores = 0;

        for (uint256 i = 0; i < reviews.length; i++) {
            for (uint256 j = i + 1; j < reviews.length; j++) {
                if (reviews[i].score == reviews[j].score) {
                    identicalScores++;
                } else if (_abs(reviews[i].score, reviews[j].score) <= 3) {
                    veryCloseScores++;
                }
            }
        }

        // Flag potential collusion
        if (identicalScores > reviews.length / 2 || veryCloseScores > reviews.length * 2 / 3) {
            for (uint256 i = 0; i < reviews.length; i++) {
                emit CollusionDetected(reviews[i].reviewer, reviewRequests[requestId].student, "Suspicious score clustering");
                _penalizeReviewer(reviews[i].reviewer, "Score clustering");
            }
        }
    }

    function _abs(uint256 a, uint256 b) private pure returns (uint256) {
        return a > b ? a - b : b - a;
    }

    function _penalizeReviewer(address reviewer, string memory reason) private {
        ReviewerProfile storage profile = reviewerProfiles[reviewer];

        // Reduce reputation
        if (profile.reputationScore > 10) {
            profile.reputationScore -= 10;
        }

        // Slash staking amount
        uint256 penalty = profile.stakingAmount / 20; // 5% penalty
        if (penalty > 0) {
            profile.stakingAmount -= penalty;
            // Send penalty to treasury (simplified - would need treasury address)
        }

        emit ReviewerPenalized(reviewer, penalty, reason);

        // Suspend reviewer if reputation too low
        if (profile.reputationScore < 30) {
            profile.isActive = false;
            _revokeRole(REVIEWER_ROLE, reviewer);
        }
    }

    /**
     * @notice Allows users to rate the helpfulness of a review
     * @param requestId The ID of the review request
     * @param reviewIndex The index of the review to rate
     * @param rating The helpfulness rating (0-100)
     * @dev Can only rate reviews for completed requests
     */
    function rateReviewHelpfulness(uint256 requestId, uint256 reviewIndex, uint256 rating) 
        external whenNotPaused {
        if (!reviewRequests[requestId].isCompleted) revert PeerReview__ReviewNotCompleted();
        if (rating > 100) revert PeerReview__InvalidScore();
        if (reviewIndex >= requestReviews[requestId].length) revert PeerReview__InvalidReviewIndex();

        Review storage review = requestReviews[requestId][reviewIndex];
        review.helpfulnessScore = (review.helpfulnessScore + rating) / 2; // Simple averaging

        // Update reviewer reputation based on helpfulness
        if (rating >= 80) {
            reviewerProfiles[review.reviewer].reputationScore++;
        } else if (rating <= 30) {
            if (reviewerProfiles[review.reviewer].reputationScore > 1) {
                reviewerProfiles[review.reviewer].reputationScore--;
            }
        }
    }

    /**
     * @notice Gets a review request by ID
     * @param requestId The ID of the review request
     * @return request The review request data
     */
    function getReviewRequest(uint256 requestId) external view returns (ReviewRequest memory) {
        return reviewRequests[requestId];
    }

    /**
     * @notice Gets all reviews for a specific request
     * @param requestId The ID of the review request
     * @return reviews Array of reviews for this request
     */
    function getReviews(uint256 requestId) external view returns (Review[] memory) {
        return requestReviews[requestId];
    }

    /**
     * @notice Gets a reviewer's profile information
     * @param reviewer The address of the reviewer
     * @return profile The reviewer's profile data
     */
    function getReviewerProfile(address reviewer) external view returns (ReviewerProfile memory) {
        return reviewerProfiles[reviewer];
    }

    /**
     * @notice Gets the review history between a reviewer and student
     * @param reviewer The address of the reviewer
     * @param student The address of the student
     * @return count Number of times this reviewer has reviewed this student
     */
    function getReviewHistory(address reviewer, address student) external view returns (uint256) {
        return antiCollusion.reviewHistory[reviewer][student];
    }

    /**
     * @notice Checks if a reviewer can review a specific student
     * @param reviewer The address of the reviewer
     * @param student The address of the student
     * @return canReview Whether the reviewer passes all anti-collusion checks
     */
    function canReview(address reviewer, address student) external view returns (bool) {
        if (!reviewerProfiles[reviewer].isActive) return false;
        if (!hasRole(REVIEWER_ROLE, reviewer)) return false;
        return _passesAntiCollusionChecks(reviewer, student);
    }

    /**
     * @notice Calculates the average score for a completed review request
     * @param requestId The ID of the review request
     * @return averageScore The average of all submitted scores
     */
    function getAverageScore(uint256 requestId) external view returns (uint256) {
        Review[] memory reviews = requestReviews[requestId];
        if (reviews.length == 0) return 0;

        uint256 totalScore = 0;
        for (uint256 i = 0; i < reviews.length; i++) {
            totalScore += reviews[i].score;
        }
        return totalScore / reviews.length;
    }

    /**
     * @notice Allows admin to add additional stake for a reviewer
     * @param reviewer The address of the reviewer
     * @dev Only active reviewers can receive additional stake
     */
    function addReviewerStake(address reviewer) external payable onlyRole(ADMIN_ROLE) {
        if (!reviewerProfiles[reviewer].isActive) revert PeerReview__ReviewerNotActive();
        reviewerProfiles[reviewer].stakingAmount += msg.value;
        antiCollusion.reviewerReputationStake[reviewer] += msg.value;
    }

    /**
     * @notice Allows admin to penalize a reviewer in emergency situations
     * @param reviewer The address of the reviewer to penalize
     * @param reason The reason for the penalty
     * @dev Should be used carefully as it affects reviewer reputation and stake
     */
    function emergencyPenalizeReviewer(address reviewer, string memory reason) 
        external onlyRole(ADMIN_ROLE) {
        _penalizeReviewer(reviewer, reason);
    }

    /**
     * @notice Pauses the contract, preventing new reviews and registrations
     * @dev Only admins can pause the contract
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @notice Unpauses the contract, allowing normal operations
     * @dev Only admins can unpause the contract
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

contracts/SkillGraph.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SkillGraph
 * @author SkillPays Team
 * @notice A dynamic skill tracking system that maps student competencies and skill relationships
 * @dev This contract manages skill creation, evidence tracking, and competency progression
 */
contract SkillGraph is AccessControl, Pausable, ReentrancyGuard {
    /// @notice Role for entities that can update skills and evidence
    bytes32 public constant SKILL_UPDATER_ROLE = keccak256("SKILL_UPDATER_ROLE");

    /// @notice Maximum confidence score for skill evidence
    uint256 public constant MAX_CONFIDENCE_SCORE = 100;

    /// @notice Maximum strength weight for skill relationships
    uint256 public constant MAX_STRENGTH_WEIGHT = 100;

    /// @notice Number of skill levels (0-4: None, Beginner, Intermediate, Advanced, Expert)
    uint256 public constant MAX_SKILL_LEVEL = 4;

    /// @dev Custom errors for gas optimization
    error SkillGraph__SkillNameEmpty();
    error SkillGraph__SkillAlreadyExists();
    error SkillGraph__SkillNotActive();
    error SkillGraph__InvalidConfidenceScore();
    error SkillGraph__InvalidStrengthWeight();
    error SkillGraph__SelfPrerequisite();
    error SkillGraph__NoSkillEvidence();

    /**
     * @notice Represents a skill in the system
     * @param name The human-readable name of the skill
     * @param category The category this skill belongs to
     * @param description Detailed description of the skill
     * @param totalVerifications Total number of times this skill has been verified
     * @param isActive Whether this skill is currently active
     * @param createdAt Timestamp when this skill was created
     */
    struct Skill {
        string name;
        string category;
        string description;
        uint256 totalVerifications;
        bool isActive;
        uint256 createdAt;
    }

    /**
     * @notice Evidence supporting a student's skill competency
     * @param skillId The ID of the skill this evidence supports
     * @param student The address of the student this evidence belongs to
     * @param evidenceType Type of evidence (badge, project, peer_review, assessment)
     * @param evidenceData Additional data about the evidence
     * @param confidenceScore How confident we are in this evidence (0-100)
     * @param timestamp When this evidence was submitted
     * @param verifier Who verified this evidence
     * @param isVerified Whether this evidence has been verified
     */
    struct SkillEvidence {
        uint256 skillId;
        address student;
        string evidenceType;
        string evidenceData;
        uint256 confidenceScore;
        uint256 timestamp;
        address verifier;
        bool isVerified;
    }

    /**
     * @notice A student's complete skill profile
     * @param skillLevels Mapping from skill ID to level (0-4)
     * @param skillScores Mapping from skill ID to accumulated score
     * @param skillEvidences Mapping from skill ID to array of evidence
     * @param learnedSkills Array of skill IDs this student has learned
     * @param totalSkillPoints Total skill points across all skills
     * @param lastUpdated When this profile was last updated
     */
    struct StudentSkillProfile {
        mapping(uint256 => uint256) skillLevels;
        mapping(uint256 => uint256) skillScores;
        mapping(uint256 => SkillEvidence[]) skillEvidences;
        uint256[] learnedSkills;
        uint256 totalSkillPoints;
        uint256 lastUpdated;
    }

    /**
     * @notice Represents a prerequisite relationship between skills
     * @param prerequisiteSkillId The skill that is required first
     * @param dependentSkillId The skill that depends on the prerequisite
     * @param strengthWeight How strong this relationship is (0-100)
     * @param isActive Whether this relationship is currently active
     */
    struct SkillRelationship {
        uint256 prerequisiteSkillId;
        uint256 dependentSkillId;
        uint256 strengthWeight;
        bool isActive;
    }

    /// @notice Mapping from skill ID to skill data
    mapping(uint256 => Skill) public skills;

    /// @notice Mapping from student address to their skill profile
    mapping(address => StudentSkillProfile) private studentProfiles;

    /// @notice Mapping from skill ID to its prerequisites
    mapping(uint256 => SkillRelationship[]) public skillPrerequisites;

    /// @notice Mapping from skill ID to skills that depend on it
    mapping(uint256 => SkillRelationship[]) public skillDependents;

    /// @notice Mapping from skill name to skill ID for quick lookup
    mapping(string => uint256) public skillNameToId;

    /// @dev Counter for generating unique skill IDs
    uint256 private _skillIds;

    /// @dev Counter for generating unique evidence IDs
    uint256 private _evidenceIds;

    /// @notice Emitted when a new skill is created
    event SkillCreated(uint256 indexed skillId, string name, string category);

    /// @notice Emitted when skill evidence is added for a student
    event SkillEvidenceAdded(uint256 indexed evidenceId, address indexed student, uint256 indexed skillId);

    /// @notice Emitted when a student's skill level is updated
    event SkillLevelUpdated(address indexed student, uint256 indexed skillId, uint256 oldLevel, uint256 newLevel);

    /// @notice Emitted when a skill relationship is added
    event SkillRelationshipAdded(uint256 indexed prerequisiteId, uint256 indexed dependentId);

    /// @notice Emitted when a student's skill is verified
    event SkillVerified(address indexed student, uint256 indexed skillId, address verifier);

    /**
     * @notice Initializes the SkillGraph contract
     * @dev Sets up roles and creates initial common skills
     */
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(SKILL_UPDATER_ROLE, msg.sender);

        // Initialize common skills
        _initializeCommonSkills();
    }

    /**
     * @dev Initializes common skills used across the platform
     * @dev Called during contract deployment to set up base skills
     */
    function _initializeCommonSkills() private {
        // Web3 Development Skills
        createSkill("Solidity Programming", "Smart Contracts", "Ability to write secure smart contracts in Solidity");
        createSkill("Web3 Frontend", "Frontend", "Building decentralized applications frontend");
        createSkill("DeFi Protocols", "Finance", "Understanding and implementing DeFi mechanisms");
        createSkill("NFT Development", "Tokens", "Creating and managing NFT contracts and marketplaces");
        createSkill("Blockchain Security", "Security", "Identifying and preventing smart contract vulnerabilities");

        // Traditional Programming Skills
        createSkill("JavaScript", "Programming", "Proficiency in JavaScript programming");
        createSkill("Python", "Programming", "Python programming and scripting");
        createSkill("React", "Frontend", "Building user interfaces with React");
        createSkill("Node.js", "Backend", "Server-side JavaScript development");
        createSkill("Database Management", "Backend", "Managing and designing databases");

        // Add skill relationships
        addSkillRelationship(skillNameToId["JavaScript"], skillNameToId["Web3 Frontend"], 80);
        addSkillRelationship(skillNameToId["JavaScript"], skillNameToId["React"], 90);
        addSkillRelationship(skillNameToId["Solidity Programming"], skillNameToId["DeFi Protocols"], 85);
        addSkillRelationship(skillNameToId["Solidity Programming"], skillNameToId["NFT Development"], 75);
    }

    /**
     * @notice Creates a new skill in the system
     * @param name The name of the skill
     * @param category The category this skill belongs to
     * @param description A detailed description of the skill
     * @return skillId The ID of the newly created skill
     * @dev Only accounts with SKILL_UPDATER_ROLE can create skills
     */
    function createSkill(string memory name, string memory category, string memory description) 
        public onlyRole(SKILL_UPDATER_ROLE) returns (uint256) {
        if (bytes(name).length == 0) revert SkillGraph__SkillNameEmpty();
        if (skillNameToId[name] != 0) revert SkillGraph__SkillAlreadyExists();

        _skillIds++;
        uint256 skillId = _skillIds;

        skills[skillId] = Skill({
            name: name,
            category: category,
            description: description,
            totalVerifications: 0,
            isActive: true,
            createdAt: block.timestamp
        });

        skillNameToId[name] = skillId;

        emit SkillCreated(skillId, name, category);
        return skillId;
    }

    /**
     * @notice Adds evidence for a student's skill competency
     * @param student The address of the student
     * @param skillId The ID of the skill the evidence supports
     * @param evidenceType The type of evidence (badge, project, peer_review, assessment)
     * @param evidenceData Additional data about the evidence
     * @param confidenceScore How confident we are in this evidence (0-100)
     * @return evidenceId The ID of the newly created evidence
     * @dev Only accounts with SKILL_UPDATER_ROLE can add evidence
     */
    function addSkillEvidence(
        address student,
        uint256 skillId,
        string memory evidenceType,
        string memory evidenceData,
        uint256 confidenceScore
    ) external onlyRole(SKILL_UPDATER_ROLE) whenNotPaused nonReentrant returns (uint256) {
        if (!skills[skillId].isActive) revert SkillGraph__SkillNotActive();
        if (confidenceScore > MAX_CONFIDENCE_SCORE) revert SkillGraph__InvalidConfidenceScore();

        _evidenceIds++;
        uint256 evidenceId = _evidenceIds;

        SkillEvidence memory evidence = SkillEvidence({
            skillId: skillId,
            student: student,
            evidenceType: evidenceType,
            evidenceData: evidenceData,
            confidenceScore: confidenceScore,
            timestamp: block.timestamp,
            verifier: msg.sender,
            isVerified: true
        });

        StudentSkillProfile storage profile = studentProfiles[student];
        profile.skillEvidences[skillId].push(evidence);

        // Update skill score and level
        _updateStudentSkillLevel(student, skillId, confidenceScore);

        emit SkillEvidenceAdded(evidenceId, student, skillId);
        return evidenceId;
    }

    /**
     * @dev Updates a student's skill level based on new evidence
     * @param student The address of the student
     * @param skillId The ID of the skill being updated
     * @param newScore The new score to add to the student's skill
     */
    function _updateStudentSkillLevel(address student, uint256 skillId, uint256 newScore) private {
        StudentSkillProfile storage profile = studentProfiles[student];

        // Add to existing score
        uint256 oldScore = profile.skillScores[skillId];
        uint256 totalScore = oldScore + newScore;
        profile.skillScores[skillId] = totalScore;

        // Calculate new level (0-4 scale)
        uint256 oldLevel = profile.skillLevels[skillId];
        uint256 newLevel = _calculateSkillLevel(totalScore);

        if (newLevel != oldLevel) {
            profile.skillLevels[skillId] = newLevel;

            // Add to learned skills if first time learning
            if (oldLevel == 0) {
                profile.learnedSkills.push(skillId);
            }

            // Update total skill points
            profile.totalSkillPoints = profile.totalSkillPoints - oldLevel + newLevel;
            profile.lastUpdated = block.timestamp;

            emit SkillLevelUpdated(student, skillId, oldLevel, newLevel);
        }

        // Update global skill verification count
        skills[skillId].totalVerifications++;
    }

    /**
     * @dev Calculates skill level based on total accumulated score
     * @param totalScore The total score accumulated for this skill
     * @return level The skill level (0-4)
     */
    function _calculateSkillLevel(uint256 totalScore) private pure returns (uint256) {
        if (totalScore >= 400) return 4; // Expert
        if (totalScore >= 300) return 3; // Advanced
        if (totalScore >= 200) return 2; // Intermediate
        if (totalScore >= 100) return 1; // Beginner
        return 0; // No skill
    }

    /**
     * @notice Adds a prerequisite relationship between two skills
     * @param prerequisiteSkillId The skill that must be learned first
     * @param dependentSkillId The skill that depends on the prerequisite
     * @param strengthWeight How strong this relationship is (0-100)
     * @dev Only accounts with SKILL_UPDATER_ROLE can add relationships
     */
    function addSkillRelationship(uint256 prerequisiteSkillId, uint256 dependentSkillId, uint256 strengthWeight)
        public onlyRole(SKILL_UPDATER_ROLE) {
        if (!skills[prerequisiteSkillId].isActive) revert SkillGraph__SkillNotActive();
        if (!skills[dependentSkillId].isActive) revert SkillGraph__SkillNotActive();
        if (prerequisiteSkillId == dependentSkillId) revert SkillGraph__SelfPrerequisite();
        if (strengthWeight > MAX_STRENGTH_WEIGHT) revert SkillGraph__InvalidStrengthWeight();

        SkillRelationship memory relationship = SkillRelationship({
            prerequisiteSkillId: prerequisiteSkillId,
            dependentSkillId: dependentSkillId,
            strengthWeight: strengthWeight,
            isActive: true
        });

        skillPrerequisites[dependentSkillId].push(relationship);
        skillDependents[prerequisiteSkillId].push(relationship);

        emit SkillRelationshipAdded(prerequisiteSkillId, dependentSkillId);
    }

    /**
     * @notice Verifies a student's competency in a specific skill
     * @param student The address of the student
     * @param skillId The ID of the skill to verify
     * @dev Only accounts with SKILL_UPDATER_ROLE can verify skills
     * @dev Student must have existing evidence for the skill
     */
    function verifyStudentSkill(address student, uint256 skillId) 
        external onlyRole(SKILL_UPDATER_ROLE) {
        if (!skills[skillId].isActive) revert SkillGraph__SkillNotActive();
        if (studentProfiles[student].skillLevels[skillId] == 0) revert SkillGraph__NoSkillEvidence();

        emit SkillVerified(student, skillId, msg.sender);
    }

    /**
     * @notice Gets a student's level for a specific skill
     * @param student The address of the student
     * @param skillId The ID of the skill
     * @return level The student's level for this skill (0-4)
     */
    function getStudentSkillLevel(address student, uint256 skillId) external view returns (uint256) {
        return studentProfiles[student].skillLevels[skillId];
    }

    /**
     * @notice Gets a student's total score for a specific skill
     * @param student The address of the student
     * @param skillId The ID of the skill
     * @return score The student's accumulated score for this skill
     */
    function getStudentSkillScore(address student, uint256 skillId) external view returns (uint256) {
        return studentProfiles[student].skillScores[skillId];
    }

    /**
     * @notice Gets all skills that a student has learned (level > 0)
     * @param student The address of the student
     * @return skillIds Array of skill IDs the student has learned
     */
    function getStudentLearnedSkills(address student) external view returns (uint256[] memory) {
        return studentProfiles[student].learnedSkills;
    }

    /**
     * @notice Gets a student's total skill points across all skills
     * @param student The address of the student
     * @return totalPoints The sum of all skill levels
     */
    function getStudentTotalSkillPoints(address student) external view returns (uint256) {
        return studentProfiles[student].totalSkillPoints;
    }

    /**
     * @notice Gets all evidence for a student's specific skill
     * @param student The address of the student
     * @param skillId The ID of the skill
     * @return evidences Array of skill evidence for this student and skill
     */
    function getSkillEvidences(address student, uint256 skillId) external view returns (SkillEvidence[] memory) {
        return studentProfiles[student].skillEvidences[skillId];
    }

    /**
     * @notice Gets all prerequisites for a specific skill
     * @param skillId The ID of the skill
     * @return prerequisites Array of skills that are prerequisites for this skill
     */
    function getSkillPrerequisites(uint256 skillId) external view returns (SkillRelationship[] memory) {
        return skillPrerequisites[skillId];
    }

    /**
     * @notice Gets all skills that depend on a specific skill
     * @param skillId The ID of the skill
     * @return dependents Array of skills that depend on this skill
     */
    function getSkillDependents(uint256 skillId) external view returns (SkillRelationship[] memory) {
        return skillDependents[skillId];
    }

    /**
     * @notice Generates a complete skill profile for a student
     * @param student The address of the student
     * @return skillIds Array of skill IDs the student has learned
     * @return skillLevels Array of corresponding skill levels
     * @return skillScores Array of corresponding skill scores
     * @return totalSkillPoints Total skill points across all skills
     * @return profileLastUpdated When the profile was last updated
     */
    function generateSkillProfile(address student) external view returns (
        uint256[] memory skillIds,
        uint256[] memory skillLevels,
        uint256[] memory skillScores,
        uint256 totalSkillPoints,
        uint256 profileLastUpdated
    ) {
        StudentSkillProfile storage profile = studentProfiles[student];
        skillIds = profile.learnedSkills;

        skillLevels = new uint256[](skillIds.length);
        skillScores = new uint256[](skillIds.length);

        for (uint256 i = 0; i < skillIds.length; i++) {
            skillLevels[i] = profile.skillLevels[skillIds[i]];
            skillScores[i] = profile.skillScores[skillIds[i]];
        }

        totalSkillPoints = profile.totalSkillPoints;
        profileLastUpdated = profile.lastUpdated;
    }

    /**
     * @notice Gets detailed information about a specific skill
     * @param skillId The ID of the skill
     * @return skill The skill data structure
     */
    function getSkillInfo(uint256 skillId) external view returns (Skill memory) {
        return skills[skillId];
    }

    /**
     * @notice Gets skill information by name
     * @param name The name of the skill
     * @return skillId The ID of the skill
     * @return skill The skill data structure
     */
    function getSkillByName(string memory name) external view returns (uint256, Skill memory) {
        uint256 skillId = skillNameToId[name];
        return (skillId, skills[skillId]);
    }

    /**
     * @notice Calculates skill path recommendations for a target skill
     * @param student The address of the student
     * @param targetSkillId The ID of the target skill
     * @return recommendedSkills Array of prerequisite skill IDs
     * @return currentLevels Array of student's current levels for prerequisites
     */
    function calculateSkillPathRecommendation(address student, uint256 targetSkillId) 
        external view returns (uint256[] memory recommendedSkills, uint256[] memory currentLevels) {

        SkillRelationship[] memory prerequisites = skillPrerequisites[targetSkillId];
        recommendedSkills = new uint256[](prerequisites.length);
        currentLevels = new uint256[](prerequisites.length);

        for (uint256 i = 0; i < prerequisites.length; i++) {
            recommendedSkills[i] = prerequisites[i].prerequisiteSkillId;
            currentLevels[i] = studentProfiles[student].skillLevels[prerequisites[i].prerequisiteSkillId];
        }
    }

    /**
     * @notice Pauses the contract, preventing evidence submission
     * @dev Only accounts with DEFAULT_ADMIN_ROLE can pause
     */
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    /**
     * @notice Unpauses the contract, allowing evidence submission
     * @dev Only accounts with DEFAULT_ADMIN_ROLE can unpause
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }
}

contracts/SkillPaysCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";

/**
 * @title SkillPaysCore
 * @dev Main orchestrator contract for the SkillPays learning ecosystem
 * @notice This contract manages students, bootcamps, and milestone completions
 * @author SkillPays Team
 */
contract SkillPaysCore is AccessControl, ReentrancyGuard, Pausable {
    using Address for address payable;
    using Math for uint256;

    /// @dev Role identifiers using keccak256 for gas optimization
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant BOOTCAMP_CREATOR_ROLE = keccak256("BOOTCAMP_CREATOR_ROLE");
    bytes32 public constant MENTOR_ROLE = keccak256("MENTOR_ROLE");

    /// @dev Maximum platform fee in basis points (10%)
    uint256 public constant MAX_FEE = 1000;

    /// @dev Minimum and maximum bootcamp duration in days
    uint256 public constant MIN_BOOTCAMP_DURATION = 1;
    uint256 public constant MAX_BOOTCAMP_DURATION = 365;

    struct Student {
        string name;
        uint256 totalBadges;
        uint256 reputationScore;
        bool isActive;
        uint256 joinedAt;
    }

    struct Bootcamp {
        uint256 id;
        string name;
        string description;
        address creator;
        uint256 duration; // in days
        uint256 fee; // in wei
        bool isActive;
        uint256 createdAt;
        uint256 totalEnrollments;
        uint256 totalCompletions;
    }

    struct Milestone {
        uint256 id;
        uint256 bootcampId;
        string name;
        string description;
        uint256 requiredScore;
        bool requiresPeerReview;
        uint256 rewardAmount; // in wei
    }

    /// @dev State variables with explicit visibility
    mapping(address => Student) private _students;
    mapping(uint256 => Bootcamp) private _bootcamps;
    mapping(uint256 => Milestone[]) private _bootcampMilestones;
    mapping(address => mapping(uint256 => bool)) private _enrollments;
    mapping(address => mapping(uint256 => mapping(uint256 => bool))) private _completedMilestones;
    mapping(address => uint256[]) private _studentBootcamps;
    mapping(uint256 => address[]) private _bootcampStudents;

    /// @dev External contract addresses
    address private _badgeContract;
    address private _peerReviewContract;
    address private _leaderboardContract;
    address private _mentorBoostContract;
    address private _microRewardsContract;

    /// @dev Economic parameters
    uint256 private _platformFee; // in basis points
    address payable private _treasury;

    /// @dev Counter for unique IDs
    uint256 private _bootcampIdCounter;
    uint256 private _milestoneIdCounter;

    /// @dev Chainlink price feed for ETH/USD (optional)
    AggregatorV3Interface private _priceFeed;

    /// @dev Events following the Checks-Effects-Interactions pattern
    event StudentRegistered(address indexed student, string name, uint256 timestamp);
    event BootcampCreated(
        uint256 indexed bootcampId, 
        string name, 
        address indexed creator, 
        uint256 fee,
        uint256 duration
    );
    event StudentEnrolled(
        address indexed student, 
        uint256 indexed bootcampId, 
        uint256 amountPaid,
        uint256 timestamp
    );
    event MilestoneAdded(
        uint256 indexed bootcampId, 
        uint256 indexed milestoneId, 
        string name,
        uint256 requiredScore
    );
    event MilestoneCompleted(
        address indexed student, 
        uint256 indexed bootcampId, 
        uint256 indexed milestoneId,
        uint256 reputationGained
    );
    event ContractUpdated(
        string indexed contractType, 
        address indexed oldAddress, 
        address indexed newAddress
    );
    event PlatformFeeUpdated(uint256 oldFee, uint256 newFee);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    /// @dev Custom errors for gas optimization
    error InvalidAddress();
    error InvalidName();
    error InvalidDuration();
    error InvalidFee();
    error StudentNotRegistered();
    error StudentAlreadyRegistered();
    error BootcampNotFound();
    error BootcampNotActive();
    error MilestoneNotFound();
    error AlreadyEnrolled();
    error NotEnrolled();
    error InsufficientPayment();
    error MilestoneAlreadyCompleted();
    error NotBootcampCreator();
    error FeeExceedsMaximum();

    /// @dev Modifiers for access control and validation
    modifier onlyValidAddress(address _addr) {
        if (_addr == address(0)) revert InvalidAddress();
        _;
    }

    modifier onlyRegisteredStudent(address _student) {
        if (!_students[_student].isActive) revert StudentNotRegistered();
        _;
    }

    modifier onlyActiveBootcamp(uint256 _bootcampId) {
        if (!_bootcamps[_bootcampId].isActive) revert BootcampNotActive();
        _;
    }

    /**
     * @dev Constructor sets up the contract with initial parameters
     * @param treasuryAddress Address to receive platform fees
     * @param initialPlatformFee Initial platform fee in basis points
     * @param priceFeed Chainlink price feed address (optional)
     */
    constructor(
        address payable treasuryAddress,
        uint256 initialPlatformFee,
        address priceFeed
    ) onlyValidAddress(treasuryAddress) {
        if (initialPlatformFee > MAX_FEE) revert FeeExceedsMaximum();

        _treasury = treasuryAddress;
        _platformFee = initialPlatformFee;

        if (priceFeed != address(0)) {
            _priceFeed = AggregatorV3Interface(priceFeed);
        }

        // Set up roles
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(BOOTCAMP_CREATOR_ROLE, msg.sender);

        emit PlatformFeeUpdated(0, initialPlatformFee);
        emit TreasuryUpdated(address(0), treasuryAddress);
    }

    /**
     * @notice Register a new student in the system
     * @param name Display name for the student
     * @dev Emits StudentRegistered event
     */
    function registerStudent(string calldata name) 
        external 
        whenNotPaused 
    {
        if (bytes(name).length == 0) revert InvalidName();
        if (_students[msg.sender].isActive) revert StudentAlreadyRegistered();

        _students[msg.sender] = Student({
            name: name,
            totalBadges: 0,
            reputationScore: 0,
            isActive: true,
            joinedAt: block.timestamp
        });

        emit StudentRegistered(msg.sender, name, block.timestamp);
    }

    /**
     * @notice Create a new bootcamp
     * @param name Name of the bootcamp
     * @param description Description of the bootcamp
     * @param duration Duration in days
     * @param fee Fee in wei
     * @return bootcampId The ID of the created bootcamp
     */
    function createBootcamp(
        string calldata name,
        string calldata description,
        uint256 duration,
        uint256 fee
    ) 
        external 
        onlyRole(BOOTCAMP_CREATOR_ROLE) 
        whenNotPaused 
        returns (uint256 bootcampId) 
    {
        if (bytes(name).length == 0) revert InvalidName();
        if (duration < MIN_BOOTCAMP_DURATION || duration > MAX_BOOTCAMP_DURATION) {
            revert InvalidDuration();
        }

        bootcampId = ++_bootcampIdCounter;

        _bootcamps[bootcampId] = Bootcamp({
            id: bootcampId,
            name: name,
            description: description,
            creator: msg.sender,
            duration: duration,
            fee: fee,
            isActive: true,
            createdAt: block.timestamp,
            totalEnrollments: 0,
            totalCompletions: 0
        });

        emit BootcampCreated(bootcampId, name, msg.sender, fee, duration);
    }

    /**
     * @notice Add a milestone to a bootcamp
     * @param bootcampId ID of the bootcamp
     * @param name Name of the milestone
     * @param description Description of the milestone
     * @param requiredScore Required score to pass
     * @param requiresPeerReview Whether peer review is required
     * @param rewardAmount Reward amount for completion
     */
    function addMilestone(
        uint256 bootcampId,
        string calldata name,
        string calldata description,
        uint256 requiredScore,
        bool requiresPeerReview,
        uint256 rewardAmount
    ) 
        external 
        onlyRole(BOOTCAMP_CREATOR_ROLE) 
        onlyActiveBootcamp(bootcampId)
        whenNotPaused 
    {
        if (bytes(name).length == 0) revert InvalidName();
        if (_bootcamps[bootcampId].creator != msg.sender) revert NotBootcampCreator();

        uint256 milestoneId = ++_milestoneIdCounter;

        Milestone memory milestone = Milestone({
            id: milestoneId,
            bootcampId: bootcampId,
            name: name,
            description: description,
            requiredScore: requiredScore,
            requiresPeerReview: requiresPeerReview,
            rewardAmount: rewardAmount
        });

        _bootcampMilestones[bootcampId].push(milestone);

        emit MilestoneAdded(bootcampId, milestoneId, name, requiredScore);
    }

    /**
     * @notice Enroll in a bootcamp
     * @param bootcampId ID of the bootcamp to enroll in
     * @dev Handles payment distribution automatically
     */
    function enrollInBootcamp(uint256 bootcampId) 
        external 
        payable 
        onlyRegisteredStudent(msg.sender)
        onlyActiveBootcamp(bootcampId)
        whenNotPaused 
        nonReentrant 
    {
        if (_enrollments[msg.sender][bootcampId]) revert AlreadyEnrolled();

        Bootcamp storage bootcamp = _bootcamps[bootcampId];

        if (msg.value < bootcamp.fee) revert InsufficientPayment();

        // Update state first (Checks-Effects-Interactions)
        _enrollments[msg.sender][bootcampId] = true;
        _studentBootcamps[msg.sender].push(bootcampId);
        _bootcampStudents[bootcampId].push(msg.sender);
        bootcamp.totalEnrollments++;

        // Handle payment distribution
        if (msg.value > 0) {
            _distributePayment(bootcamp.creator, msg.value);
        }

        emit StudentEnrolled(msg.sender, bootcampId, msg.value, block.timestamp);
    }

    /**
     * @notice Complete a milestone
     * @param bootcampId ID of the bootcamp
     * @param milestoneId ID of the milestone
     * @param proof Proof of completion (could be IPFS hash)
     */
    function completeMilestone(
        uint256 bootcampId,
        uint256 milestoneId,
        bytes calldata proof
    ) 
        external 
        onlyRegisteredStudent(msg.sender)
        whenNotPaused 
        nonReentrant 
    {
        if (!_enrollments[msg.sender][bootcampId]) revert NotEnrolled();
        if (_completedMilestones[msg.sender][bootcampId][milestoneId]) {
            revert MilestoneAlreadyCompleted();
        }

        Milestone memory milestone = _getMilestone(bootcampId, milestoneId);
        if (milestone.id == 0) revert MilestoneNotFound();

        // Update state
        _completedMilestones[msg.sender][bootcampId][milestoneId] = true;

        Student storage student = _students[msg.sender];
        student.totalBadges++;
        student.reputationScore += milestone.requiredScore;

        // External interactions
        if (_badgeContract != address(0)) {
            _mintBadge(msg.sender, bootcampId, milestoneId, milestone.requiredScore);
        }

        if (milestone.rewardAmount > 0 && address(this).balance >= milestone.rewardAmount) {
            payable(msg.sender).sendValue(milestone.rewardAmount);
        }

        emit MilestoneCompleted(
            msg.sender, 
            bootcampId, 
            milestoneId, 
            milestone.requiredScore
        );
    }

    /**
     * @dev Internal function to distribute enrollment payments
     * @param creator Address of the bootcamp creator
     * @param amount Total payment amount
     */
    function _distributePayment(address creator, uint256 amount) private {
        uint256 feeAmount = (amount * _platformFee) / 10000;
        uint256 creatorAmount = amount - feeAmount;

        if (feeAmount > 0) {
            _treasury.sendValue(feeAmount);
        }

        if (creatorAmount > 0) {
            payable(creator).sendValue(creatorAmount);
        }
    }

    /**
     * @dev Internal function to mint badge via external contract
     * @param student Student address
     * @param bootcampId Bootcamp ID
     * @param milestoneId Milestone ID
     * @param score Achievement score
     */
    function _mintBadge(
        address student,
        uint256 bootcampId,
        uint256 milestoneId,
        uint256 score
    ) private {
        // Determine badge level based on score
        uint256 level = _calculateBadgeLevel(score);

        (bool success, ) = _badgeContract.call(
            abi.encodeWithSignature(
                "mintBadge(address,uint256,uint256,uint256,string,uint256,string)",
                student,
                bootcampId,
                milestoneId,
                level,
                "General Skills", // Could be made dynamic
                score,
                "" // Empty metadata URI - will use onchain generation
            )
        );

        // Log but don't revert if badge minting fails
        if (!success) {
            // Consider emitting an event for monitoring
        }
    }

    /**
     * @dev Calculate badge level based on score
     * @param score The achievement score
     * @return level Badge level (0-3)
     */
    function _calculateBadgeLevel(uint256 score) private pure returns (uint256 level) {
        if (score >= 95) return 3; // Platinum
        if (score >= 85) return 2; // Gold
        if (score >= 75) return 1; // Silver
        return 0; // Bronze
    }

    /**
     * @dev Get milestone by bootcamp and milestone ID
     * @param bootcampId Bootcamp ID
     * @param milestoneId Milestone ID
     * @return milestone The milestone struct
     */
    function _getMilestone(uint256 bootcampId, uint256 milestoneId) 
        private 
        view 
        returns (Milestone memory milestone) 
    {
        Milestone[] memory milestones = _bootcampMilestones[bootcampId];
        for (uint256 i = 0; i < milestones.length; i++) {
            if (milestones[i].id == milestoneId) {
                return milestones[i];
            }
        }
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @notice Get student information
     * @param studentAddress Address of the student
     * @return student Student struct
     */
    function getStudent(address studentAddress) 
        external 
        view 
        returns (Student memory student) 
    {
        return _students[studentAddress];
    }

    /**
     * @notice Get bootcamp information
     * @param bootcampId ID of the bootcamp
     * @return bootcamp Bootcamp struct
     */
    function getBootcamp(uint256 bootcampId) 
        external 
        view 
        returns (Bootcamp memory bootcamp) 
    {
        return _bootcamps[bootcampId];
    }

    /**
     * @notice Get all milestones for a bootcamp
     * @param bootcampId ID of the bootcamp
     * @return milestones Array of milestone structs
     */
    function getBootcampMilestones(uint256 bootcampId) 
        external 
        view 
        returns (Milestone[] memory milestones) 
    {
        return _bootcampMilestones[bootcampId];
    }

    /**
     * @notice Get all bootcamps a student is enrolled in
     * @param student Address of the student
     * @return bootcampIds Array of bootcamp IDs
     */
    function getStudentBootcamps(address student) 
        external 
        view 
        returns (uint256[] memory bootcampIds) 
    {
        return _studentBootcamps[student];
    }

    /**
     * @notice Check if student is enrolled in bootcamp
     * @param student Student address
     * @param bootcampId Bootcamp ID
     * @return enrolled True if enrolled
     */
    function isEnrolled(address student, uint256 bootcampId) 
        external 
        view 
        returns (bool enrolled) 
    {
        return _enrollments[student][bootcampId];
    }

    /**
     * @notice Check if milestone is completed by student
     * @param student Student address
     * @param bootcampId Bootcamp ID
     * @param milestoneId Milestone ID
     * @return completed True if completed
     */
    function isMilestoneCompleted(
        address student, 
        uint256 bootcampId, 
        uint256 milestoneId
    ) 
        external 
        view 
        returns (bool completed) 
    {
        return _completedMilestones[student][bootcampId][milestoneId];
    }

    /**
     * @notice Get current ETH/USD price from Chainlink (if available)
     * @return price Current ETH price in USD (8 decimals)
     * @return timestamp Last update timestamp
     */
    function getETHPrice() 
        external 
        view 
        returns (int256 price, uint256 timestamp) 
    {
        if (address(_priceFeed) == address(0)) {
            return (0, 0);
        }

        (, price, , timestamp, ) = _priceFeed.latestRoundData();
    }

    // ============ ADMIN FUNCTIONS ============

    /**
     * @notice Set external contract addresses
     * @param contractType Type of contract
     * @param contractAddress New contract address
     */
    function setContract(
        string calldata contractType, 
        address contractAddress
    ) 
        external 
        onlyRole(ADMIN_ROLE)
        onlyValidAddress(contractAddress)
    {
        bytes32 typeHash = keccak256(bytes(contractType));
        address oldAddress;

        if (typeHash == keccak256("badge")) {
            oldAddress = _badgeContract;
            _badgeContract = contractAddress;
        } else if (typeHash == keccak256("peerReview")) {
            oldAddress = _peerReviewContract;
            _peerReviewContract = contractAddress;
        } else if (typeHash == keccak256("leaderboard")) {
            oldAddress = _leaderboardContract;
            _leaderboardContract = contractAddress;
        } else if (typeHash == keccak256("mentorBoost")) {
            oldAddress = _mentorBoostContract;
            _mentorBoostContract = contractAddress;
        } else if (typeHash == keccak256("microRewards")) {
            oldAddress = _microRewardsContract;
            _microRewardsContract = contractAddress;
        }

        emit ContractUpdated(contractType, oldAddress, contractAddress);
    }

    /**
     * @notice Update platform fee
     * @param newFee New fee in basis points
     */
    function setPlatformFee(uint256 newFee) 
        external 
        onlyRole(ADMIN_ROLE) 
    {
        if (newFee > MAX_FEE) revert FeeExceedsMaximum();

        uint256 oldFee = _platformFee;
        _platformFee = newFee;

        emit PlatformFeeUpdated(oldFee, newFee);
    }

    /**
     * @notice Update treasury address
     * @param newTreasury New treasury address
     */
    function setTreasury(address payable newTreasury) 
        external 
        onlyRole(ADMIN_ROLE)
        onlyValidAddress(newTreasury)
    {
        address oldTreasury = _treasury;
        _treasury = newTreasury;

        emit TreasuryUpdated(oldTreasury, newTreasury);
    }

    /**
     * @notice Update Chainlink price feed
     * @param newPriceFeed New price feed address
     */
    function setPriceFeed(address newPriceFeed) 
        external 
        onlyRole(ADMIN_ROLE) 
    {
        _priceFeed = AggregatorV3Interface(newPriceFeed);
    }

    /**
     * @notice Grant bootcamp creator role
     * @param account Address to grant role to
     */
    function grantBootcampCreatorRole(address account) 
        external 
        onlyRole(ADMIN_ROLE)
        onlyValidAddress(account)
    {
        grantRole(BOOTCAMP_CREATOR_ROLE, account);
    }

    /**
     * @notice Grant mentor role
     * @param account Address to grant role to
     */
    function grantMentorRole(address account) 
        external 
        onlyRole(ADMIN_ROLE)
        onlyValidAddress(account)
    {
        grantRole(MENTOR_ROLE, account);
    }

    /**
     * @notice Emergency pause
     * @dev Only admin can pause/unpause
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @notice Unpause contract
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    /**
     * @notice Emergency withdrawal (only for stuck funds)
     * @param amount Amount to withdraw
     */
    function emergencyWithdraw(uint256 amount) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
        nonReentrant 
    {
        require(amount <= address(this).balance, "Insufficient balance");
        _treasury.sendValue(amount);
    }

    // ============ GETTERS FOR EXTERNAL CONTRACTS ============

    function badgeContract() external view returns (address) { return _badgeContract; }
    function peerReviewContract() external view returns (address) { return _peerReviewContract; }
    function leaderboardContract() external view returns (address) { return _leaderboardContract; }
    function mentorBoostContract() external view returns (address) { return _mentorBoostContract; }
    function microRewardsContract() external view returns (address) { return _microRewardsContract; }
    function treasury() external view returns (address) { return _treasury; }
    function platformFee() external view returns (uint256) { return _platformFee; }

    /**
     * @notice Receive function to accept ETH deposits
     * @dev Funds can be used for milestone rewards
     */
    receive() external payable {}
}

contracts/StudentBadges.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/Base64.sol";

/**
 * @title StudentBadges
 * @dev ERC721 NFT contract for SkillPays achievement badges with tiered levels
 * @notice Represents verifiable skill achievements with onchain metadata
 * @author SkillPays Team
 */
contract StudentBadges is 
    ERC721, 
    ERC721Enumerable, 
    ERC721URIStorage, 
    AccessControl, 
    Pausable, 
    ReentrancyGuard 
{
    using Strings for uint256;

    /// @dev Role identifiers
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant URI_SETTER_ROLE = keccak256("URI_SETTER_ROLE");

    /// @dev Badge level enumeration
    enum BadgeLevel { 
        BRONZE,    // 0
        SILVER,    // 1  
        GOLD,      // 2
        PLATINUM   // 3
    }

    /// @dev Badge metadata structure
    struct Badge {
        uint256 bootcampId;
        uint256 milestoneId;
        BadgeLevel level;
        uint256 earnedAt;
        string skillsProven;
        uint256 peerScore;
        bool isVerified;
        string metadataURI; // IPFS hash for additional metadata
    }

    /// @dev Skill proof structure for onchain resume
    struct SkillProof {
        string skillName;
        BadgeLevel proofLevel;
        uint256 verificationCount;
        uint256 lastUpdated;
        bool isActive;
    }

    /// @dev State variables
    mapping(uint256 => Badge) private _badges;
    mapping(address => mapping(string => SkillProof)) private _skillProofs;
    mapping(address => uint256[]) private _studentBadges;
    mapping(address => mapping(BadgeLevel => uint256)) private _levelCounts;
    mapping(address => string[]) private _studentSkills;

    /// @dev Token counter for unique IDs
    uint256 private _tokenIdCounter;

    /// @dev Base URI for metadata
    string private _baseTokenURI;

    /// @dev Events
    event BadgeMinted(
        address indexed student,
        uint256 indexed tokenId,
        uint256 indexed bootcampId,
        uint256 milestoneId,
        BadgeLevel level,
        uint256 peerScore
    );

    event BadgeLevelUpgraded(
        uint256 indexed tokenId,
        BadgeLevel oldLevel,
        BadgeLevel newLevel,
        address indexed upgrader
    );

    event SkillProofUpdated(
        address indexed student,
        string skillName,
        BadgeLevel level,
        uint256 verificationCount
    );

    event BaseURIUpdated(string oldURI, string newURI);

    /// @dev Custom errors
    error BadgeNotFound();
    error CannotDowngradeBadge();
    error InvalidSkillName();
    error InvalidBadgeLevel();
    error UnauthorizedAccess();

    /// @dev Constructor
    constructor(
        string memory name,
        string memory symbol,
        string memory baseURI
    ) ERC721(name, symbol) {
        _baseTokenURI = baseURI;

        // Set up roles
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
        _grantRole(URI_SETTER_ROLE, msg.sender);

        emit BaseURIUpdated("", baseURI);
    }

    /**
     * @notice Mint a new badge for a student
     * @param student Address of the student
     * @param bootcampId ID of the bootcamp
     * @param milestoneId ID of the milestone
     * @param level Badge level (0-3)
     * @param skillsProven Comma-separated skills proven
     * @param peerScore Peer review score (0-100)
     * @param metadataURI IPFS hash for additional metadata
     * @return tokenId The minted token ID
     */
    function mintBadge(
        address student,
        uint256 bootcampId,
        uint256 milestoneId,
        uint256 level,
        string calldata skillsProven,
        uint256 peerScore,
        string calldata metadataURI
    ) 
        external 
        onlyRole(MINTER_ROLE) 
        whenNotPaused 
        nonReentrant 
        returns (uint256 tokenId) 
    {
        if (student == address(0)) revert ERC721InvalidReceiver(student);
        if (level > uint256(BadgeLevel.PLATINUM)) revert InvalidBadgeLevel();
        if (peerScore > 100) revert InvalidBadgeLevel();

        tokenId = ++_tokenIdCounter;
        BadgeLevel badgeLevel = BadgeLevel(level);

        // Create badge record
        _badges[tokenId] = Badge({
            bootcampId: bootcampId,
            milestoneId: milestoneId,
            level: badgeLevel,
            earnedAt: block.timestamp,
            skillsProven: skillsProven,
            peerScore: peerScore,
            isVerified: peerScore >= 80,
            metadataURI: metadataURI
        });

        // Update student tracking
        _studentBadges[student].push(tokenId);
        _levelCounts[student][badgeLevel]++;

        // Update skill proofs
        _updateSkillProofs(student, skillsProven, badgeLevel);

        // Mint the NFT
        _safeMint(student, tokenId);

        // Set token URI if provided
        if (bytes(metadataURI).length > 0) {
            _setTokenURI(tokenId, metadataURI);
        }

        emit BadgeMinted(student, tokenId, bootcampId, milestoneId, badgeLevel, peerScore);
    }

    /**
     * @notice Upgrade a badge to a higher level
     * @param tokenId Token ID to upgrade
     * @param newLevel New badge level
     */
    function upgradeBadgeLevel(uint256 tokenId, uint256 newLevel) 
        external 
        onlyRole(MINTER_ROLE) 
        whenNotPaused 
    {
        if (_ownerOf(tokenId) == address(0)) revert BadgeNotFound();
        if (newLevel > uint256(BadgeLevel.PLATINUM)) revert InvalidBadgeLevel();

        Badge storage badge = _badges[tokenId];
        BadgeLevel newBadgeLevel = BadgeLevel(newLevel);

        if (newBadgeLevel <= badge.level) revert CannotDowngradeBadge();

        address owner = ownerOf(tokenId);
        BadgeLevel oldLevel = badge.level;

        // Update level counts
        _levelCounts[owner][oldLevel]--;
        _levelCounts[owner][newBadgeLevel]++;

        // Update badge level
        badge.level = newBadgeLevel;

        // Update skill proofs
        _updateSkillProofs(owner, badge.skillsProven, newBadgeLevel);

        emit BadgeLevelUpgraded(tokenId, oldLevel, newBadgeLevel, msg.sender);
    }

    /**
     * @dev Update skill proofs when badge is minted or upgraded
     * @param student Student address
     * @param skillsProven Comma-separated skills
     * @param level Badge level achieved
     */
    function _updateSkillProofs(
        address student,
        string memory skillsProven,
        BadgeLevel level
    ) private {
        string[] memory skills = _parseSkills(skillsProven);

        for (uint256 i = 0; i < skills.length; i++) {
            string memory skillName = skills[i];
            if (bytes(skillName).length == 0) continue;

            SkillProof storage proof = _skillProofs[student][skillName];

            // Add to student skills if new
            if (!proof.isActive) {
                _studentSkills[student].push(skillName);
                proof.skillName = skillName;
                proof.isActive = true;
            }

            // Update proof level if higher
            if (level > proof.proofLevel || proof.verificationCount == 0) {
                proof.proofLevel = level;
                proof.lastUpdated = block.timestamp;
            }

            proof.verificationCount++;

            emit SkillProofUpdated(student, skillName, proof.proofLevel, proof.verificationCount);
        }
    }

    /**
     * @dev Parse comma-separated skills string into array
     * @param skillsString Comma-separated skills
     * @return skills Array of individual skill names
     */
    function _parseSkills(string memory skillsString) private pure returns (string[] memory skills) {
        if (bytes(skillsString).length == 0) {
            return new string[](0);
        }

        bytes memory skillsBytes = bytes(skillsString);
        uint256 skillCount = 1;

        // Count commas to determine array size
        for (uint256 i = 0; i < skillsBytes.length; i++) {
            if (skillsBytes[i] == ',') {
                skillCount++;
            }
        }

        skills = new string[](skillCount);
        uint256 skillIndex = 0;
        uint256 start = 0;

        for (uint256 i = 0; i <= skillsBytes.length; i++) {
            if (i == skillsBytes.length || skillsBytes[i] == ',') {
                // Extract skill name
                bytes memory skillBytes = new bytes(i - start);
                for (uint256 j = start; j < i; j++) {
                    skillBytes[j - start] = skillsBytes[j];
                }

                // Trim whitespace and store
                skills[skillIndex] = _trim(string(skillBytes));
                skillIndex++;
                start = i + 1;
            }
        }
    }

    /**
     * @dev Trim whitespace from string
     * @param str String to trim
     * @return trimmed Trimmed string
     */
    function _trim(string memory str) private pure returns (string memory trimmed) {
        bytes memory strBytes = bytes(str);
        if (strBytes.length == 0) return str;

        uint256 start = 0;
        uint256 end = strBytes.length;

        // Find first non-space character
        while (start < end && strBytes[start] == ' ') {
            start++;
        }

        // Find last non-space character
        while (end > start && strBytes[end - 1] == ' ') {
            end--;
        }

        if (start >= end) return "";

        bytes memory trimmedBytes = new bytes(end - start);
        for (uint256 i = start; i < end; i++) {
            trimmedBytes[i - start] = strBytes[i];
        }

        return string(trimmedBytes);
    }

    /**
     * @notice Generate comprehensive onchain resume for a student
     * @param student Student address
     * @return badgeIds Array of badge token IDs
     * @return skills Array of skill names  
     * @return skillLevels Array of skill levels
     * @return skillVerificationCounts Array of verification counts
     * @return totalBadges Total number of badges
     * @return reputationScore Overall reputation score
     */
    function generateOnchainResume(address student) 
        external 
        view 
        returns (
            uint256[] memory badgeIds,
            string[] memory skills,
            BadgeLevel[] memory skillLevels,
            uint256[] memory skillVerificationCounts,
            uint256 totalBadges,
            uint256 reputationScore,
            uint256 bronzeBadges,
            uint256 silverBadges,
            uint256 goldBadges,
            uint256 platinumBadges
        ) 
    {
        badgeIds = _studentBadges[student];

        // Get student skills
        string[] memory studentSkills = _studentSkills[student];
        skills = new string[](studentSkills.length);
        skillLevels = new BadgeLevel[](studentSkills.length);
        skillVerificationCounts = new uint256[](studentSkills.length);

        for (uint256 i = 0; i < studentSkills.length; i++) {
            skills[i] = studentSkills[i];
            SkillProof memory proof = _skillProofs[student][studentSkills[i]];
            skillLevels[i] = proof.proofLevel;
            skillVerificationCounts[i] = proof.verificationCount;
        }

        totalBadges = badgeIds.length;
        reputationScore = _calculateReputationScore(student);

        // Badge level counts
        bronzeBadges = _levelCounts[student][BadgeLevel.BRONZE];
        silverBadges = _levelCounts[student][BadgeLevel.SILVER];
        goldBadges = _levelCounts[student][BadgeLevel.GOLD];
        platinumBadges = _levelCounts[student][BadgeLevel.PLATINUM];
    }

    /**
     * @dev Calculate reputation score based on badges earned
     * @param student Student address
     * @return score Total reputation score
     */
    function _calculateReputationScore(address student) private view returns (uint256 score) {
        score += _levelCounts[student][BadgeLevel.BRONZE] * 10;
        score += _levelCounts[student][BadgeLevel.SILVER] * 25;
        score += _levelCounts[student][BadgeLevel.GOLD] * 50;
        score += _levelCounts[student][BadgeLevel.PLATINUM] * 100;
    }

    /**
     * @notice Generate SVG-based onchain metadata for a badge
     * @param tokenId Token ID
     * @return metadata Base64-encoded JSON metadata
     */
    function generateOnchainMetadata(uint256 tokenId) 
        public 
        view 
        returns (string memory metadata) 
    {
        if (_ownerOf(tokenId) == address(0)) revert BadgeNotFound();

        Badge memory badge = _badges[tokenId];
        string memory levelName = _getLevelName(badge.level);
        string memory svg = _generateBadgeSVG(badge);

        // Create JSON metadata
        string memory json = string(abi.encodePacked(
            '{"name":"SkillPays Badge #', tokenId.toString(), 
            '","description":"Verified skill achievement badge',
            '","level":"', levelName,
            '","skills":"', badge.skillsProven,
            '","bootcamp_id":', badge.bootcampId.toString(),
            '","milestone_id":', badge.milestoneId.toString(),
            '","peer_score":', badge.peerScore.toString(),
            '","earned_at":', badge.earnedAt.toString(),
            '","verified":', badge.isVerified ? 'true' : 'false',
            '","image":"data:image/svg+xml;base64,', Base64.encode(bytes(svg)),
            '"}'
        ));

        return string(abi.encodePacked(
            'data:application/json;base64,',
            Base64.encode(bytes(json))
        ));
    }

    /**
     * @dev Generate SVG for badge visualization
     * @param badge Badge data
     * @return svg SVG string
     */
    function _generateBadgeSVG(Badge memory badge) private pure returns (string memory svg) {
        string memory color = _getLevelColor(badge.level);
        string memory levelName = _getLevelName(badge.level);

        svg = string(abi.encodePacked(
            '<svg width="200" height="200" xmlns="http://www.w3.org/2000/svg">',
            '<defs><linearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">',
            '<stop offset="0%" style="stop-color:', color, ';stop-opacity:1" />',
            '<stop offset="100%" style="stop-color:#ffffff;stop-opacity:0.3" />',
            '</linearGradient></defs>',
            '<circle cx="100" cy="100" r="90" fill="url(#grad)" stroke="#333" stroke-width="4"/>',
            '<text x="100" y="80" text-anchor="middle" font-family="Arial" font-size="14" font-weight="bold" fill="#333">',
            'SkillPays</text>',
            '<text x="100" y="100" text-anchor="middle" font-family="Arial" font-size="12" font-weight="bold" fill="#333">',
            levelName, '</text>',
            '<text x="100" y="120" text-anchor="middle" font-family="Arial" font-size="10" fill="#666">',
            'Score: ', badge.peerScore.toString(), '</text>',
            '<text x="100" y="140" text-anchor="middle" font-family="Arial" font-size="8" fill="#999">',
            badge.isVerified ? 'VERIFIED' : 'PENDING', '</text>',
            '</svg>'
        ));
    }

    /**
     * @dev Get level name string
     * @param level Badge level
     * @return name Level name
     */
    function _getLevelName(BadgeLevel level) private pure returns (string memory name) {
        if (level == BadgeLevel.PLATINUM) return "PLATINUM";
        if (level == BadgeLevel.GOLD) return "GOLD";
        if (level == BadgeLevel.SILVER) return "SILVER";
        return "BRONZE";
    }

    /**
     * @dev Get level color for SVG
     * @param level Badge level
     * @return color Hex color code
     */
    function _getLevelColor(BadgeLevel level) private pure returns (string memory color) {
        if (level == BadgeLevel.PLATINUM) return "#E5E4E2";
        if (level == BadgeLevel.GOLD) return "#FFD700";
        if (level == BadgeLevel.SILVER) return "#C0C0C0";
        return "#CD7F32";
    }

    // ============ VIEW FUNCTIONS ============

    function getBadgeDetails(uint256 tokenId) external view returns (Badge memory) {
        if (_ownerOf(tokenId) == address(0)) revert BadgeNotFound();
        return _badges[tokenId];
    }

    function getStudentBadges(address student) external view returns (uint256[] memory) {
        return _studentBadges[student];
    }

    function getStudentLevelCounts(address student) external view returns (
        uint256 bronze, uint256 silver, uint256 gold, uint256 platinum
    ) {
        return (
            _levelCounts[student][BadgeLevel.BRONZE],
            _levelCounts[student][BadgeLevel.SILVER],
            _levelCounts[student][BadgeLevel.GOLD],
            _levelCounts[student][BadgeLevel.PLATINUM]
        );
    }

    function getSkillProof(address student, string memory skillName) 
        external view returns (SkillProof memory) {
        return _skillProofs[student][skillName];
    }

    function getStudentSkills(address student) external view returns (string[] memory) {
        return _studentSkills[student];
    }

    // ============ ADMIN FUNCTIONS ============

    function setBaseURI(string calldata newBaseURI) 
        external 
        onlyRole(URI_SETTER_ROLE) 
    {
        string memory oldURI = _baseTokenURI;
        _baseTokenURI = newBaseURI;
        emit BaseURIUpdated(oldURI, newBaseURI);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // ============ OVERRIDES ============

    function _baseURI() internal view override returns (string memory) {
        return _baseTokenURI;
    }

    function tokenURI(uint256 tokenId) 
        public 
        view 
        override(ERC721, ERC721URIStorage) 
        returns (string memory) 
    {
        if (_ownerOf(tokenId) == address(0)) revert BadgeNotFound();

        // Return custom URI if set, otherwise generate onchain metadata
        string memory uri = super.tokenURI(tokenId);
        if (bytes(uri).length > 0) {
            return uri;
        }

        return generateOnchainMetadata(tokenId);
    }

    function _update(address to, uint256 tokenId, address auth)
        internal
        override(ERC721, ERC721Enumerable)
        whenNotPaused
        returns (address)
    {
        return super._update(to, tokenId, auth);
    }

    function _increaseBalance(address account, uint128 value)
        internal
        override(ERC721, ERC721Enumerable)
    {
        super._increaseBalance(account, value);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Enumerable, ERC721URIStorage, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

